# ===================== Claude-F view cache (residual) =====================
import weakref as _cf_vc_weakref
_CF_VIEW_TAB = {}
_CF_VIEW_EPOCH = [0]
_CF_VIEW_CAP = 4096   # v3.1: a full table stops caching new bases (never clears mid-life)
_CF_KEEP = []          # Claude-F KEEP: setup intermediates held until Estimator.setup returns (one free round trip)
_CF_KEEP_ON = [False]


def _cf_keep(*xs):
    if _CF_KEEP_ON[0]:
        _CF_KEEP.extend(xs)


def _cf_keep_rs(x, shape):
    r = fnp.reshape(x, shape)
    _cf_keep(x)
    return r


def _cf_vc_norm1(k):
    t = type(k)
    if t is int:
        return k
    if t is slice:
        return ('s', k.start, k.stop, k.step)
    if k is Ellipsis:
        return ('E',)
    if k is None:
        return ('N',)
    raise TypeError


def _cf_vc_norm(key, _int=int, _slice=slice, _tuple=tuple, _E=Ellipsis):
    """Claude-F RSD1: same keys as tuple(_cf_vc_norm1(k) for k in key), without a call per element."""
    if type(key) is _tuple:
        if len(key) == 2:
            a, b = key
            if type(a) is _slice and type(b) is _slice:
                return (('s', a.start, a.stop, a.step), ('s', b.start, b.stop, b.step))
        out = []
        ap = out.append
        for k in key:
            t = type(k)
            if t is _slice:
                ap(('s', k.start, k.stop, k.step))
            elif t is _int:
                ap(k)
            elif k is _E:
                ap(('E',))
            elif k is None:
                ap(('N',))
            else:
                raise TypeError
        return _tuple(out)
    return _cf_vc_norm1(key)


_CF_RSD1 = True   # Claude-F residual diet v1 (byte-identical client-Python cuts)


def _cf_vc_entry(base):
    bid = id(base)
    ent = _CF_VIEW_TAB.get(bid)
    if ent is not None and ent[0]() is base and ent[1] == _CF_VIEW_EPOCH[0]:
        return ent
    if len(_CF_VIEW_TAB) >= _CF_VIEW_CAP:
        return None
    try:
        def _drop(ref, bid=bid):
            e = _CF_VIEW_TAB.get(bid)
            if e is not None and e[0] is ref:
                del _CF_VIEW_TAB[bid]
        ent = [_cf_vc_weakref.ref(base, _drop), _CF_VIEW_EPOCH[0], {}]
    except TypeError:
        return None
    _CF_VIEW_TAB[bid] = ent
    return ent


def _cf_view(base, key):
    """base[key] for a basic key, cached per live base object."""
    try:
        nk = _cf_vc_norm(key)
    except TypeError:
        return base[key]
    ent = _CF_VIEW_TAB.get(id(base))   # Claude-F RSD1: the hit test of _cf_vc_entry, inline
    if ent is None or ent[0]() is not base or ent[1] != _CF_VIEW_EPOCH[0]:
        ent = _cf_vc_entry(base)
        if ent is None:
            return base[key]
    v = ent[2].get(nk)
    if v is None:
        v = ent[2][nk] = base[key]
    return v


def _cf_T(base):
    """base.T cached per live base object."""
    ent = _cf_vc_entry(base)
    if ent is None:
        return base.T
    v = ent[2].get('T')
    if v is None:
        v = ent[2]['T'] = base.T
    return v


_CF_FVC = True   # Claude-F FVC1: F-side view cache (bit-identical); CF_FVC=0 is read after `import os as _os`
_CF_FVC_MAX_VIEWS_PER_BASE = 64   # Claude-R FVCCAP (Codex-B FVC-LIFE-1 A): FV views kept per base; 0 = none
_CF_FVC_INFO = {'capped': 0}


def _cfv(base, key):
    """base[key], cached per live base when the view has pairwise different dimensions (never a symmetric-tag target)."""
    if not _CF_FVC:
        return base[key]
    try:
        nk = ('FV', _cf_vc_norm(key))
    except TypeError:
        return base[key]
    ent = _CF_VIEW_TAB.get(id(base))   # Claude-F RSD1: the hit test of _cf_vc_entry, inline
    if ent is None or ent[0]() is not base or ent[1] != _CF_VIEW_EPOCH[0]:
        ent = _cf_vc_entry(base)
        if ent is None:
            return base[key]
    v = ent[2].get(nk)
    if v is not None:
        return v                    # Claude-R FVCCAP: a stored live view is never changed or evicted
    fv_count = sum(1 for k_ in ent[2] if type(k_) is tuple and len(k_) == 2 and type(k_[0]) is str and k_[0] == 'FV')
    if fv_count >= _CF_FVC_MAX_VIEWS_PER_BASE:
        _CF_FVC_INFO['capped'] += 1
        return base[key]            # the uncached path; the view is not kept
    v = base[key]
    shp = tuple(v.shape)
    if len(set(shp)) == len(shp):
        ent[2][nk] = v
    return v


def _cfv_tp(base, axes=None):
    """Claude-F FVC5: fnp.transpose(base, axes), cached per live base when the result has pairwise different dimensions."""
    if not _CF_FVC:
        return fnp.transpose(base, axes)
    ent = _cf_vc_entry(base)
    if ent is None:
        return fnp.transpose(base, axes)
    k = ('FVT', None if axes is None else tuple(int(a) for a in axes))
    v = ent[2].get(k)
    if v is None:
        v = fnp.transpose(base, axes)
        shp = tuple(v.shape)
        if len(set(shp)) == len(shp):
            ent[2][k] = v
    return v


def _cfv_sw(base, i, j):
    """Claude-F FVC5: fnp.swapaxes(base, i, j), same rule."""
    if not _CF_FVC:
        return fnp.swapaxes(base, i, j)
    ent = _cf_vc_entry(base)
    if ent is None:
        return fnp.swapaxes(base, i, j)
    k = ('FVS', int(i), int(j))
    v = ent[2].get(k)
    if v is None:
        v = fnp.swapaxes(base, i, j)
        shp = tuple(v.shape)
        if len(set(shp)) == len(shp):
            ent[2][k] = v
    return v


def _cf_reshape4(Q, shp, _reshape):
    """tuple(_reshape(q_, shp) for q_ in Q), each result cached per live quadrant object -- only if it is a view."""
    out = []
    for q_ in Q:
        ent = _cf_vc_entry(q_)
        if ent is None:
            out.append(_reshape(q_, shp)); continue
        key = ('R', shp)
        v = ent[2].get(key)
        if v is None:
            v = _reshape(q_, shp)
            if bool(fnp.shares_memory(v, q_)):
                ent[2][key] = v
        out.append(v)
    return tuple(out)


def _cf_quarters(array, h, w):
    ent = _CF_VIEW_TAB.get(id(array))   # Claude-F RSD1: the hit test of _cf_vc_entry, inline
    if ent is None or ent[0]() is not array or ent[1] != _CF_VIEW_EPOCH[0]:
        ent = _cf_vc_entry(array)
    if ent is None:
        return (array[..., :h, :w], array[..., :h, w:], array[..., h:, :w], array[..., h:, w:])
    q = ent[2].get(('Q', h, w))
    if q is None:
        q = ent[2][('Q', h, w)] = (array[..., :h, :w], array[..., :h, w:], array[..., h:, :w], array[..., h:, w:])
    return q


def _ci_lzq(eng, array, owner, cat):
    """Claude-I LZQ: register a setup-owned pack without building its quadrants (eng._quarters builds them on first use)."""
    if not (_CI_LZQ_B or (_CI_LZQ_A and cat == 'A')) or not getattr(eng, "_bd_trim_setup", False):
        return eng._remember_quarters_only(array, owner)
    record = eng._layouts.get(id(array))
    if record is not None and record[0] is array:
        return
    eng._scratch_owned_views[id(array)] = (array, owner)
    if id(array) not in owner:
        owner.append(id(array))


class _CiSd3Bundles(dict):
    """Claude-I SD3: a view table whose missing entry is made by .make(key) on first read and kept."""
    make = None

    def __missing__(self, key):
        if self.make is None:
            raise KeyError(key)
        v = self[key] = self.make(key)
        return v


def _cf_r48_blocks(A):
    """_cb_r48_blocks4(A[0, 0]) cached per live operand object (basic slices: always views)."""
    ent = _cf_vc_entry(A)
    if ent is None:
        return _cb_r48_blocks4(A[0, 0])
    v = ent[2].get('B4')
    if v is None:
        A00 = A[0, 0]
        _cf_keep(A00)
        v = ent[2]['B4'] = _cb_r48_blocks4(A00)
    return v


def _cf_split_only(old, new):
    """Claude-F NEST1: True when `new` only splits the axes of `old` (consecutive runs multiply to each old axis)."""
    i, m = 0, len(new)
    for d in old:
        p = 1
        while p < d and i < m:
            p *= int(new[i]); i += 1
        if p != d:
            return False
    return all(int(x) == 1 for x in new[i:])


def _cf_nest_view(q_, shp, _reshape):
    """_reshape(q_, shp) cached per live quarter object, only when the result is a view (copies are recomputed).
    The view test (one shares_memory round trip) runs on the SECOND sighting of an object, so operands that are
    fresh on every call never pay it."""
    ent = _cf_vc_entry(q_)
    if ent is None:
        return _reshape(q_, shp)
    key = ('N', shp)
    v = ent[2].get(key)
    if v is None:
        if _cf_split_only(tuple(q_.shape), tuple(shp)):   # Claude-F NEST1: splitting axes only is always a view
            v = ent[2][key] = _reshape(q_, shp)
            return v
        ent[2][key] = True                       # first sighting: remember, no round trip
        return _reshape(q_, shp)
    if v is True:
        v = _reshape(q_, shp)
        ent[2][key] = v if bool(fnp.shares_memory(v, q_)) else False
        return v
    if v is False:
        return _reshape(q_, shp)
    return v
# =================== end Claude-F view cache ===================

