# ======================= Claude-M HEXLIT: hex-packed numeric literals (values bit-identical) =======================
def _hxl_n(h, t, shape):
    v = memoryview(bytes.fromhex(h)).cast(t).tolist()
    for c in reversed(shape[1:]):
        v = [v[i:i + c] for i in range(0, len(v), c)]
    return v


def _hxl_t(h, t, shape):
    v = tuple(memoryview(bytes.fromhex(h)).cast(t).tolist())
    for c in reversed(shape[1:]):
        v = tuple(v[i:i + c] for i in range(0, len(v), c))
    return v
# ===================== end HEXLIT helpers =====================

