# ======================= Claude-F AB2E: pair-group einsum without its (t, n, n) temporary (2026-10-16) =======================
_CF_AB2E = _os.environ.get("CF_AB2E", "1") != "0"
_CF_AB2E_TAB = {}


def _cf_ab2e_disjoint(spans):
    """True when the pair-group spans are disjoint, increasing slices (each group owns its slice of the AB stack)."""
    e = _CF_AB2E_TAB.get(id(spans))
    if e is not None and e[0] is spans:
        return e[1]
    ok, last = True, 0
    try:
        for lo, hi in spans:
            if not (type(lo) is int and type(hi) is int and last <= lo < hi):
                ok = False; break
            last = hi
    except Exception:
        ok = False
    _CF_AB2E_TAB[id(spans)] = (spans, ok)
    return ok
# ===================== end Claude-F AB2E =====================


# ======================= Claude-F AB2W: AB2 route loop with less memory traffic (2026-10-16) =======================
_CF_AB2W = _os.environ.get("CF_AB2W", "1") != "0"
_CF_AB2W_TAB = {}                       # id(route tuple) -> (route tuple, plan)
_CF_AB2W_CONTIG = frozenset(("d21T",))  # keys bound to a transposed view; a copy route makes them contiguous


def _cf_ab2w_plan(payload):
    """[(0, src, None) copy | (1, a, b) multiply], src/a/b = b2 key or an earlier slot index; None if not applicable."""
    e = _CF_AB2W_TAB.get(id(payload))
    if e is not None and e[0] is payload:
        return e[1]
    plan, first, copied = [], {}, {}
    for t, route in enumerate(payload):
        if not (isinstance(route, tuple) and len(route) == 2 and isinstance(route[0], str)
                and (route[1] is None or isinstance(route[1], str))):
            _CF_AB2W_TAB[id(payload)] = (payload, None)
            return None
        a, b = route
        if route in first:
            plan.append((0, first[route], None))
            continue
        first[route] = t
        if b is None:
            plan.append((0, a, None))
            copied.setdefault(a, t)
        else:
            plan.append((1, copied.get(a, a) if a in _CF_AB2W_CONTIG else a,
                         copied.get(b, b) if b in _CF_AB2W_CONTIG else b))
    plan = tuple(plan)
    _CF_AB2W_TAB[id(payload)] = (payload, plan)
    return plan
# ===================== end Claude-F AB2W =====================

