def _cb_r48_decode(rows):
    values = {'A': -2.0, 'B': -1.0, 'C': -0.5,
              'c': 0.5, 'b': 1.0, 'a': 2.0}
    return tuple(tuple((index, values[value]) for index, value in enumerate(row)
                       if value != '.') for row in rows)

