def _cb_r48_form(inputs, outputs, coeffs, start):
    """Form eight rank-48 operands without retaining the other forty."""
    for output, row in zip(outputs, coeffs[start:start + _CB_R48_CHUNK]):
        halves = tuple(term for term in row if abs(term[1]) == 0.5)
        wholes = tuple(term for term in row if abs(term[1]) == 1.0)
        if halves:
            index, coefficient = halves[0]
            if coefficient > 0:
                fnp.copyto(output, inputs[index])
            else:
                fnp.negative(inputs[index], out=output)
            for index, coefficient in halves[1:]:
                if coefficient > 0:
                    fnp.add(output, inputs[index], out=output)
                else:
                    fnp.subtract(output, inputs[index], out=output)
            fnp.divide(output, _CB_R48_TWO, out=output)
        else:
            index, coefficient = wholes[0]
            if coefficient > 0:
                fnp.copyto(output, inputs[index])
            else:
                fnp.negative(inputs[index], out=output)
            wholes = wholes[1:]
        for index, coefficient in wholes:
            if coefficient > 0:
                fnp.add(output, inputs[index], out=output)
            else:
                fnp.subtract(output, inputs[index], out=output)

def _cb_r48_post_chunk(products, outputs, start, initialized):
    """Accumulate one contiguous eight-product chunk in global product order."""
    stop = start + _CB_R48_CHUNK
    for output_index, row in enumerate(_CB_R48_POST_COEFFS):
        output = outputs[output_index]
        for product_index, coefficient in row:
            if product_index < start or product_index >= stop:
                continue
            product = products[product_index - start]
            for _ in range(int(abs(coefficient))):
                if not initialized[output_index]:
                    if coefficient > 0:
                        fnp.copyto(output, product)
                    else:
                        fnp.negative(product, out=output)
                    initialized[output_index] = True
                elif coefficient > 0:
                    fnp.add(output, product, out=output)
                else:
                    fnp.subtract(output, product, out=output)

# Claude-P setup-RPC batching helpers: identical numpy views, one remote call instead of one per view.
# Active ONLY inside Estimator.setup (flag set by the wrapper appended at the end of the module), so predict keeps
# the original per-view slicing and its op_log / call count / residual are untouched.
_CP_IN_SETUP = [False]


def _cp_rows(slab):
    if _CP_IN_SETUP[0] and slab.ndim >= 2 and slab.shape[0] > 0:
        return tuple(fnp.unstack(slab))
    return tuple(slab[i] for i in range(slab.shape[0]))


def _cp_split7(flat, P):
    if _CP_IN_SETUP[0] and P > 0 and flat.ndim >= 2 and flat.shape[1] == 7 * P:
        return tuple(fnp.split(flat, 7, axis=1))
    return tuple(flat[:, j*P:(j+1)*P] for j in range(7))


def _cp_quarters(array):
    H, W = array.shape[-2], array.shape[-1]
    h, w = H // 2, W // 2
    if False and _CP_IN_SETUP[0] and h > 0 and w > 0 and H == 2 * h and W == 2 * w:   # Claude-P v2: 3 splits cost more than 4 getitems over IPC
        top, bottom = fnp.split(array, 2, axis=-2)
        a, b = fnp.split(top, 2, axis=-1)
        c, d = fnp.split(bottom, 2, axis=-1)
        return (a, b, c, d)
    return _cf_quarters(array, h, w)


def _cp_grid_last2(array, rows, columns):
    """Row-major blocks over the last two axes (== array[..., i*h:(i+1)*h, j*w:(j+1)*w])."""
    H, W = array.shape[-2], array.shape[-1]
    h, w = H // rows, W // columns
    if (_CP_IN_SETUP[0] or _CI_FP1_GRID) and h > 0 and w > 0 and H == rows * h and W == columns * w:
        out = []
        bands = fnp.split(array, rows, axis=-2)
        _cf_keep(*bands)
        for band in bands:
            out.extend(fnp.split(band, columns, axis=-1))
        return tuple(out)
    return tuple(array[..., i * h:(i + 1) * h, j * w:(j + 1) * w]
                 for i in range(rows) for j in range(columns))


class _CPPrefixes:
    """Claude-P v2: lazy tuple of prefix views base[:i] (same view as the eager tuple, created on first index)."""
    __slots__ = ('base', 'n', 'cache')

    def __init__(self, base, n):
        self.base = base; self.n = n; self.cache = {}

    def __len__(self):
        return self.n

    def __getitem__(self, i):
        i = int(i)
        if not 0 <= i < self.n:
            raise IndexError(i)
        v = self.cache.get(i)
        if v is None:
            v = self.base[:i]; self.cache[i] = v
        return v


def _cb_r48_blocks4(array):
    if array.ndim == 2:
        return _cp_grid_last2(array, 4, 4)
    h, w = array.shape[-2] // 4, array.shape[-1] // 4
    return tuple(array[i*h:(i+1)*h, j*w:(j+1)*w] for i in range(4) for j in range(4))

def _cb_r48_run(owner, X, Y, out, lev, plan):
    L4, R4, P4, LW, RW, PW, rows = plan
    LO, RO, PI, LW_rows, RW_rows, PW_rows = rows
    _cb_r48_204_left(_cf_r48_blocks(X), LO, LW_rows)
    _cb_r48_204_right(_cf_r48_blocks(Y), RO, RW_rows)
    owner.mm(L4, R4, P4, lev - 2)
    _cb_r48_204_post(PI, _cf_r48_blocks(out), PW_rows)
    return out

def _cb_r48_pick_v3(leaders, h, q):
    candidates = tuple((H * Q, array) for H, Q, array in leaders
                       if H >= h and Q >= q)
    if not candidates:
        raise RuntimeError("R48 top view exceeds Pareto leaders")
    return _ci_sd_v(min(candidates, key=lambda row: row[0])[1], (Ellipsis, slice(None, h), slice(None, q)))

if _CF_B_R48_CHILD_TRIM:
    # Geometry metadata only.  No owner, backing, view, or root input is retained.
    _CF_B_R48_CHILD_ROWS = {
        (role, P, paired, shape): (role, P, shape, paired)
        for role, P, shape, paired in _CB_R48_USED_CHILD_GEOMETRY
    }

    def _cf_b_r48_source(row):
        role, P, shape, paired = row
        oldP = {48: 49, 336: 343, 2352: 2401, 16464: 16807}[P]
        candidates = tuple(candidate for candidate in _STAGE1_SCRATCH_GEOMETRY
                           if candidate[0] == role and candidate[1] == oldP
                           and candidate[3] == paired
                           and candidate[2][0] >= shape[0]
                           and candidate[2][-2:] == shape[-2:])
        if not candidates:
            raise RuntimeError("Missing exact c9 child alias")
        return min(candidates, key=lambda candidate: math.prod(candidate[2]))

    def _cf_b_r48_make(owner, row, source):
        role, P, shape, paired = row
        was_lazy = _CF_COLS_LAZY[0]
        _CF_COLS_LAZY[0] = True
        try:
            source_value = owner._workspace((role, source[1]), source[2], paired)
        finally:
            _CF_COLS_LAZY[0] = was_lazy
        if paired:
            flat = source_value[1][:shape[0], :7 * P]
            return (None, flat, _CF_COLS_LATER)
        return source_value[:shape[0], :P]

    def _cf_b_r48_order(role_key, views):
        # Parent insertion order is inventory first, then later aliases.  In
        # particular min(enclosing, key=prod) must retain its original tie break.
        ordered = {}
        for role, P, shape, paired in _CB_R48_USED_CHILD_GEOMETRY:
            if (role, P) == role_key and (paired, shape) in views:
                ordered[(paired, shape)] = views[(paired, shape)]
        for view_key, value in views.items():
            if view_key not in ordered:
                ordered[view_key] = value
        views.clear()
        views.update(ordered)

    def _cf_b_r48_restore(owner, role_key, view_key, entry):
        # Invoked only after an ordinary cache miss.  A private E1 pool copy has
        # the same role/oldP backing relation and needs no owner backreference.
        role, P = role_key
        paired, shape = view_key
        row = _CF_B_R48_CHILD_ROWS.get((role, P, paired, shape))
        if row is None:
            return None
        source = _cf_b_r48_source(row)
        source_entry = owner.pool.get((role, source[1]))
        if (entry is None or source_entry is None
                or entry[0] is not source_entry[0]
                or source_entry[0].size < math.prod(source[2])):
            # Growth/disable-coloring invalidates the alias relationship; keep
            # the parent's normal workspace behavior in that independent pool.
            return None
        value = _cf_b_r48_make(owner, row, source)
        entry[1][view_key] = value
        _cf_b_r48_order(role_key, entry[1])
        return value

    def _cf_b_r48_restore_prefix(owner, role_key, view_key, entry):
        # _workspace uses the FIRST same-trailing-shape prefix, not the
        # minimum-product enclosing crop used by _cc_r48_20_alias.  Original
        # inventory rows precede every later alias, so the first eligible
        # inventory row wins even if a later cached prefix is already present.
        paired, shape = view_key
        for role, P, other_shape, other_paired in _CB_R48_USED_CHILD_GEOMETRY:
            if ((role, P) == role_key and other_paired == paired
                    and other_shape[1:] == shape[1:]
                    and other_shape[0] >= shape[0]):
                winner = (other_paired, other_shape)
                if winner not in entry[1]:
                    # A grown/independent pool fails restore's backing check
                    # and continues with the ordinary parent prefix lookup.
                    _cf_b_r48_restore(owner, role_key, winner, entry)
                return

    def _cf_b_r48_restore_enclosing(owner, role, P, shape, paired, entry):
        # Recreate only the winner that the parent's full inventory would have
        # selected.  Original rows precede later aliases, including size ties.
        oldP = {48: 49, 336: 343, 2352: 2401, 16464: 16807}.get(P)
        source_entry = owner.pool.get((role, oldP))
        if (entry is None or source_entry is None
                or entry[0] is not source_entry[0]):
            # An independent/grown pool no longer has the original virtual
            # inventory.  Its actual cached enclosing views remain authoritative.
            return
        virtual = {}
        for r, p, s, is_paired in _CB_R48_USED_CHILD_GEOMETRY:
            if (r, p) == (role, P):
                virtual[(is_paired, s)] = None
        for view_key in entry[1]:
            if view_key not in virtual:
                virtual[view_key] = None
        enclosing = tuple(view_key for view_key in virtual
                          if view_key[0] == paired
                          and view_key[1][0] >= shape[0]
                          and view_key[1][-2] >= shape[-2]
                          and view_key[1][-1] >= shape[-1])
        if not enclosing:
            return
        winner = min(enclosing, key=lambda view_key: math.prod(view_key[1]))
        if winner not in entry[1]:
            # Restore also checks the original source's capacity.  If that
            # relationship no longer holds, retain parent actual-view fallback.
            _cf_b_r48_restore(owner, (role, P), winner, entry)

    def _cf_b_r48_prepare(owner):
        # Read the final module table during setup.  PRUNE v2/v3 may replace it
        # after its literal declaration; a frozen import-time root set is wrong.
        required = set()
        uncertain = False
        for kind, xs, ys, lev in _STAGE1_CALLPLAN_ROOTS:
            if xs[1] not in _CB_R48_CHILD_P:
                continue
            if (kind != "mm" or xs[:2] != ys[:2] or xs[0] != 1
                    or xs[3] != ys[2]):
                uncertain = True
                break
            required.update(_be1_geometry(xs[2], xs[3], ys[3], lev, xs[1]))
        if uncertain:
            required.update(_CB_R48_USED_CHILD_GEOMETRY)

        grouped = {}
        eager = 0
        for row in _CB_R48_USED_CHILD_GEOMETRY:
            role, P, shape, paired = row
            source = _cf_b_r48_source(row)
            source_entry = owner.pool[(role, source[1])]
            views, backing = grouped.setdefault((role, P), ({}, source_entry[0]))
            if backing is not source_entry[0]:
                raise RuntimeError("R48 alias group changed backing")
            if row in required:
                views[(paired, shape)] = _cf_b_r48_make(owner, row, source)
                eager += 1
        for key, (views, backing) in grouped.items():
            # Empty metadata groups still preserve _cf_lazy_fits capacity and
            # _cc_r48_20_alias's role/P indexing and same-role backing identity.
            owner.pool[key] = (backing, views, [])
        total = len(_CB_R48_USED_CHILD_GEOMETRY)
        owner._r48_setupfast_counts = (total, len(grouped), 0)
        owner._cf_b_r48_child_counts = (total, eager, total - eager, len(grouped))

def _cb_prepare_r48_child_views_v3(owner):
    if _CF_B_R48_CHILD_TRIM:
        return _cf_b_r48_prepare(owner)
    # The selected 14 P48 roots need only the literal inventory below.  Each
    # child matrix is a prefix of the same-role c9 P49/P343/P2401/P16807 view
    # with identical trailing geometry.  These are metadata slices only.
    base_p = {48: 49, 336: 343, 2352: 2401, 16464: 16807}
    grouped = {}
    for role, P, shape, paired in _CB_R48_USED_CHILD_GEOMETRY:
        candidates = tuple(row for row in _STAGE1_SCRATCH_GEOMETRY
                           if row[0] == role and row[1] == base_p[P]
                           and row[3] == paired and row[2][0] >= shape[0]
                           and row[2][-2:] == shape[-2:])
        if not candidates:
            raise RuntimeError("Missing exact c9 child alias")
        source = min(candidates, key=lambda row: math.prod(row[2]))
        _CF_COLS_LAZY[0] = True   # Claude-F SETCUT2: only the source flat is read here
        try:
            source_value = owner._workspace((role, source[1]), source[2], paired)
        finally:
            _CF_COLS_LAZY[0] = False
        source_entry = owner.pool[(role, source[1])]
        views, backing = grouped.setdefault((role, P), ({}, source_entry[0]))
        if backing is not source_entry[0]:
            raise RuntimeError("R48 alias group changed backing")
        if paired:
            need_batch = 7 * P
            flat = source_value[1][:shape[0], :need_batch]
            value = (None, flat, _CF_COLS_LATER)   # Claude-F SETCUT2: made at its first request (same split of this flat)
        else:
            value = source_value[:shape[0], :P]
        views[(paired, shape)] = value
    for key, (views, backing) in grouped.items():
        owner.pool[key] = (backing, views, [])
    owner._r48_setupfast_counts = (len(_CB_R48_USED_CHILD_GEOMETRY),
                                    len(grouped), 0)

def _cb_prepare_r48(owner):
    # Keep v5's three dormant M1/N1/R1 P16807 numeric backings.  Only thirteen
    # Pareto-max metadata reshapes are charged; every requested root view is a
    # slice of one of them.  No numeric arena is added.
    la = owner.pool[('M1', 16807)][0]
    pa = owner.pool[('N1', 16807)][0]
    ra = owner.pool[('R1', 16807)][0]

    left = ((256, 2048,
             fnp.reshape(la[:48*256*2048], (1, 48, 256, 2048))),)
    right = tuple((h, q, fnp.reshape(ra[:48*h*q], (1, 48, h, q)))
                  for h, q in ((192, 2688), (224, 2176), (240, 2160),
                               (256, 2064), (2048, 256)))
    product = ((256, 2688,
                fnp.reshape(pa[:48*256*2688], (1, 48, 256, 2688))),)
    left_work = ((256, 2048,
                  fnp.reshape(pa[:18*256*2048], (18, 256, 2048))),)
    right_work = tuple((h, q, fnp.reshape(pa[:18*h*q], (18, h, q)))
                       for h, q in ((192, 2688), (224, 2176), (240, 2160),
                                    (256, 2064), (2048, 256)))
    post_work = ((256, 2688,
                  fnp.reshape(la[:44*256*2688], (44, 256, 2688))),)

    if _CF_FROM12_KEYS_V9:
        owner._f12_e1_raw_leaders = (left, right, product, left_work, right_work, post_work)
        _f12_left = left + ((240,2240,fnp.reshape(la[:48*240*2240],(1,48,240,2240))),)
        _f12_right = right + ((2240,240,fnp.reshape(ra[:48*2240*240],(1,48,2240,240))),
                              (208,2400,fnp.reshape(ra[:48*208*2400],(1,48,208,2400))))
        _f12_lwork = left_work + ((240,2240,fnp.reshape(pa[:18*240*2240],(18,240,2240))),)
        _f12_rwork = right_work + ((2240,240,fnp.reshape(pa[:18*2240*240],(18,2240,240))),
                                   (208,2400,fnp.reshape(pa[:18*208*2400],(18,208,2400))))
    plans = {}
    for key in _CB_R48_ROOTS:
        h, q, v = key[1][2] // 4, key[1][3] // 4, key[2][3] // 4
        if _CF_FROM12_KEYS_V9 and key in (('mm', (1, 1, 960, 8960), (1, 1, 8960, 960), 5), ('mm', (1, 1, 960, 8768), (1, 1, 8768, 960), 5), ('mm', (1, 1, 960, 8576), (1, 1, 8576, 960), 5), ('mm', (1, 1, 960, 832), (1, 1, 832, 9600), 6), ('mm', (1, 1, 960, 832), (1, 1, 832, 9472), 6), ('mm', (1, 1, 960, 832), (1, 1, 832, 9280), 6)):
            arrays = (_cb_r48_pick_v3(_f12_left, h, q),
                      _cb_r48_pick_v3(_f12_right, q, v),
                      _cb_r48_pick_v3(product, h, v),
                      _cb_r48_pick_v3(_f12_lwork, h, q),
                      _cb_r48_pick_v3(_f12_rwork, q, v),
                      _cb_r48_pick_v3(post_work, h, v))
        else:
            arrays = (_cb_r48_pick_v3(left, h, q),
                      _cb_r48_pick_v3(right, q, v),
                      _cb_r48_pick_v3(product, h, v),
                      _cb_r48_pick_v3(left_work, h, q),
                      _cb_r48_pick_v3(right_work, q, v),
                      _cb_r48_pick_v3(post_work, h, v))
        L4, R4, P4, LW, RW, PW = arrays
        # Hoist first-batch views once; keep the original mm operands intact.
        LO, RO, PI = _ci_sd_v(L4, 0), _ci_sd_v(R4, 0), _ci_sd_v(P4, 0)
        rows = tuple(_cc_host_rows(slab) for slab in (LO, RO, PI, LW, RW, PW))
        plans[key] = arrays + (rows,)
    owner._r48_arenas = (la, ra, pa)
    owner._r48_top_view_counts = ((2,7,1,2,7,1) if _CF_FROM12_KEYS_V9 else (1,5,1,1,5,1))
    owner._r48_views = plans

class _CfUnmade:
    """Claude-F SETCUT: a setup view no executor reads (never made); any use raises, never silently."""
    __slots__ = ()

    def __getattr__(self, name):
        raise RuntimeError('Claude-F SETCUT: unmade view used (%s)' % name)

    def __getitem__(self, key):
        raise RuntimeError('Claude-F SETCUT: unmade view indexed')


_CF_UNMADE = _CfUnmade()
_CF_COLS_LATER = _CfUnmade()   # Claude-F SETCUT2: columns of a paired workspace not made yet
_CF_COLS_LAZY = [False]        # set (setup only) by a requester that reads the flat only


def _cf_cols_ready(entry, view_key, views):
    """Claude-F SETCUT2: the finished (None, flat, columns) value of a paired pool view (columns made on first request)."""
    if views is None or views[2] is not _CF_COLS_LATER:
        return views
    flat, P = views[1], int(view_key[1][2])
    views = (views[0], flat, _ci_sd_memo(flat, ('SDS7', P), lambda: _cp_split7(flat, P)))
    entry[1][view_key] = views
    return views


def _cb_decode_views(out):
    """Billed-once block-grid view; all returned slices alias ``out``."""
    b, P, m, w = out.shape
    h, v = m // 2, w // 2
    grid = fnp.reshape(out, (b, P, 2, h, 2, v))
    _cf_keep(grid)
    C11 = _CF_UNMADE   # Claude-F SETCUT: _cb_decode5 (7 views) and _cb_prepare_decode5 never read C11
    C12 = grid[:, :, 0, :, 1, :]
    C21 = grid[:, :, 1, :, 0, :]
    C22 = grid[:, :, 1, :, 1, :]
    left = grid[:, :, :, :, 0, :]
    right = grid[:, :, :, :, 1, :]
    # Both aliases are setup-owned scratch.  Bind the second decode source now
    # instead of creating it on every prediction.
    left1 = left[:, :, 1:2]
    return C11, C12, C21, C22, left, right, left1


def _cb_decode_pair_views(flat, P):
    """Two product-major adjacent-pair views; called only during setup."""
    b, sevenP, h, v = flat.shape
    if sevenP != 7 * P:
        raise RuntimeError("decode pair P mismatch")
    if _CP_IN_SETUP[0] and P > 0:   # Claude-P v2: one split for the three column blocks (identical views)
        _c0, _p12, _p34, _rest = fnp.split(flat, [P, 3 * P, 5 * P], axis=1)
        pair12 = fnp.reshape(_p12, (b, 2, P, h, v))
        pair34 = fnp.reshape(_p34, (b, 2, P, h, v))
        c0_batch = _c0[:, :, None]
        _cf_keep(_c0, _p12, _p34, _rest, pair12, pair34)
    else:
        pair12 = fnp.reshape(flat[:, P:3*P], (b, 2, P, h, v))
        pair34 = fnp.reshape(flat[:, 3*P:5*P], (b, 2, P, h, v))
        # This is exactly cols[0][:, :, None], but is constructed while
        # the setup-owned flat product slab is being prepared.
        c0_batch = flat[:, :P][:, :, None]
    return fnp.swapaxes(pair12, 1, 2), fnp.swapaxes(pair34, 1, 2), c0_batch


if _CI_DECODEDIET:
    class _CiDecodeDietPair:
        """Host-only recipe; no new array or global cache."""
        __slots__ = ("flat", "P", "value")

        def __init__(self, flat, P):
            self.flat = flat
            self.P = P
            self.value = None

        def get(self):
            if self.value is None:
                self.value = _cb_decode_pair_views(self.flat, self.P)
                self.flat = None
            return self.value

        def __len__(self):
            return 3

        def __iter__(self):
            return iter(self.get())

        def __getitem__(self, key):
            return self.get()[key]


def _cb_decode5(cols, pairs, views):
    """Use five requests for setup-cached scratch; seven for dynamic roots."""
    if len(views) == 4:
        C11, C12, C21, C22 = views
        fnp.add(cols[0], cols[1], out=C11)
        fnp.add(cols[0], cols[2], out=C12)
        fnp.add(C12, cols[4], out=C22)
        fnp.add(C22, cols[6], out=C21)
        fnp.add(C12, cols[3], out=C12)
        fnp.add(C12, cols[5], out=C12)
        fnp.add(C22, cols[3], out=C22)
        return
    C11, C12, C21, C22, left, right, left1 = views
    pair12, pair34, c0_batch = pairs
    fnp.add(c0_batch, pair12, out=left)
    fnp.add(left1, pair34, out=right)
    fnp.add(C12, cols[5], out=C12)
    fnp.add(C22, cols[6], out=C21)
    fnp.add(C22, cols[3], out=C22)


def _cb_prepare_decode5(cols, pairs, views):
    """Setup-only flattening of existing owned decode views; no new array view."""
    _C11, C12, C21, C22, left, right, left1 = views
    pair12, pair34, c0_batch = pairs
    return (c0_batch, cols[3], cols[5], cols[6],
            pair12, pair34, C12, C21, C22, left, right, left1)


def _cb_decode5_cached(plan, _add=fnp.add):
    """Five-request decode with branch/index metadata prepared in setup."""
    c0_batch, c3, c5, c6, pair12, pair34, C12, C21, C22, left, right, left1 = plan
    _add(c0_batch, pair12, out=left)
    _add(left1, pair34, out=right)
    _add(C12, c5, out=C12)
    _add(C22, c6, out=C21)
    _add(C22, c3, out=C22)


def _cb_decode7_root(cols, views, _add=fnp.add):
    """Seven-request decode for the caller-owned dynamic root output."""
    C11, C12, C21, C22 = views
    c0, c1, c2, c3, c4, c5, c6 = cols
    _add(c0, c1, out=C11)
    _add(c0, c2, out=C12)
    _add(C12, c4, out=C22)
    _add(C22, c6, out=C21)
    _add(C12, c3, out=C12)
    _add(C12, c5, out=C12)
    _add(C22, c3, out=C22)


def _stage1_plan_mm_1_dense(layers, leaf, XQ, YQ, OQ):
    # Winograd 7-product/15-add schedule; generated locally.
    L0, R0, M0, MP0, X0, Y0, O0 = layers[0]
    X11, X12, X21, X22 = XQ
    Y11, Y12, Y21, Y22 = YQ
    fnp.copyto(L0[0], X11)
    fnp.copyto(L0[1], X12)
    fnp.add(X21, X22, out=L0[3])
    fnp.subtract(L0[3], X11, out=L0[2])
    fnp.subtract(X11, X21, out=L0[4])
    fnp.subtract(X12, L0[2], out=L0[5])
    fnp.copyto(L0[6], X22)
    fnp.copyto(R0[0], Y11)
    fnp.copyto(R0[1], Y21)
    fnp.copyto(R0[5], Y22)
    fnp.subtract(Y12, Y11, out=R0[3])
    fnp.subtract(Y22, R0[3], out=R0[2])
    fnp.subtract(Y22, Y12, out=R0[4])
    fnp.subtract(Y21, R0[2], out=R0[6])
    X, Y, out, zero_runs = leaf
    if zero_runs:
        _cb_at = 0
        for _cb_lo, _cb_hi in zero_runs:
            if _cb_at < _cb_lo:
                fnp.matmul(X[:, _cb_at:_cb_lo], Y[:, _cb_at:_cb_lo], out=out[:, _cb_at:_cb_lo])
            fnp.copyto(out[:, _cb_lo:_cb_hi], _CB_F32_ZERO)
            _cb_at = _cb_hi
        if _cb_at < X.shape[1]:
            fnp.matmul(X[:, _cb_at:], Y[:, _cb_at:], out=out[:, _cb_at:])
    else:
        fnp.matmul(X, Y, out=out)
    _cb_decode5(M0, MP0, OQ)

def _stage1_plan_mm_3_dense(layers, leaf, XQ, YQ, OQ):
    # Winograd 7-product/15-add schedule; generated locally.
    L0, R0, M0, MP0, X0, Y0, O0 = layers[0]
    X11, X12, X21, X22 = XQ
    Y11, Y12, Y21, Y22 = YQ
    fnp.copyto(L0[0], X11)
    fnp.copyto(L0[1], X12)
    fnp.add(X21, X22, out=L0[3])
    fnp.subtract(L0[3], X11, out=L0[2])
    fnp.subtract(X11, X21, out=L0[4])
    fnp.subtract(X12, L0[2], out=L0[5])
    fnp.copyto(L0[6], X22)
    fnp.copyto(R0[0], Y11)
    fnp.copyto(R0[1], Y21)
    fnp.copyto(R0[5], Y22)
    fnp.subtract(Y12, Y11, out=R0[3])
    fnp.subtract(Y22, R0[3], out=R0[2])
    fnp.subtract(Y22, Y12, out=R0[4])
    fnp.subtract(Y21, R0[2], out=R0[6])
    L1, R1, M1, MP1, X1, Y1, O1 = layers[1]
    X11, X12, X21, X22 = X1
    Y11, Y12, Y21, Y22 = Y1
    fnp.copyto(L1[0], X11)
    fnp.copyto(L1[1], X12)
    fnp.add(X21, X22, out=L1[3])
    fnp.subtract(L1[3], X11, out=L1[2])
    fnp.subtract(X11, X21, out=L1[4])
    fnp.subtract(X12, L1[2], out=L1[5])
    fnp.copyto(L1[6], X22)
    fnp.copyto(R1[0], Y11)
    fnp.copyto(R1[1], Y21)
    fnp.copyto(R1[5], Y22)
    fnp.subtract(Y12, Y11, out=R1[3])
    fnp.subtract(Y22, R1[3], out=R1[2])
    fnp.subtract(Y22, Y12, out=R1[4])
    fnp.subtract(Y21, R1[2], out=R1[6])
    L2, R2, M2, MP2, X2, Y2, O2 = layers[2]
    X11, X12, X21, X22 = X2
    Y11, Y12, Y21, Y22 = Y2
    fnp.copyto(L2[0], X11)
    fnp.copyto(L2[1], X12)
    fnp.add(X21, X22, out=L2[3])
    fnp.subtract(L2[3], X11, out=L2[2])
    fnp.subtract(X11, X21, out=L2[4])
    fnp.subtract(X12, L2[2], out=L2[5])
    fnp.copyto(L2[6], X22)
    fnp.copyto(R2[0], Y11)
    fnp.copyto(R2[1], Y21)
    fnp.copyto(R2[5], Y22)
    fnp.subtract(Y12, Y11, out=R2[3])
    fnp.subtract(Y22, R2[3], out=R2[2])
    fnp.subtract(Y22, Y12, out=R2[4])
    fnp.subtract(Y21, R2[2], out=R2[6])
    X, Y, out, zero_runs = leaf
    if zero_runs:
        _cb_at = 0
        for _cb_lo, _cb_hi in zero_runs:
            if _cb_at < _cb_lo:
                fnp.matmul(X[:, _cb_at:_cb_lo], Y[:, _cb_at:_cb_lo], out=out[:, _cb_at:_cb_lo])
            fnp.copyto(out[:, _cb_lo:_cb_hi], _CB_F32_ZERO)
            _cb_at = _cb_hi
        if _cb_at < X.shape[1]:
            fnp.matmul(X[:, _cb_at:], Y[:, _cb_at:], out=out[:, _cb_at:])
    else:
        fnp.matmul(X, Y, out=out)
    _cb_decode5(M2, MP2, O2)
    _cb_decode5(M1, MP1, O1)
    _cb_decode5(M0, MP0, OQ)

def _stage1_plan_mm_2_fused(layers, leaf, XQ, YQ, OQ):
    # Winograd 7-product/15-add schedule; generated locally.
    L0, R0, M0, MP0, X0, Y0, O0 = layers[0]
    X11, X12, X21, X22 = XQ
    Y11, Y12, Y21, Y22 = YQ
    fnp.copyto(L0[0], X11)
    fnp.copyto(L0[1], X12)
    fnp.add(X21, X22, out=L0[3])
    fnp.subtract(L0[3], X11, out=L0[2])
    fnp.subtract(X11, X21, out=L0[4])
    fnp.subtract(X12, L0[2], out=L0[5])
    fnp.copyto(L0[6], X22)
    fnp.copyto(R0[0], Y11)
    fnp.copyto(R0[1], Y21)
    fnp.copyto(R0[5], Y22)
    fnp.subtract(Y12, Y11, out=R0[3])
    fnp.subtract(Y22, R0[3], out=R0[2])
    fnp.subtract(Y22, Y12, out=R0[4])
    fnp.subtract(Y21, R0[2], out=R0[6])
    L1, R1, M1, MP1, X1, Y1, O1 = layers[1]
    X11, X12, X21, X22 = X1
    Y11, Y12, Y21, Y22 = Y1
    fnp.copyto(L1[0], X11)
    fnp.copyto(L1[1], X12)
    fnp.add(X21, X22, out=L1[3])
    fnp.subtract(L1[3], X11, out=L1[2])
    fnp.subtract(X11, X21, out=L1[4])
    fnp.subtract(X12, L1[2], out=L1[5])
    fnp.copyto(L1[6], X22)
    fnp.copyto(R1[0], Y11)
    fnp.copyto(R1[1], Y21)
    fnp.copyto(R1[5], Y22)
    fnp.subtract(Y12, Y11, out=R1[3])
    fnp.subtract(Y22, R1[3], out=R1[2])
    fnp.subtract(Y22, Y12, out=R1[4])
    fnp.subtract(Y21, R1[2], out=R1[6])
    LXQ, LYQ, LOQ, Lb, Rb, Mb, Nb, zero_by_product = leaf
    X11, X12, X21, X22 = LXQ
    Y11, Y12, Y21, Y22 = LYQ
    C11, C12, C21, C22 = LOQ
