# Outside2 preserves the real-arithmetic product; its FP order changes.
_OUTSIDE2_ROUTING_ROOTS = (('mm', (1, 1, 1024, 1024), (1, 1, 1024, 352), 4), ('mm', (1, 1, 1024, 352), (1, 1, 352, 1024), 4))

def _outside2_mm(smm, X, Y, *, out):
    """Reuse prepared Phase2 scratch; retain the native generic fallback."""
    level = smm.level(X.shape[0], X.shape[1], Y.shape[1], 4)
    root = ("mm", (1, 1) + X.shape, (1, 1) + Y.shape, level)
    # Coloring is activated only by the original fixed Phase2 setup guard.
    # Never create a plan, grow scratch, or retain root arrays during predict.
    if (smm._colored_active and root in _OUTSIDE2_ROUTING_ROOTS
            and smm._callplans.get(root) is not None):
        smm.mm(_ci_nn(X), _ci_nn(Y), _ci_nn(out), level)
        return out
    return fnp.matmul(X, Y, out=out)

