_CC_R48_20_SPECS = ((960, 6144, 352, 5, 'old_hub', (960, 352, 6)),)   # Claude-F: only the dispatched spec is prepared (was 6)


def _cc_r48_20_geometry(m, k, n, lev):
    """Exactly the default prepared mm binder's required owned geometry."""
    m, k, n, lev, P = m // 4, k // 4, n // 4, lev - 2, 48
    geometry = set()
    while _StrassenV29._ok(m, k, n, lev):
        h, q, v = m // 2, k // 2, n // 2
        if P >= STRASSEN_FUSE_P and not _StrassenV29._ok(h, q, v, lev - 1):
            for role, H, Q in (('L1', h, q), ('R1', q, v),
                               ('M1', h, v), ('N1', h, v)):
                geometry.add((role, P, (1, P, H, Q), False))
            break
        mrole = ('L' if (_StrassenV29._ok(h // 2, q // 2, v // 2, lev - 2)
                         and q == v) else 'M')
        for role, H, Q in (('L', h, q), ('R', q, v), (mrole, h, v)):
            geometry.add((role, P, (1, 7, P, H, Q), True))
        m, k, n, lev, P = h, q, v, lev - 1, 7 * P
    return geometry


def _cc_r48_20_alias(owner, role, P, shape, paired):
    """Bind a zero-allocation basic prefix/crop without touching old views."""
    entry = owner.pool[(role, P)]
    key = (paired, shape)
    existing = entry[1].get(key)
    if existing is not None:
        return _cf_cols_ready(entry, key, existing) if paired else existing   # Claude-F SETCUT2
    if _CF_B_R48_CHILD_TRIM:
        existing = _cf_b_r48_restore(owner, (role, P), key, entry)
        if existing is not None:
            return _cf_cols_ready(entry, key, existing) if paired else existing
    oldP = {48: 49, 336: 343, 2352: 2401, 16464: 16807}[P]
    candidates = tuple(row for row in _STAGE1_SCRATCH_GEOMETRY
        if row[0] == role and row[1] == oldP and row[3] == paired
        and row[2][0] >= shape[0] and row[2][-2:] == shape[-2:])
    if candidates:
        source = min(candidates, key=lambda row: math.prod(row[2]))
        source_entry = owner.pool[(role, oldP)]
        if source_entry[0] is not entry[0]:
            raise RuntimeError('R48-20 same-role backing identity changed')
        source_value = source_entry[1].get((paired, source[2]))
        if source_value is None:   # Claude-P/F diet: source view of a lazily-bound root
            source_value = owner._workspace((role, oldP), source[2], paired)
        if paired:
            flat = source_value[1][:shape[0], :7 * P]
        else:
            value = source_value[:shape[0], :P]
    else:
        # Original C9 P343 can be fused while new P336 remains regular.
        # The already-owned wide P336 flats cover all three missing default
        # dense geometries. Retain their exact strides, not a guessed reshape.
        if _CF_B_R48_CHILD_TRIM:
            _cf_b_r48_restore_enclosing(owner, role, P, shape, paired, entry)
        enclosing = tuple((other_shape, value)
            for (other_paired, other_shape), value in entry[1].items()
            if other_paired == paired and other_shape[0] >= shape[0]
            and other_shape[-2] >= shape[-2]
            and other_shape[-1] >= shape[-1])
        if not enclosing:
            raise RuntimeError('R48-20 owned enclosing alias missing')
        _, source_value = min(enclosing, key=lambda row: math.prod(row[0]))
        if paired:
            flat = source_value[1][:shape[0], :7 * P,
                                   :shape[-2], :shape[-1]]
        else:
            value = source_value[:shape[0], :P, :shape[-2], :shape[-1]]
    if paired:
        # The flat is product-major. Always regroup at NEW P boundaries.
        value = (None, flat, _cp_split7(flat, P))
    entry[1][key] = value
    return value


def _cc_r48_20_prepare(owner):
    """Setup-only child plans, owned root routes, rowtuples and block views."""
    generation = owner._scratch_generation
    required = set()
    for m, k, n, lev, _mode, _route in _CC_R48_20_SPECS:
        required.update(_cc_r48_20_geometry(m, k, n, lev))
    for role, P, shape, paired in sorted(required):
        _cc_r48_20_alias(owner, role, P, shape, paired)

    # Use original14 top owned plans as leaders. Their numeric buffers and
    # helper rowtuples are never modified, replaced or retained as root data.
    base_plans = tuple(owner._r48_views.values())
    leaders = tuple(tuple((plan[index].shape[-2], plan[index].shape[-1],
                           plan[index]) for plan in base_plans)
                    for index in range(6))
    pack_left = owner._root_pack_arenas[0]
    plans = {}
    hoisted_pair_cache = {}
    for m, k, n, lev, mode, route in _CC_R48_20_SPECS:
        a, b, c = m // 4, k // 4, n // 4
        arrays = tuple(_cb_r48_pick_v3(leaders[index], H, Q)
                       for index, H, Q in ((0, a, b), (1, b, c), (2, a, c),
                                           (3, a, b), (4, b, c), (5, a, c)))
        L4, R4, P4, LW, RW, PW = arrays
        rows = tuple(_cc_host_rows(slab)
                     for slab in (_ci_sd_v(L4, 0), _ci_sd_v(R4, 0), _ci_sd_v(P4, 0), LW, RW, PW))
        child = owner._bind_callplan('mm', L4.shape, R4.shape, lev - 2)
        child = _cc_r48_20_hoist_child(child, hoisted_pair_cache)
        child_quarters = (owner._quarters(L4), owner._quarters(R4),
                          owner._quarters(P4))
        is_recon = mode == 'recon'
        if mode == 'old_hub':
            root_pack = owner._old_hub_packs[route]
            ownedX, ownedY, ownedOut = root_pack[2:5]
        elif mode == 'hub':
            root_pack = owner._root_packs[route]
            ownedX, ownedY, ownedOut = root_pack[2:5]
        else:
            root_pack = owner._old_recon_packs[route]
            ownedY, ownedOut = root_pack[1:3]
            # Live Qc/QU is not setup owned. Copy it afresh at runtime into a
            # disjoint suffix AFTER Y's existing rank*batch*1024 packed area.
            start = k * n
            stop = start + m * k
            if stop > pack_left.size:
                raise RuntimeError('R48-20 root input suffix exceeds owner')
            ownedX = fnp.reshape(pack_left[start:stop], (1, 1, m, k))
        key = ('mm', (1, 1, m, k), (1, 1, k, n), lev)
        if (ownedX.shape != key[1] or ownedY.shape != key[2]
                or ownedOut.shape != (1, 1, m, n)):
            raise RuntimeError('R48-20 owned root geometry mismatch')
        # These51views per shape are setup-only, owned pack views. Caller
        # weights/activations are never cached, even for a matching shape.
        root_blocks = tuple(_cb_r48_blocks4(array[0, 0])
                            for array in (ownedX, ownedY, ownedOut))
        plans[key] = (generation, key, is_recon, ownedX, ownedY, ownedOut,
                      root_blocks, rows, child, child_quarters)
    if owner._scratch_generation != generation:
        raise RuntimeError('R48-20 setup grew or invalidated owned scratch')
    # Snapshot only existing owner references. A generation guard is necessary
    # but also require the actual pool, physical arenas and pack identities;
    # no numeric arrays, caller views or persistent layouts are created here.
    pool_keys = {(role, P) for role, P, _shape, _paired in required}
    pool_keys.update((role, {48: 49, 336: 343, 2352: 2401,
                             16464: 16807}[P])
                     for role, P, _shape, _paired in required)
    pool_keys.update((role, 16807) for role in ('M1', 'N1', 'R1'))
    owner._cc_r48_20_backing_guard = (
        generation,
        tuple((key, owner.pool[key][0]) for key in sorted(pool_keys)),
        tuple(sorted(owner._color_arenas.items())),
        tuple(owner._root_pack_arenas),
    )
    owner._cc_r48_20_plans = plans
    owner._cc_r48_20_hits = 0
    owner._cc_r48_20_hit_counts = {}


def _cc_r48_20_valid(owner):
    guard = getattr(owner, '_cc_predict_guard', None)
    return (guard is not None and owner._colored_active
            and owner._scratch_generation == guard[0] and guard[1])


def _cc_r48_20_matches(owner, X, Y, out, lev, plan):
    generation, key, is_recon, ownedX, ownedY, ownedOut, _blocks, _rows, _child, _quarters = plan
    return (_cc_r48_20_valid(owner)
            and generation == owner._scratch_generation and lev == key[3]
            and X.shape == key[1] and Y.shape == key[2]
            and out.shape == ownedOut.shape and Y is ownedY and out is ownedOut
            and (is_recon or X is ownedX))


def _cc_r48_20_run(owner, X, Y, out, lev, plan):
    """ReturnNone on foreign route; otherwise no new predict array views."""
    if not _cc_r48_20_matches(owner, X, Y, out, lev, plan):
        return None
    _generation, key, is_recon, ownedX, _ownedY, _ownedOut, blocks, rows, child, quarters = plan
    owner._cc_r48_20_hits += 1
    owner._cc_r48_20_hit_counts[key] = owner._cc_r48_20_hit_counts.get(key, 0) + 1
    if is_recon:
        fnp.copyto(ownedX, X)
    _civ = _ci_r48v_fixed(owner, id(plan), plan, owner, ownedX, plan[4], plan[5], rows) if _CI_R48V else None
    if _civ is not None:
        _ci_r48v_exec(_civ[0], None)
        _ci_r48v_exec(_civ[1], None)
        child[0](child[1], child[2], *quarters)
        _ci_r48v_exec(_civ[2], None)
        return out
    XI, YI, OI = blocks
    LO, RO, PI, LW_rows, RW_rows, PW_rows = rows
    _cb_r48_204_left(XI, LO, LW_rows)
    _cb_r48_204_right(YI, RO, RW_rows)
    function, layers, leaf = child
    XQ, YQ, OQ = quarters
    function(layers, leaf, XQ, YQ, OQ)
    _cb_r48_204_post(PI, OI, PW_rows)
    return out


def _cc_r48_20_hoist_child(child, cache):
    """Cache both owned FD3 broadcast/slice views during setup, not predict."""
    function, layers, leaf = child
    if function is _stage1_plan_mm_2_fused:
        if any(leaf[-1]):
            raise RuntimeError('R48-20 fused zero spans would create runtime views')
        function = _cc_r48_20_mm2_fused
    elif function is _stage1_plan_mm_2_dense:
        if leaf[-1]:
            raise RuntimeError('R48-20 dense zero spans would create runtime views')
        function = _cc_r48_20_mm2_dense
    else:
        raise RuntimeError('R48-20 child policy changed from two regular layers')
    if len(layers) != 2:
        raise RuntimeError('R48-20 child regular-layer count changed')
    prepared = []
    for index, (Lcols, Rcols, Mcols, MPairs, XQ, YQ, OQ) in enumerate(layers):
        if index:
            if len(OQ) != 7 or len(MPairs) != 3:
                raise RuntimeError('R48 view-cache owned metadata changed')
            MPairs = (MPairs[0], MPairs[1], MPairs[2], OQ[6])
            OQ = OQ[:6]  # Python tuple projection; no new array view.
        prepared.append((Lcols, Rcols, Mcols, MPairs, XQ, YQ, OQ))
    return function, tuple(prepared), leaf


def _cc_r48_20_decode(cols, pairs, views):
    """Original FD3 numeric order; no runtime owned broadcast/slice creation."""
    if len(views) == 4:
        C11, C12, C21, C22 = views
        fnp.add(cols[0], cols[1], out=C11)
        fnp.add(cols[0], cols[2], out=C12)
        fnp.add(C12, cols[4], out=C22)
        fnp.add(C22, cols[6], out=C21)
        fnp.add(C12, cols[3], out=C12)
        fnp.add(C12, cols[5], out=C12)
        fnp.add(C22, cols[3], out=C22)
        return
    C11, C12, C21, C22, left, right = views
    pair12, pair34, product0_broadcast, left_column_slice = pairs
    fnp.add(product0_broadcast, pair12, out=left)
    fnp.add(left_column_slice, pair34, out=right)
    fnp.add(C12, cols[5], out=C12)
    fnp.add(C22, cols[6], out=C21)
    fnp.add(C22, cols[3], out=C22)


def _cc_r48_20_mm2_fused(layers, leaf, XQ, YQ, OQ):
    # Winograd 7-product/15-add schedule; generated locally.
    L0, R0, M0, MP0, X0, Y0, O0 = layers[0]
