    fnp.copyto(L1[1], X12)
    fnp.add(X21, X22, out=L1[3])
    fnp.subtract(L1[3], X11, out=L1[2])
    fnp.subtract(X11, X21, out=L1[4])
    fnp.subtract(X12, L1[2], out=L1[5])
    fnp.copyto(L1[6], X22)
    fnp.copyto(R1[0], Y11)
    fnp.copyto(R1[1], Y21)
    fnp.copyto(R1[5], Y22)
    fnp.subtract(Y12, Y11, out=R1[3])
    fnp.subtract(Y22, R1[3], out=R1[2])
    fnp.subtract(Y22, Y12, out=R1[4])
    fnp.subtract(Y21, R1[2], out=R1[6])
