    if zero_by_product[5]:
        _cb_at = 0
        for _cb_lo, _cb_hi in zero_by_product[5]:
            if _cb_at < _cb_lo:
                fnp.matmul(Lb[:, _cb_at:_cb_lo], Rb[:, _cb_at:_cb_lo], out=C12[:, _cb_at:_cb_lo])
            fnp.copyto(C12[:, _cb_lo:_cb_hi], 0.0)
            _cb_at = _cb_hi
        if _cb_at < Lb.shape[1]:
            fnp.matmul(Lb[:, _cb_at:], Rb[:, _cb_at:], out=C12[:, _cb_at:])
