        for _cb_lo, _cb_hi in zero_by_product[2]:
            if _cb_at < _cb_lo:
                fnp.matmul(Lb[:, _cb_at:_cb_lo], Y22[:, _cb_at:_cb_lo], out=C21[:, _cb_at:_cb_lo])
