    fnp.subtract(Y22, Y12, out=Rb)
    if zero_by_product[6]:
        _cb_at = 0
        for _cb_lo, _cb_hi in zero_by_product[6]:
            if _cb_at < _cb_lo:
                fnp.matmul(Lb[:, _cb_at:_cb_lo], Rb[:, _cb_at:_cb_lo], out=Mb[:, _cb_at:_cb_lo])
            fnp.copyto(Mb[:, _cb_lo:_cb_hi], 0.0)
