def _cc_r48_20_mm2_dense(layers, leaf, XQ, YQ, OQ):
    # Winograd 7-product/15-add schedule; generated locally.
    L0, R0, M0, MP0, X0, Y0, O0 = layers[0]
    X11, X12, X21, X22 = XQ
    Y11, Y12, Y21, Y22 = YQ
    fnp.copyto(L0[0], X11)
    fnp.copyto(L0[1], X12)
    fnp.add(X21, X22, out=L0[3])
    fnp.subtract(L0[3], X11, out=L0[2])
    fnp.subtract(X11, X21, out=L0[4])
    fnp.subtract(X12, L0[2], out=L0[5])
    fnp.copyto(L0[6], X22)
    fnp.copyto(R0[0], Y11)
    fnp.copyto(R0[1], Y21)
    fnp.copyto(R0[5], Y22)
    fnp.subtract(Y12, Y11, out=R0[3])
    fnp.subtract(Y22, R0[3], out=R0[2])
    fnp.subtract(Y22, Y12, out=R0[4])
    fnp.subtract(Y21, R0[2], out=R0[6])
    L1, R1, M1, MP1, X1, Y1, O1 = layers[1]
    X11, X12, X21, X22 = X1
    Y11, Y12, Y21, Y22 = Y1
    fnp.copyto(L1[0], X11)
    fnp.copyto(L1[1], X12)
    fnp.add(X21, X22, out=L1[3])
    fnp.subtract(L1[3], X11, out=L1[2])
    fnp.subtract(X11, X21, out=L1[4])
    fnp.subtract(X12, L1[2], out=L1[5])
    fnp.copyto(L1[6], X22)
    fnp.copyto(R1[0], Y11)
    fnp.copyto(R1[1], Y21)
    fnp.copyto(R1[5], Y22)
    fnp.subtract(Y12, Y11, out=R1[3])
    fnp.subtract(Y22, R1[3], out=R1[2])
    fnp.subtract(Y22, Y12, out=R1[4])
    fnp.subtract(Y21, R1[2], out=R1[6])
    X, Y, out, zero_runs = leaf
    if zero_runs:
        _cb_at = 0
        for _cb_lo, _cb_hi in zero_runs:
            if _cb_at < _cb_lo:
                fnp.matmul(X[:, _cb_at:_cb_lo], Y[:, _cb_at:_cb_lo], out=out[:, _cb_at:_cb_lo])
            fnp.copyto(out[:, _cb_lo:_cb_hi], _CB_F32_ZERO)
            _cb_at = _cb_hi
        if _cb_at < X.shape[1]:
            fnp.matmul(X[:, _cb_at:], Y[:, _cb_at:], out=out[:, _cb_at:])
    else:
        fnp.matmul(X, Y, out=out)
    _cc_r48_20_decode(M1, MP1, O1)
    _cc_r48_20_decode(M0, MP0, OQ)


