def _cc_full1024_validate(owner, generation, bindings):
    """Strong identities only; never inspect or preserve scratch values."""
    if not owner._colored_active or owner._scratch_generation != generation:
        raise RuntimeError("Full1024 cyclic scratch generation is invalid")
    for key, arena, backing in bindings:
        entry = owner.pool.get(key)
        if (entry is None or entry[0] is not backing
                or owner._color_arenas.get(arena) is not backing):
            raise RuntimeError("Full1024 cyclic physical backing was replaced")


def _cc_full1024_prepare(owner):
    """Setup only: one direct19-reshape, scratch-owned, immutable row plan.

    Nested rank48 and the fused leaf keep batch axes48x40, not1x1920 plus
    a second reshape. All block/quarter/row/padding-destination views are made
    here. Runtime must select exactly two approved occurrences and reset that
    selection at predict entry; this fragment does not alter dispatch.
    """
    if not owner._colored_active:
        raise RuntimeError("Full1024 cyclic setup requires active coloring")
    generation = owner._scratch_generation
    bindings = []
    for key, arena, required in _CC_FULL1024_BACKING_REQUIREMENTS:
        entry = owner.pool.get(key)
        if entry is None:
            raise RuntimeError("Full1024 cyclic owned backing is missing")
        backing = entry[0]
        if (owner._color_arenas.get(arena) is not backing
                or backing.size < required):
            raise RuntimeError("Full1024 cyclic owned capacity/map mismatch")
        bindings.append((key, arena, backing))
    bindings = tuple(bindings)
