    # These are ALREADY OWNED setup root-pack references, never caller data.
    root_pack = owner._root_packs.get(("hub", 8))
    root_arenas = owner._root_pack_arenas
    if root_pack is None or len(root_pack) != 6 or len(root_arenas) != 3:
        raise RuntimeError("Full1024 cyclic owned hub8 root pack is missing")
    rootX, rootY, rootOut = root_pack[2], root_pack[3], root_pack[4]
    if (rootX.shape, rootY.shape, rootOut.shape) != _CC_FULL1024_ROOT_SHAPES:
        raise RuntimeError("Full1024 cyclic owned root-pack shape mismatch")
    root_matrices = (rootX[0, 0], rootY[0, 0], rootOut[0, 0])
    root_bindings = (root_pack, root_arenas)

    la, ra, pa, nLa, nRa, nPa, fLa, fRa, fMa, fNa = (
        binding[2] for binding in bindings
    )

    # Every source is a contiguous1D prefix or disjoint padding suffix.
    # Nineteen billed reshape calls sum to314,960,896F.
    LO = fnp.reshape(la[:18823680], (40, 344, 1368))
    RO = fnp.reshape(ra[:18823680], (40, 1368, 344))
