    RW = fnp.reshape(pa[:19294272], (41, 1368, 344))
    PW = fnp.reshape(la[:3313408], (28, 344, 344))
    padX = fnp.reshape(la[18823680:27294336], (1032, 8208))
    padY = fnp.reshape(ra[18823680:27294336], (8208, 1032))

