    nPI = fnp.reshape(nPa[:14200320], (48, 40, 86, 86))
    nLW = fnp.reshape(pa[:21176640], (18, 40, 86, 342))
    nRW = fnp.reshape(pa[:21176640], (18, 40, 342, 86))
