        _cc_host_rows(nLW), _cc_host_rows(nRW), _cc_host_rows(nPW),
        nXI, nYI, nCO, XQ, YQ, OQ, Lb, Rb, Mb, Nb, CO,
        pad_destinations, cropped_output, generation, bindings,
