def _cc_ta_nonzero(values):
    if isinstance(values, (list, tuple)):
        return any(_cc_ta_nonzero(value) for value in values)
    return float(values) != 0.0


def _cc_ta_reduced_policy(model):
    """Immutable export-only pruning proof; never current-network data."""
    required = {38, 39, 40, 41, 42, 43}
    energies = {20, 21}
    wk_energy = {19}
    masks = {44, 45, 46}
    pk = {14, 15, 16, 17, 18}
    omitted_names = model.get('omit_names')
    if not isinstance(omitted_names, (list, tuple)):
        raise ValueError('Reduced ridge requires explicit omit_names metadata')
    if len(set(omitted_names)) != len(omitted_names):
        raise ValueError('Reduced omit_names must be unique')
    allowed = {_CC_TA_NAMES[index] for index in required | energies | wk_energy | masks | pk}
    if any(name not in allowed for name in omitted_names):
        raise ValueError('Reduced omit_names contains an unsupported feature')
    omitted = {_CC_TA_NAMES.index(name) for name in omitted_names}
    if not required.issubset(omitted) or len(omitted & energies) not in (0, 2):
        raise ValueError('Omit all six N31/RN21 features, and both or neither K31 energies')
    if omitted & wk_energy and not energies.issubset(omitted):
        raise ValueError('Omitting wk431 energy also requires both K31 energies omitted')
    if omitted & pk and (not pk.issubset(omitted) or not (energies | wk_energy).issubset(omitted)):
        raise ValueError('pk omission requires all pk5 and K31 energies omitted')
    beta = model['beta']
    if len(beta) != 15 or any(len(row) != 499 for row in beta):
        raise ValueError('Reduced ridge still requires full15x499 zero-padded beta')
    def zero(index):
        return all(float(row[311+47*block+index]) == 0.0
                   for row in beta for block in range(4))
    if any(not zero(index) for index in omitted):
        raise ValueError('Refusing to omit a feature with any nonzero fitted coefficient')
    # Associated phase masks are independent fitted features. If nonzero,
    # retain their exact phase copies even though their numeric queries vanish.
    return dict(keep_pk_energy=not bool(omitted & pk), keep_k31_energy=not bool(omitted & energies),
                keep_wk431_energy=not bool(omitted & wk_energy),
                mask44_required=not zero(44),
                mask45_required=not zero(45), mask46_required=not zero(46),
                omitted_columns=tuple(sorted(omitted | {index for index in masks if zero(index)})))


