def _ci_star_birth(Om, kb_slot, alpha, phi, inv, i2, i3, a2, K2v, K4v, ones_n):
    """Claude-I star-D4: combined per-layer column weights of the source born here (birth = this layer's pre-activation)."""
    f2 = fnp.multiply(phi, inv)
    f3 = fnp.multiply(fnp.multiply(alpha, phi), -1.0 * i2)
    f4 = fnp.multiply(fnp.multiply(fnp.subtract(a2, 1.0), phi), i3)
    vp = fnp.maximum(K2v, 1e-4)
    rv = fnp.divide(1.0, vp)
    kb = fnp.multiply(K4v, fnp.multiply(rv, rv))
    W5 = fnp.stack([ones_n, f3, f4, kb, fnp.multiply(f2, f2)], axis=1)          # (n, 5)
    Om5 = fnp.matmul(W5, _CI_STAR_TH5).reshape(-1, 16, 5)                        # (n, l, m)
    rv2 = fnp.multiply(rv, rv)
    VP = fnp.stack([ones_n, rv, rv2, fnp.multiply(rv2, rv), fnp.multiply(rv2, rv2)], axis=1)   # (n, m): vp^-q
    fnp.multiply(Om5, VP[:, None, :], out=Om5)
    Om5 = fnp.add(Om5, fnp.matmul(fnp.stack([f3, f4], axis=1), _CI_STAR_TRAW).reshape(-1, 16, 5))
    fnp.copyto(_cfv(Om, (slice(None), slice(None), kb_slot, slice(None))), _cfv_tp(Om5, (1, 2, 0)))   # Claude-F FVC5

def _ci_star5_g4(bufs, pool, Om, li, A_st, P_st, g4law):
    # Memory-safe (official worker RLIMIT_AS 8 GiB, ~30 MB headroom): NO fnp.einsum on (k,n,n) operands
    # (flopscope einsum cost analysis allocates float64 dummies of operand shape). Elementwise products go
    # into (L-1,n,n) pool slabs the chain allocates but leaves unused when R_FB=0 ("xt","yt","u") or that are
    # dead after _dslices ("t"); the column-weighted row sums use batched matmul into a tiny (k,n,1) buffer.
    k = A_st.shape[0]
    if _C_A_ON: _a0_begin(li, int(A_st.shape[1]))
    X = fnp.multiply(A_st, A_st, out=bufs["xt"][:k])           # A^2
    Y = fnp.multiply(A_st, P_st, out=bufs["yt"][:k])           # A P
    Z = fnp.multiply(P_st, P_st, out=bufs["u"][:k])            # P^2
    T = bufs["t"][:k]
    R = pool.get("ci_star_red", (Om.shape[2], A_st.shape[1], 1))[:k]
    def _acc(M, m, F):
        fnp.matmul(M, _cf_view(_cf_view(Om, (li, m, slice(None, k))), (slice(None), slice(None), None)), out=R)       # (k, n, 1)
        f = fnp.sum(R, axis=0)                                  # (n, 1)
        if _C_A_ON: _a0_cap(li, f)
        return f if F is None else fnp.add(F, f, out=F)
    F = _acc(fnp.multiply(X, Y, out=T), 1, None)               # A^3 P
    F = _acc(fnp.multiply(Y, Z, out=T), 3, F)                  # A P^3
    F = _acc(fnp.multiply(X, X, out=X), 0, F)                  # A^4
    F = _acc(fnp.multiply(Y, Y, out=Y), 2, F)                  # A^2 P^2
    F = _acc(fnp.multiply(Z, Z, out=Z), 4, F)                  # P^4
    if _C_A_ON: _a0_capF(li, F)
    a, b = _CI_STAR_AB[li]
    _gs = _CI_G['star'][li]
    g = fnp.multiply(g4law, 1.0 + _gs * (a - 1.0))
    fnp.add(g, _gs * b, out=g)
    fnp.add(g, fnp.multiply(F[:, 0], _gs), out=g)
    return g


def _ci_gain_setup(core, ctx):
    if (ctx.width, ctx.depth) != (1024, 16):
        return
    f32 = fnp.float32
    if core._law_arrays is not None:
        beta, mean, inv = core._law_arrays
        g = fnp.asarray([[_CI_G['a14'][l + 1]] for l in range(beta.shape[0])], dtype=f32)
        core._law_arrays = (fnp.multiply(beta, g), mean, inv)
    if core._beta_arrays is None:
        return
    c3 = list(core._c3_arrays)
    st = getattr(core, '_cc_ta_state', None)
    plans = list(st['ridge_plans']) if (st is not None and st.get('ridge_plans')) else None
    for li in range(1, 16):
        core._beta_arrays[li] = fnp.multiply(core._beta_arrays[li], f32(_CI_G['c2'][li]))
        c3[li] = fnp.multiply(c3[li], f32(_CI_G['c3'][li]))
        if plans is not None:
            bm, bl = plans[li - 1]
            plans[li - 1] = (fnp.multiply(bm, f32(_CI_G['ta'][li])), fnp.multiply(bl, f32(_CI_G['ta'][li])))
    core._c3_arrays = tuple(c3)
    if plans is not None:
        st['ridge_plans'] = tuple(plans)



# --- codex-2 TAK31CUT v1: setup-only view timing; original arrays stay eager ---
_CI_TAK31CUT = _os.environ.get("CI_TAK31CUT", "1") != "0"

class _CiTak31Views:
    """State-owned basic views; constructing the container allocates no array."""
    __slots__ = ("_base", "_column", "_cache", "_as_tuple")

    def __init__(self, base, length, eager, column, as_tuple):
        self._base = base
        self._column = column
        self._as_tuple = as_tuple
        self._cache = [None] * length
        for i in eager:
            self._cache[i] = base[:, i] if column else base[i]

    def __len__(self):
        return len(self._cache)

    def __getitem__(self, index):
        if isinstance(index, slice):
            values = [self[i] for i in range(*index.indices(len(self._cache)))]
            return tuple(values) if self._as_tuple else values
        value = self._cache[index]
        if value is None:
            i = range(len(self._cache))[index]
            value = self._base[:, i] if self._column else self._base[i]
            self._cache[i] = value
        return value

    def __iter__(self):
        for i in range(len(self._cache)):
            yield self[i]

def _ci_tak31_getattr(self, name):
    if name == "k31x8":
        value = self.k31x[:8]
        self.k31x8 = value
        return value
    raise AttributeError(name)
# --- end codex-2 TAK31CUT v1 helpers ---

def _cc_ta_setup(core, ctx):
    core._cc_ta_enabled = False
    core._cc_ta_state = None
    core._cc_ta_predict_guard = None
    core._cc_ta_head_hits = core._cc_ta_feature_hits = core._cc_ta_wc_hits = 0
    model = _CC_TA_MODEL
    if not model:
        return
    kind = model.get('kind')
    if kind == 'ridge':
        nonzero = _cc_ta_nonzero(model.get('beta', ()))
    elif kind == 'mlp':
        nonzero = any(_cc_ta_nonzero(model.get(key, ()))
                      for key in ('W1', 'b1', 'W2', 'b2', 'W3', 'b3'))
    else:
        raise ValueError('Track A model kind must be ridge or mlp')
    if not nonzero:
        return
    if (ctx.width, ctx.depth) != (1024, 16):
        return
    if NO_REGEN or NO_CORR or NO_WK431 or NO_SRC_LAST or FULL_LAST or C4_BETA is None:
        raise ValueError('Track A active literals require the default paid suppliers/head')
    mode = model.get('mode')
    if mode not in ('replace', 'residual'):
        raise ValueError('Track A requires explicit replace/residual ownership')
    if model.get('target') != ('C4-off' if mode == 'replace' else 'parent-residual'):
        raise ValueError('Training target does not match C4 ownership mode')
    if tuple(model.get('names', ())) != _CC_TA_NAMES:
        raise ValueError('Track A feature order mismatch')
    if kind != 'ridge':
        raise ValueError('Reduced Track A shipping is ridge-only')
    policy = _cc_ta_reduced_policy(model)
    n = ctx.width
    owner = core._smm
    if not owner._colored_active:
        raise RuntimeError('Track A active port requires prepared colored owner')
    keys = (('N1', 16807), ('M1', 16807), ('R1', 16807))
    backings = tuple(owner.pool[key][0] for key in keys)
    if len({id(value) for value in backings}) != 3 or any(value.size < n*n for value in backings):
        raise RuntimeError('Track A borrowed arenas overlap or are too small')
    matrices = tuple(fnp.reshape(value[:n*n], (n, n)) for value in backings)
    # Only small, setup-owned packets persist between layers of ONE predict.
    frame = fnp.zeros((n, 47), dtype=fnp.float32)
    Q = fnp.zeros((n, 5), dtype=fnp.float32)
    prev = fnp.zeros((n, 3), dtype=fnp.float32)
    wc = fnp.zeros((n, 13), dtype=fnp.float32)
    messages = fnp.zeros((n, 5), dtype=fnp.float32)
    powers = fnp.zeros((2, n), dtype=fnp.float32)
    # Reused query/gate outputs. Their setup-owned views never point at
    # current-network arrays; every numeric element is overwritten first.
    queries3 = fnp.empty((n, 3), dtype=fnp.float32)
    queries2 = queries3[:, :2]
    head_gates = fnp.empty((n, 4), dtype=fnp.float32)
    head_gate_prefixes = _CPPrefixes(head_gates, n + 1)   # Claude-P v2: prefix view made on first use
    # General workspace, not zeros' inferred last-two-axis symmetry. Every
    # active prefix is fully overwritten by stack before ANY subsequent read.
    batch_width = (3 if policy['keep_pk_energy'] else 0)+int(policy['keep_wk431_energy'])+int(policy['keep_k31_energy'])
    batch = fnp.empty((batch_width, n, n), dtype=fnp.float32)
    batch_rows = fnp.zeros((batch_width, n), dtype=fnp.float32)
    batch_plans = {}
    for width, indexes in ((3, (14, 15, 17)), (4, (14, 15, 17, 19)),
                           (5, (14, 15, 17, 19, 20))):
        if width > batch_width:
            continue
        rows = batch_rows[:width]
        batch_plans[width] = (batch[:width], rows, rows.T,
            fnp.asarray((indexes,), dtype=fnp.int64))
    if _CI_TAK31CUT:
        columns = _CiTak31Views(frame, 47, (0, 1, 2, 3, 8, 9, 10, 11, 12, 13, 16, 18, 21, 22, 36, 37, 44, 45, 46), True, True)
    else:
        columns = tuple(frame[:, index] for index in range(47))
    qcols = tuple(Q[:, index] for index in range(5))
    pcols = tuple(prev[:, index] for index in range(3))
    pows = tuple(powers[index] for index in range(2))
    views = dict(wcU=wc[:, :5], wcV=wc[:, 5:10], wcA=wc[:, 10], wcJ=wc[:, 11],
        wcSafe=wc[:, 12], wcAcol=wc[:, 12:13], signed=frame[:, 26:31], magnitude=frame[:, 31:36],
        neighbors=frame[:, 23:26], messages3=messages[:, :3], messages2=messages[:, :2],
        ivrow=pows[0][None, :], i2col=pows[1][:, None],
        r2indexes=fnp.asarray(((4, 5, 7),), dtype=fnp.int64),
        rindexes=fnp.asarray(((6, 8),), dtype=fnp.int64))
    if policy['keep_pk_energy']:
        views['batch_pk21'] = batch[1]
    if policy['keep_k31_energy']:
        views['batch_k31'] = batch[4]
    views['NT'] = matrices[0].T
    if _CI_TAK31CUT:
        views['message_cols'] = _CiTak31Views(messages, 5, (0,), True, True)
    else:
        views['message_cols'] = tuple(messages[:, index] for index in range(5))
    state = dict(generation=owner._scratch_generation, keys=keys, backings=backings,
                 matrices=matrices, frame=frame, Q=Q, prev=prev, wc=wc,
                 messages=messages, powers=powers, columns=columns, qcols=qcols,
                 pcols=pcols, pows=pows, views=views, batch_plans=batch_plans,
                 queries3=queries3, queries2=queries2,
                 head_gate_prefixes=head_gate_prefixes, kind=kind, mode=mode,
                 prev_li=-1, wc_li=-1, frame_li=-1)
    # Positional plans remove repeated string lookup/assembly in 46 hooks.
    state['wc_plan'] = (matrices[0], matrices[1], matrices[2], views['wcA'],
        views['wcSafe'], views['wcJ'], Q, views['wcU'], views['wcV'])
    state['feature_plan'] = (frame, columns, pows, views, matrices[0],
        matrices[1], matrices[2], powers, qcols, queries3, queries2, prev, pcols, batch_plans)
    state.update(policy)
    # All dimensions/values are supplied, never inferred from a training shard.
    if kind == 'ridge':
        if len(model['beta']) != 15 or any(len(row) != 499 for row in model['beta']):
            raise ValueError('Ridge beta must have shape15x499 (311+4*47)')
        for key in ('nl_mu', 'nl_sd'):
            if len(model[key]) != 15 or any(len(row) != 47 for row in model[key]):
                raise ValueError('Ridge scaling must have shape15x47')
        if any(not (0.0 < float(value) < float('inf')) for row in model['nl_sd'] for value in row):
            raise ValueError('Ridge nl_sd must be finite and positive')
        # Immutable coefficient folding only; never current-network feature data.
        local_rows, message_rows = [], []
        for beta, mean, sd in zip(model['beta'], model['nl_mu'], model['nl_sd']):
            if any(not (-3.0e38 < float(x) < 3.0e38) for row in (beta, mean) for x in row):
                raise ValueError('Ridge coefficients/means must be finite F32-safe')
            if any(not (1.0e-37 <= float(x) < 3.0e38) for x in sd):
                raise ValueError('Ridge std must survive F32 cast/reciprocal')
            weights = [[float(beta[311+47*t+f])/float(sd[f]) for t in range(4)]
                       for f in range(47)]
            local = list(beta[:311])
            for t, index in enumerate((0, 6, 16, 17)):
                local[index] = float(local[index])-sum(float(mean[f])*weights[f][t]
                                                       for f in range(47))
            if any(not (-3.0e38 < float(x) < 3.0e38) for x in local):
                raise ValueError('Folded ridge local parameters overflow F32')
            if any(not (-3.0e38 < x < 3.0e38) for row in weights for x in row):
                raise ValueError('Folded ridge message parameters overflow F32')
            local_rows.append(local)
            message_rows.append(weights)
        state['beta_local'] = tuple(fnp.asarray(row, dtype=fnp.float32) for row in local_rows)
        state['beta_message'] = tuple(fnp.asarray(row, dtype=fnp.float32) for row in message_rows)
        state['ridge_plans'] = tuple(zip(state['beta_message'], state['beta_local']))
    else:
        for key in ('raw_mu', 'raw_sd'):
            if len(model[key]) != 15 or any(len(row) != 82 for row in model[key]):
                raise ValueError('MLP raw scaling must have shape15x82')
        if len(model['yscale']) != 15:
            raise ValueError('MLP yscale must have length15')
        if any(not (0.0 < float(value) < float('inf')) for row in model['raw_sd'] for value in row):
            raise ValueError('MLP raw_sd must be finite and positive')
        for key, rows, cols in (('W1', 98, 64), ('W2', 64, 32), ('W3', 32, 1)):
            if len(model[key]) != rows or any(len(row) != cols for row in model[key]):
                raise ValueError('MLP matrices must be INPUTxOUTPUT,98x64/64x32/32x1')
        for key, width in (('b1', 64), ('b2', 32), ('b3', 1)):
            if len(model[key]) != width:
                raise ValueError('MLP bias width mismatch')
        for key in ('W1', 'b1', 'W2', 'b2', 'W3', 'b3'):
            state[key] = fnp.asarray(model[key], dtype=fnp.float32)
        means = fnp.asarray(model['raw_mu'], dtype=fnp.float32)
        inverse = fnp.reciprocal(fnp.asarray(model['raw_sd'], dtype=fnp.float32))
        state['means'] = tuple(means[index][None, :] for index in range(15))
        state['inverse'] = tuple(inverse[index][None, :] for index in range(15))
        state['yscale'] = tuple(float(value) for value in model['yscale'])
        # Immutable layer codes, not a sample-network mask or model result.
        onehot = [[float(index == layer) for index in range(16)] for layer in range(16)]
        codes = fnp.asarray(onehot, dtype=fnp.float32)
        state['codes'] = tuple(codes[layer][None, :] for layer in range(16))
    core._cc_ta_state = state
    core._cc_ta_enabled = True


def _cc_ta_begin(core, n, L):
    core._cc_ta_head_hits = core._cc_ta_feature_hits = core._cc_ta_wc_hits = 0
    core._cc_ta_predict_guard = None
    state = getattr(core, '_cc_ta_state', None)
    owner = getattr(core, '_smm', None)
    valid = bool(getattr(core, '_cc_ta_enabled', False) and state and owner
                 and (n, L) == (1024, 16) and owner._colored_active
                 and state['generation'] == owner._scratch_generation
                 and all(owner.pool.get(key) is not None and owner.pool[key][0] is value
                         for key, value in zip(state['keys'], state['backings'])))
    if valid:
        core._cc_ta_predict_guard = (state, owner, state['generation'])
        state['prev_li'] = state['wc_li'] = state['frame_li'] = -1
    core._cc_ta_active = valid
    return valid


def _cc_ta_require_valid(core):
    state = core._cc_ta_state
    owner = core._smm
    guard = getattr(core, '_cc_ta_predict_guard', None)
    if (guard is None or guard[0] is not state or guard[1] is not owner
            or not owner._colored_active or guard[2] != owner._scratch_generation):
        raise RuntimeError('Track A owned workspace invalidated during predict')
    return state


def _cc_ta_wc(core, li, WC, W, already_B):
    state = _cc_ta_require_valid(core)
    if state['prev_li'] != li-1:
        return
    B, absB, square, wcA, wcSafe, wcJ, Q, wcU, wcV = state['wc_plan']
    if already_B is None:
        fnp.multiply(WC, W, out=B)
    else:
        B = already_B  # trim's paid T1; read-only, never retained.
    fnp.abs(B, out=absB)
    fnp.multiply(B, B, out=square)
    fnp.sum(absB, axis=1, out=wcA)
    fnp.maximum(wcA, 1e-10, out=wcSafe)
    fnp.sum(square, axis=1, out=wcJ)
    fnp.matmul(B, Q, out=wcU)
    fnp.matmul(absB, Q, out=wcV)
    state['wc_li'] = li
    core._cc_ta_wc_hits += 1


def _cc_ta_prepare(core, li, W, WW, zeros_n, mu, alpha, phi, Phi, D3, g4,
                   inv, i2, i3, i4, R, R2, xsr, D21, pk11, pk21, pk22, wk431, K31F, support=None):
    state = _cc_ta_require_valid(core)
    (F, cols, pows, v, N, work, other, powers, qcols, queries3, queries2,
     prev, pcols, batch_plans) = state['feature_plan']
    fnp.copyto(F, 0.0)
    fnp.stack((inv, i2), axis=0, out=powers)
    # Batch the ordered gate queries; every packet is the current PRE frame.
    fnp.multiply(alpha, phi, out=qcols[1])
    if R is not None:
        if xsr is None:
            fnp.sum(R2, axis=1, out=cols[0])
        else:
            fnp.copyto(cols[0], xsr[:, 0])  # paid current PRE row-r2, not a constant.
        fnp.abs(R, out=work)
        fnp.sum(work, axis=1, out=cols[1])
        fnp.max(work, axis=1, out=cols[2])
        # Same top-eight multiset; ordering/roundoff need active-value qualification.
        # partition has no out=; this read-only input returns one priced n*n temp.
        top = fnp.partition(R2, R2.shape[1]-8, axis=1)
        fnp.sum(top[:, -8:], axis=1, out=cols[3])
        del top
        fnp.stack((phi, Phi, alpha), axis=1, out=queries3)
        fnp.matmul(R2, queries3, out=v['messages3'])
        fnp.put_along_axis(F, v['r2indexes'], v['messages3'], axis=1)
        fnp.multiply(mu, inv, out=cols[8])
        fnp.stack((alpha, cols[8]), axis=1, out=queries2)
        fnp.matmul(R, queries2, out=v['messages2'])
        fnp.put_along_axis(F, v['rindexes'], v['messages2'], axis=1)
    if D21 is not None:
        fnp.multiply(D21, v['i2col'], out=N)
        fnp.multiply(N, v['ivrow'], out=N)
        _mR = (Phi >= 0.01).astype(fnp.float32) if support is None else support
        fnp.multiply(N, _mR[:, None], out=N)
        fnp.multiply(N, _mR if _CF_RPCB_R3C else _mR[None, :], out=N)
        fnp.multiply(N, N, out=work)
        fnp.sum(work, axis=1, out=cols[9])
        fnp.sum(work, axis=0, out=cols[10])
        fnp.matmul(N, phi, out=cols[12])
        fnp.matmul(v['NT'], phi, out=cols[13])
        if R is not None:
            fnp.multiply(N, R, out=other)
            fnp.sum(other, axis=1, out=cols[11])
            if state['mask46_required']:
                fnp.copyto(cols[46], 1.0)
    if pk11 is not None and state['keep_pk_energy']:
        tensors = (pk11, pk21, pk22)
        if wk431 is not None and state['keep_wk431_energy']:
            tensors += (wk431,)
        if K31F is not None and state['keep_k31_energy']:
            if wk431 is None:
                raise RuntimeError('Fitted K31 phase lacks the current wk431 supplier')
            tensors += (K31F,)
        pack, rows, rowsT, indexes = batch_plans[len(tensors)]
        fnp.stack(tensors, axis=0, out=pack)
        fnp.multiply(pack, pack, out=pack)
        fnp.sum(pack, axis=2, out=rows)
        fnp.put_along_axis(F, indexes, rowsT, axis=1)
        fnp.sum(v['batch_pk21'], axis=0, out=cols[16])
        if K31F is not None and state['keep_k31_energy']:
            fnp.sum(v['batch_k31'], axis=0, out=cols[21])
    if pk11 is not None and R is not None and state['keep_pk_energy']:
        fnp.multiply(pk11, R, out=work)
        fnp.sum(work, axis=1, out=cols[18])
    if K31F is not None and state['mask45_required']:
        fnp.copyto(cols[45], 1.0)
    if li > 0 and state['prev_li'] == li-1:
        fnp.matmul(W, pcols[0], out=cols[22])
        fnp.multiply(pcols[0], pcols[0], out=v['message_cols'][0])
        fnp.stack((v['message_cols'][0], pcols[1], pcols[2]), axis=1, out=queries3)
        fnp.matmul(WW, queries3, out=v['neighbors'])
    if state['wc_li'] == li:
        fnp.multiply(v['wcU'], v['i2col'], out=v['signed'])
        fnp.true_divide(v['wcV'], v['wcAcol'], out=v['magnitude'])
        fnp.multiply(v['wcA'], i2, out=cols[36])
        fnp.multiply(v['wcJ'], i4, out=cols[37])
        if state['mask44_required']:
            fnp.copyto(cols[44], 1.0)
    # Q's numeric values are carried only within this predict, never across MLPs.
    if li < 15:
        q = qcols
        fnp.copyto(q[0], Phi)
        if D3 is None:
            fnp.copyto(q[2], 0.0)
        else:
            fnp.multiply(D3, i3, out=q[2])
        if g4 is None:
            fnp.copyto(q[3], 0.0)
        else:
            fnp.multiply(g4, i4, out=q[3])
        fnp.add(cols[0], 1.0, out=q[4])
        fnp.true_divide(cols[0], q[4], out=q[4])
    fnp.stack((zeros_n, cols[0], cols[9]), axis=1, out=prev)
    state['prev_li'] = state['frame_li'] = li
    core._cc_ta_feature_hits += 1


def _cc_ta_apply(core, li, alive, feats, xa, xb, xs, one, pl, local311, base_delta, c4, current_delta):
    state = _cc_ta_require_valid(core)
    # prev excludes the new correction; REPLACE uses the C4-off training base.
    reference = base_delta if state['mode'] == 'replace' else current_delta
    fnp.put_along_axis(state['pcols'][0], alive, reference, axis=0)
    if li < 1:
        return current_delta
    if state['kind'] == 'ridge':
        beta_message, beta_local = state['ridge_plans'][li-1]
        raw = fnp.take(state['frame'], alive, axis=0)
        messages = raw @ beta_message
        gates = state['head_gate_prefixes'][alive.shape[0]]
        fnp.stack((one, pl, local311[:, 16], local311[:, 17]), axis=1, out=gates)
        message = fnp.einsum('ij,ij->i', messages, gates)
        local = local311 @ beta_local
        extra = local+message
    else:
        nl = fnp.take(state['frame'], alive, axis=0)
        raw = fnp.concatenate((feats, xa, xb, xs, nl), axis=1)
        z = (raw-state['means'][li-1])*state['inverse'][li-1]
        fnp.clip(z, -8.0, 8.0, out=z)
        code = fnp.broadcast_to(state['codes'][li], (alive.shape[0], 16))
        x = fnp.concatenate((z, code), axis=1)
        h1 = fnp.maximum(x@state['W1']+state['b1'], 0.0)
        h2 = fnp.maximum(h1@state['W2']+state['b2'], 0.0)
        extra = (h2@state['W3']+state['b3'])[:, 0]*state['yscale'][li-1]
    core._cc_ta_head_hits += 1
    return reference+extra



_BD_Q = ((1024, 1024, 1024, 1024, 1024, 992, 960, 928, 928, 896, 864, 864, 832, 832, 800) if _CF_BQW else ((1024, 1024, 1024, 1024, 1024, 1024, 1024, 928, 928, 896, 864, 864, 832, 832, 800)))

