"""Metered, frame-explicit kernels; no labels, numpy or learned fitting.

Embed this file into the pinned parent namespace (fnp/flops/math). The same
functions can be imported with a namespace supplied by a shape-cost probe.
"""


def basis10(xp,mu,sigma,alpha,phi,Phi,D3,g4,head,base,out):
    s=xp.maximum(sigma,1e-6);s2=xp.multiply(s,s)
    s3=xp.multiply(s2,s);s4=xp.multiply(s2,s2)
    xp.stack((xp.ones_like(mu),mu,s,alpha,phi,Phi,
        xp.true_divide(D3,s3),xp.true_divide(g4,s4),head,base),axis=1,out=out)
    return s


def same60(xp,C,D,basis,sigma,scratch,query,out):
    """Six two-operand matmuls, one NN scratch, no input tensor mutation."""
    if C is None or D is None:
        xp.copyto(out,0.0);return
    inv=xp.true_divide(1.0,sigma);i2=xp.multiply(inv,inv)
    i3=xp.multiply(i2,inv);i4=xp.multiply(i2,i2)
    # Keep diagonal-zero semantics of the exported literal training inputs.
    # A copied raw kernel and its immediate 10-column reduction share NN storage.
    operations=((C,None,inv,inv,False),(C,C,i2,i2,False),
        (D,None,inv,i2,False),(D,None,i2,inv,True),
        (C,D,i2,i3,False),(D,D,i2,i4,False))
    for q,(left,right,column_scale,row_scale,transpose) in enumerate(operations):
        if right is None:xp.copyto(scratch,left)
        else:xp.multiply(left,right,out=scratch)
        xp.fill_diagonal(scratch,0.0)
        xp.multiply(basis,column_scale[:,None],out=query)
        target=out[:,q*10:(q+1)*10]
        xp.matmul(scratch.T if transpose else scratch,query,out=target)
        xp.multiply(target,row_scale[:,None],out=target)


def leg10(xp,A,P,ka,weights,work,reduction,out,valid_rows):
    """Full defined young+confined set; borrow only dead dslice work slabs.

    weights(k,n,4) = cc,w4,w4/vp^4,u, in each source's birth-column frame.
    work is existing xt/yt/u/t scratch, not new (k,n,n) numeric allocations.
    No einsum (in particular no SDK float64 shape-inference dummies).
    """
    k=A.shape[0];m=int(valid_rows);xp.copyto(out,0.0)
    if not k or not m:return
    a=A[:,:m];p=P[:,:m]
    X,Y,Z,T=[_cf_view(work[name], (slice(None, k), slice(None, m))) for name in ('xt','yt','u','t')]
    red=reduction[:k,:m,:1]
    xp.multiply(a,a,out=X);xp.multiply(a,p,out=Y);xp.multiply(p,p,out=Z)
    def contract(matrix,column_weights):
        xp.matmul(matrix,column_weights[:,:,None],out=red)
        return red
    def summed(matrix,column_weights):
        contract(matrix,column_weights)
        return xp.sum(red,axis=0)[:,0]
    # F4/F5 use the literal dense represented carriers in current row order.
    xp.sum(Z,axis=2,out=red[:,:,0])
    xp.sum(red,axis=0,out=out[:m,4:5])
    xp.sum(X,axis=2,out=red[:,:,0])
    xp.sum(red,axis=0,out=out[:m,5:6])
    xp.multiply(Y,Y,out=T)
    xp.sum(T,axis=2,out=red[:,:,0])
    xp.sum(red,axis=0,out=out[:m,9:10])
    contract(T,weights[:k,:,0])
    xp.multiply(xp.sum(red[ka:],axis=0)[:,0],6.0,out=out[:m,0])
    if ka:xp.multiply(xp.sum(red[:ka],axis=0)[:,0],6.0,out=out[:m,1])
    # A^4 P and newest A^3 P preserve the fixed E feature definitions.
    xp.multiply(X,X,out=T);xp.multiply(T,p,out=T)
    xp.multiply(summed(T,weights[:k,:,1]),5.0,out=out[:m,2])
    xp.multiply(_cf_view(X, k-1),_cf_view(Y, k-1),out=_cf_view(T, k-1))
    xp.matmul(_cf_view(T, k-1),_cf_view(weights, (k-1,slice(None),1)),out=_cf_view(out, (slice(None,m),3)))
    contract(a,weights[:k,:,3]);xp.sum(red,axis=0,out=out[:m,6:7])
    contract(p,weights[:k,:,3]);xp.sum(red,axis=0,out=out[:m,7:8])
    xp.multiply(Z,Z,out=T)
    contract(T,weights[:k,:,2]);xp.sum(red,axis=0,out=out[:m,8:9])


def gelu_inplace(xp,normal_cdf,values,work,activation):
    if activation=='exact_erf':
        # torch.nn.GELU(approximate='none') = x * Phi(x).
        if _CF_RPCB_R5B: xp.multiply(values,normal_cdf(values),out=values,dtype=xp.float32)   # Claude-F RPCB R5b: same cast inside the ufunc
        else: xp.multiply(values,xp.asarray(normal_cdf(values),dtype=xp.float32),out=values)
    elif activation=='tanh':
        xp.multiply(values,values,out=work);xp.multiply(work,values,out=work)
        xp.multiply(work,0.044715,out=work);xp.add(work,values,out=work)
        xp.multiply(work,0.7978845608028654,out=work);xp.tanh(work,out=work)
        xp.add(work,1.0,out=work);xp.multiply(work,0.5,out=work)
        xp.multiply(values,work,out=values)
    else:raise ValueError('The exported activation tag must be explicit')


def mlp_delta(xp,normal_cdf,raw,li,model,work,activation):
    cols=raw.shape[1];t=li-6;x,h1,h2,tmp,result=work
    _xc = _cf_view(x, (slice(None), slice(None, cols)))
    xp.subtract(raw,_cf_view(model['norm_mean'], t),out=_xc)
    xp.true_divide(_xc,_cf_view(model['norm_std'], t),out=_xc)
    xp.clip(_xc,-8.0,8.0,out=_xc)
    xp.copyto(_cf_view(x, (slice(None), slice(cols, None))),0.0);xp.copyto(_cf_view(x, (slice(None), cols+t)),1.0)
    xp.matmul(x,model['W1'].T,out=h1);xp.add(h1,model['b1'],out=h1)
    gelu_inplace(xp,normal_cdf,h1,tmp,activation)
    xp.matmul(h1,model['W2'].T,out=h2);xp.add(h2,model['b2'],out=h2)
    gelu_inplace(xp,normal_cdf,h2,tmp,activation)
    xp.matmul(h2,model['W3'].T,out=result);xp.add(result,model['b3'],out=result)
    xp.multiply(result,model['target_scale'][t],out=result)
    return result[:,0]

_C_EDGE_PARAMETERS={'W1': _hxl_n('', 'f', (64, 121)), 'b1': _hxl_n('', 'f', (64,)), 'W2': _hxl_n('', 'f', (64, 64)), 'b2': _hxl_n('', 'f', (64,)), 'W3': _hxl_n('', 'f', (1, 64)), 'b3': [0.08632208406925201], 'norm_mean': _hxl_n('', 'f', (10, 111)), 'norm_std': _hxl_n('', 'f', (10, 111)), 'target_scale': [3.9543810999020934e-05, 4.2982886952813715e-05, 4.561571040540002e-05, 4.8326499381801113e-05, 5.0725851906463504e-05, 5.278700700728223e-05, 5.483883069246076e-05, 5.688379314960912e-05, 5.877801595488563e-05, 6.076292265788652e-05]}
_C_EDGE_COLS=111
_C_EDGE_ACTIVATION='exact_erf'

"""Production adapter embedded after the original83 module and kernel code.

The builder supplies _C_EDGE_PARAMETERS, _C_EDGE_COLS and the exported
_C_EDGE_ACTIVATION. All runtime arithmetic uses the metered SDK namespace.
"""


class _CEdgeState:
    def __init__(self,n):
        self.n=n;self.cols=_C_EDGE_COLS
        def alloc(shape):
            return fnp.zeros(shape,dtype=fnp.float32)
        self.model={key:fnp.asarray(_C_EDGE_PARAMETERS[key],dtype=fnp.float32)
            for key in ('W1','b1','W2','b2','W3','b3','norm_mean','norm_std','target_scale')}
        self.scratch=alloc((n,n)) if self.cols>=81 else None
        # Age-split D21 (tier) carriers: copies of the per-layer pieces, live only inside one layer.
        _r=int(globals().get('_CF_R1',352));self.tier_r=_r   # shared old-basis width (rank builds define _CF_R1)
        self.tier_t=alloc((2,n,_r));self.tier_qc=alloc((n,_r))
        self.tier_g=alloc((_r,10));self.tier_d=alloc((2,n));self.tier_mask=alloc((n,))
        self.tier_li=-1;self.tier_m=0;self.tier_have=[False,False,False]
        self.nn=(alloc((n,self.cols+10)),alloc((n,64)),alloc((n,64)),
            alloc((n,64)),alloc((n,1)))
        # Per-layer lifetime: PRE leg -> basis/queries/six contractions ->
        # normalization may overwrite raw only after all contractions finish.
        self.raw=self.nn[0][:,:self.cols]
        self.basis=self.raw[:,:10];self.leg=self.raw[:,11:21]
        self.query=alloc((n,10));self.base=alloc((n,))
        self.birth_weights=alloc((15,n,4));self.red=alloc((15,n,1))
        self.generation=0;self.packet=None;self.count=0;self.normalized=[];self.hits={};self.last={}

    def begin(self):
        self.generation+=1;self.packet=None;self.count=0;self.normalized=[];self.hits={}
        self.tier_li=-1;self.tier_have=[False,False,False]

    def finish(self):
        self.last=dict(generation=self.generation,hits=dict(self.hits),births=self.count,
            packet_released=True,mode='add predicted residual to existing original83 head')
        self.packet=None;self.count=0;self.normalized=[]


def _c_edge_birth(core,li,alpha,sigma,phi,Phi,K2v,K4v,w2):
    s=getattr(core,'_c_edge',None)
    if s is None:return
    slot=s.count
    if slot>=15:raise ValueError('Unexpected extra source birth')
    if getattr(s,'ce_ok',False) and ((str(K2v.dtype)=='float32' and str(K4v.dtype)=='float32') if _CF_RPCB_R6 else (K2v.dtype==fnp.float32 and K4v.dtype==fnp.float32)):
        W0,W1,W2,W3=_ce_bw_cols(s,slot)
        v=fnp.maximum(K2v,1e-4);v2=fnp.multiply(v,v)
        fnp.true_divide(K4v,v2,out=W1)
        fnp.copyto(W0,w2)
        fnp.true_divide(W1,fnp.multiply(v2,v2),out=W2)
        fnp.multiply(sigma,fnp.add(fnp.multiply(alpha,Phi),phi),out=W3)
        s.count+=1;s.normalized.append(False)
        return
    W=_cfv(s.birth_weights,slot);v=fnp.maximum(K2v,1e-4);v2=fnp.multiply(v,v)
    w4=fnp.true_divide(K4v,v2)
    fnp.copyto(_cfv(W,(slice(None),0)),w2);fnp.copyto(_cfv(W,(slice(None),1)),w4)
    fnp.true_divide(w4,fnp.multiply(v2,v2),out=_cfv(W,(slice(None),2)))
    fnp.multiply(sigma,fnp.add(fnp.multiply(alpha,Phi),phi),out=_cfv(W,(slice(None),3)))
    s.count+=1;s.normalized.append(False)


def _c_edge_keep(core,keep):
    s=getattr(core,'_c_edge',None)
    if s is not None and s.count:
        fnp.multiply(_cf_view(s.birth_weights, (s.count-1, slice(None), 3)),keep,out=_cf_view(s.birth_weights, (s.count-1, slice(None), 3)))


def _c_edge_birth_permute(core,order):
    s=getattr(core,'_c_edge',None)
    if s is not None and s.count:
        W=_ce_bw_slot(s,s.count-1) if getattr(s,'ce_ok',False) else s.birth_weights[s.count-1];fnp.copyto(W,fnp.take(W,order,axis=0))


def _c_edge_pre(core,li,mu,sigma,alpha,phi,Phi,D3,g4,C,D,A,P,ka,ns,bufs,rfb):
    s=getattr(core,'_c_edge',None)
    if s is None:return
    s.packet=None
    if not 6<=li<=15:return
    if A is None or P is None or bufs is None or rfb!=0:
        raise ValueError('Exported83 feature ABI requires the original R_FB=0 dense carriers')
    k=A.shape[0]
    if k!=s.count:raise ValueError('Birth/leg generation mismatch')
    if getattr(s,'ce_ok',False):
        _ce_normalize_pending(s,k)
        _ce_leg10(s,A,P,ka,bufs,ns)
        s.packet=(li,s.generation,mu,sigma,alpha,phi,Phi,D3,g4,C,D)
        return
    for slot in range(k):
        if not s.normalized[slot]:
            u=s.birth_weights[slot,:,3]
            norm=fnp.sqrt(fnp.sum(fnp.multiply(u,u)))
            fnp.true_divide(u,fnp.maximum(norm,1e-20),out=u);s.normalized[slot]=True
    # xt/yt/u/t contain no live future input after _dslices when R_FB=0.
    leg10(fnp,A,P,ka,s.birth_weights[:k],bufs,s.red,s.leg,ns)
    s.packet=(li,s.generation,mu,sigma,alpha,phi,Phi,D3,g4,C,D)


def _c_edge_apply(core,li,head,alive,base_delta):
    s=getattr(core,'_c_edge',None)
    if s is None or not 6<=li<=15:return head
    if s.packet is None or s.packet[:2]!=(li,s.generation):
        raise ValueError('Missing/stale current-layer feature packet')
    _,_,mu,sigma,alpha,phi,Phi,D3,g4,C,D=s.packet
    fnp.copyto(s.base,0.0);fnp.put_along_axis(s.base,alive,base_delta,axis=0)
    if getattr(s,'ce_ok',False):
        sig=_ce_basis10(s,mu,sigma,alpha,phi,Phi,D3,g4,head)
        fnp.subtract(head,s.base,out=s.ce_raw10)
    else:
        sig=basis10(fnp,mu,sigma,alpha,phi,Phi,D3,g4,head,s.base,s.basis)
        fnp.subtract(head,s.base,out=s.raw[:,10])
    if s.cols>=111:
        # Must run before same60: the young piece lives in s.scratch until here.
        _c_tier_apply(s,li,sig,_ce_v(s).ce_raw81 if getattr(s,'ce_ok',False) else s.raw[:,81:111])
    if s.cols>=81:
        if getattr(s,'ce_ok',False):
            _ce_same60(s,C if li!=15 else None,D if li!=15 else None,sig)
        else:
            same60(fnp,C if li!=15 else None,D if li!=15 else None,
                s.basis,sig,s.scratch,s.query,s.raw[:,21:81])
    # E trained R = original83 post-head local residual, not C4-off T.
    # Both exported models therefore ADD to the existing head on all rows.
    if _C_A_ON: _a_fill_pre(core, s, li, sig)
    _x3_fill(s,li,sig)
    if li == 15 and _L15APP_ON: _l15app_apply(core, s, head)
    correction=_x3_mlp_delta(fnp,flops.stats.norm.cdf,s.raw,li,s.model,s.nn,_C_EDGE_ACTIVATION,s)
    fnp.add(head,correction,out=head)
    s.hits[li]=s.hits.get(li,0)+1;s.packet=None
    return head


def _c_tier_state(core):
    s=getattr(core,'_c_edge',None)
    return s if (s is not None and s.cols>=111) else None


def _c_tier_begin(core,li):
    s=_c_tier_state(core)
    if s is None:return
    s.tier_li=li if 6<=li<=14 else -1;s.tier_have=[False,False,False]


def _c_tier_t(core,j,piece):
    """j=0: tier-1 aggregate before the lift; j=1: tier-2 lift.  (m,352) copied, rows >= m are never read unmasked."""
    s=_c_tier_state(core)
    if s is None or s.tier_li<0:return
    m,r=piece.shape
    if r!=s.tier_r:raise ValueError('Tier carrier width differs from the shared old-basis width')
    fnp.copyto(_cf_view(_ce_v(s).ce_tt[j] if getattr(s,'ce_ok',False) else s.tier_t[j], slice(None, m)),piece);s.tier_have[j+1]=True


def _c_tier_young(core,young,Qc,m,keep):
    s=_c_tier_state(core)
    if s is None or s.tier_li<0:return
    m=int(m)
    if Qc.shape[1]!=s.tier_r:raise ValueError('Tier carrier width differs from the shared old-basis width')
    fnp.copyto(_cf_view(s.scratch, (slice(None, m), slice(None, m))),_cf_view(young, (slice(None, m), slice(None, m))));fnp.copyto(_cf_view(s.tier_qc, slice(None, m)),_cf_view(Qc, slice(None, m)))
    if keep is None and m==s.n and getattr(s,'ce_ok',False):fnp.copyto(s.tier_mask,1.0)
    else:
        fnp.copyto(s.tier_mask,0.0)
        if keep is None:fnp.copyto(_cf_view(s.tier_mask, slice(None, m)),1.0)
        else:fnp.put_along_axis(s.tier_mask,keep,1.0,axis=0)
    s.tier_m=m;s.tier_have[0]=True


def _c_tier_apply(s,li,sigma,out):
    """out (n,30) = [Dn_young V, Dn_t1 V, Dn_t2 V] in the current frame; zero when this layer has no capture."""
    if getattr(s,'ce_ok',False) and out is s.ce_raw81:
        return _ce_tier_apply(s,li,sigma,out)
    fnp.copyto(out,0.0)
    if s.tier_li!=li or not s.tier_have[0]:return
    inv=fnp.true_divide(1.0,sigma)
    colw=fnp.multiply(inv,s.tier_mask);roww=fnp.multiply(colw,inv)
    q=s.query;fnp.multiply(s.basis,colw[:,None],out=q)
    # Young: full contiguous scratch; rows/cols outside the live set meet zero query rows / zero row weights.
    fnp.fill_diagonal(s.scratch,0.0);fnp.matmul(s.scratch,q,out=out[:,0:10])
    if s.tier_have[1] or s.tier_have[2]:
        for j in (0,1):
            if not s.tier_have[j+1]:fnp.copyto(s.tier_t[j],0.0)
        n=out.shape[0];o=out[:,10:30].reshape(n,2,10).transpose(1,0,2)        # (2,n,10) view: t1 | t2
        fnp.matmul(s.tier_qc.T,q,out=s.tier_g);fnp.matmul(s.tier_t,s.tier_g,out=o)
        # Diagonal of t Qc^T without forming it; the copied carriers are dead after this layer.
        fnp.multiply(s.tier_t,s.tier_qc,out=s.tier_t);fnp.sum(s.tier_t,axis=2,out=s.tier_d)
        fnp.subtract(o,fnp.multiply(s.tier_d[:,:,None],q),out=o)
    fnp.multiply(out,roww[:,None],out=out)
    s.tier_have=[False,False,False];s.tier_li=-1


_c_edge_original_setup=Estimator.setup
_c_edge_original_predict=Estimator.predict


def _c_edge_setup(self,ctx):
    _c_edge_original_setup(self,ctx)
    self.core._c_edge=_CEdgeState(ctx.width) if (ctx.width,ctx.depth)==(1024,16) else None


def _c_edge_predict(self,mlp,budget):
    s=getattr(self.core,'_c_edge',None)
    if s is not None:s.begin()
    try:return _c_edge_original_predict(self,mlp,budget)
    finally:
        if s is not None:s.finish()


Estimator.setup=_c_edge_setup
Estimator.predict=_c_edge_predict


# Claude-P: mark the setup window for the view-batching helpers (predict path stays byte- and op-identical).
_cp_original_setup = Estimator.setup


def _cp_setup_window(self, ctx):
    _CP_IN_SETUP[0] = True
    try:
        return _cp_original_setup(self, ctx)
    finally:
        _CP_IN_SETUP[0] = False


Estimator.setup = _cp_setup_window


# ======================= Claude-S DFS-2 (2026-10-14) =======================
# One more Strassen-Winograd level inside eligible fused leaves, executed depth-first with the
# parent's own 22-op / 2-temporary schedule (outputs used as scratch, inputs never overwritten).
# Eligible = prepared Stage1 callplans whose plan function is _stage1_plan_mm_2_fused or
# _stage1_plan_mm_3_fused, no structural-zero runs, leaf (h, q, v) all even and q >= CS_DFS2_MINQ.
# Inner temporaries are views of setup colour arenas that the root does not use (checked).
import types as _cs_types
import functools as _cs_functools
_CS_DFS2 = True
_CS_DFS2_MINQ = 128
_CS_DFS2_ARENAS = {
    2352: ("keep_L1_343", "keep_M1_343", "keep_N1_343", "keep_R1_343"),    # R48 hub children (P48 roots)
    343: ("keep_L1_2401", "keep_R1_2401", "keep_M1_2401", "keep_N1_2401"),  # level-4 P1 roots
}
_CS_DFS2_P = (2352,)
_CS_DFS2_TOP = {2352: (48, 336, 2352), 343: (1, 7, 49, 343)}
_CS_DFS2_TABLE = {}
_CS_DFS2_INFO = {"converted": [], "skipped": []}


def _cs_dfs2_inner(A11, A12, A21, A22, B11, B12, B21, B22, C11, C12, C21, C22, L, R, M, N,
                   _add=fnp.add, _sub=fnp.subtract, _mm=fnp.matmul):
    _add(A21, A22, out=L)
    _sub(B12, B11, out=R)
    _mm(L, R, out=C22)
    _sub(L, A11, out=L)
    _sub(B22, R, out=R)
    _mm(L, R, out=C12)
    _sub(A12, L, out=L)
    _mm(L, B22, out=C21)
    _sub(R, B21, out=R)
    _mm(A22, R, out=C11)
    _sub(A11, A21, out=L)
    _sub(B22, B12, out=R)
    _mm(L, R, out=M)
    _mm(A11, B11, out=N)
    _add(C12, N, out=C12)
    _add(M, C12, out=M)
    _add(C12, C22, out=C12)
    _add(C12, C21, out=C12)
    _sub(M, C11, out=C21)
    _add(M, C22, out=C22)
    _mm(A12, B21, out=C11)
    _add(C11, N, out=C11)


def _cs_dfs2_matmul(A, B, out=None, _get=_CS_DFS2_TABLE.get, _mm=fnp.matmul):
    entry = _get((id(A), id(B), id(out)))
    if entry is None or entry[0] is not A or entry[1] is not B or entry[2] is not out:
        return _mm(A, B, out=out)
    _cs_dfs2_inner(*entry[3])
    return out


class _CSFnpProxy:
    """fnp with matmul routed through the DFS-2 dispatcher (only used by the mm_2 clone)."""
    __slots__ = ()
    matmul = staticmethod(_cs_dfs2_matmul)

    def __getattr__(self, name):
        return getattr(fnp, name)


_cs_mm2_globals = dict(_stage1_plan_mm_2_fused.__globals__)
_cs_mm2_globals["fnp"] = _CSFnpProxy()
_cs_plan_mm_2_dfs2 = _cs_types.FunctionType(
    _stage1_plan_mm_2_fused.__code__, _cs_mm2_globals, "_cs_plan_mm_2_dfs2",
    _stage1_plan_mm_2_fused.__defaults__, _stage1_plan_mm_2_fused.__closure__)
_cs_plan_mm_3_dfs2 = _cs_functools.partial(_stage1_plan_mm_3_fused, _matmul=_cs_dfs2_matmul)


def _cs_dfs2_convert(self, roots):
    arenas_by_name = getattr(self, "_color_arenas", None) or {}
    quarter_cache = {}

    def quarters(array):
        hit = quarter_cache.get(id(array))
        if hit is None or hit[0] is not array:
            hit = (array, tuple(self._quarters(array)))
            quarter_cache[id(array)] = hit
        return hit[1]

    r48_backings = tuple(self.pool[k][0] for k in (("M1", 16807), ("R1", 16807), ("N1", 16807))
                         if k in self.pool)
    for key in tuple(roots):
        plan = self._callplans.get(key)
        if plan is None:
            continue
        function, layers, leaf = plan
        if function is _stage1_plan_mm_2_fused:
            LXQ, LYQ, LOQ, Lb, Rb, Mb, Nb, zbp = leaf
            X11, X12, X21, X22 = LXQ
            Y11, Y12, Y21, Y22 = LYQ
            C11, C12, C21, C22 = LOQ
            new_function = _cs_plan_mm_2_dfs2
        elif function is _stage1_plan_mm_3_fused:
            (X11, X12, X21, X22, Y11, Y12, Y21, Y22, C11, C12, C21, C22,
             Lb, Rb, Mb, Nb, zbp) = leaf
            new_function = _cs_plan_mm_3_dfs2
        else:
            continue
        bx, P, h, q = Lb.shape
        v = Rb.shape[-1]
        if any(len(z) for z in zbp):
            _CS_DFS2_INFO["skipped"].append((key, "zero-runs"))
            continue
        if h % 2 or q % 2 or v % 2 or q < _CS_DFS2_MINQ or min(h, v) < 8 or P not in _CS_DFS2_ARENAS or P not in _CS_DFS2_P:
            continue
        names = _CS_DFS2_ARENAS[P]
        arenas = tuple(arenas_by_name.get(name) for name in names)
        if any(a is None for a in arenas) or len({id(a) for a in arenas}) != 4:
            _CS_DFS2_INFO["skipped"].append((key, "arena-missing"))
            continue
        used = {id(entry[0]) for (role, p), entry in self.pool.items()
                if p in _CS_DFS2_TOP[P] and role in ("L", "R", "M", "L1", "R1", "M1", "N1")}
        if P == 2352:
            used |= {id(b) for b in r48_backings}
        if any(id(a) in used for a in arenas):
            _CS_DFS2_INFO["skipped"].append((key, "arena-busy"))
            continue
        h2, q2, v2 = h // 2, q // 2, v // 2
        need = (bx * P * h2 * q2, bx * P * q2 * v2, bx * P * h2 * v2, bx * P * h2 * v2)
        ok = True
        for role, arena, size in zip(("L2", "R2", "M2", "N2"), arenas, need):
            entry = self.pool.get((role, P))
            if entry is None:
                self.pool[(role, P)] = (arena, {}, [])
            elif entry[0] is not arena:
                ok = False
            if arena.size < size:
                ok = False
        if not ok:
            _CS_DFS2_INFO["skipped"].append((key, "arena-size"))
            continue
        generation = self._scratch_generation
        L2 = self._buf(("L2", P, h2, q2), (bx, P, h2, q2))
        R2 = self._buf(("R2", P, q2, v2), (bx, P, q2, v2))
        M2 = self._buf(("M2", P, h2, v2), (bx, P, h2, v2))
        N2 = self._buf(("N2", P, h2, v2), (bx, P, h2, v2))
        if self._scratch_generation != generation or not self._colored_active:
            raise RuntimeError("Claude-S DFS-2 temporaries grew scratch")
        temps = (L2, R2, M2, N2)
        for A, B, C in ((Lb, Rb, C22), (Lb, Rb, C12), (Lb, Y22, C21), (X22, Rb, C11),
                        (Lb, Rb, Mb), (X11, Y11, Nb), (X12, Y21, C11)):
            views = quarters(A) + quarters(B) + quarters(C) + temps
            _CS_DFS2_TABLE[(id(A), id(B), id(C))] = (A, B, C, views)
        self._callplans[key] = (new_function, layers, leaf)
        _CS_DFS2_INFO["converted"].append((key, (h, q, v), P))


_cs_dfs2_prepare_callplans_parent = _StrassenV29.prepare_callplans


def _cs_dfs2_prepare_callplans(self, roots):
    _cs_dfs2_prepare_callplans_parent(self, roots)
    if _CS_DFS2 and getattr(self, "_colored_active", False):
        _cs_dfs2_convert(self, roots)


_StrassenV29.prepare_callplans = _cs_dfs2_prepare_callplans
# ===================== end Claude-S DFS-2 =====================


# ================= Claude-S MEM: warm the last-layer D3 einsum cost cache (2026-10-14) =================
# flopscope builds 3 float64 np.empty dummies (operand shapes) for the cost analysis of a 3-operand
# einsum; at the last layer ("kij,kij,kij->i", (15,1024,1024) x3) this is a 360 MiB transient on top of
# the largest predict pool = the worker VmPeak.  The result is LRU-cached by (subscripts, shapes,
# symmetry fingerprint, operand-identity pattern), so one identical-signature call at setup (zero-stride
# broadcast views, operands 0 and 1 the same object) moves that transient into setup.  Predictions and
# predict FLOPs are unchanged.
_CS_MEMWARM = True
_cs_mem_setup_parent = Estimator.setup


def _cs_mem_setup(self, ctx):
    _cs_mem_setup_parent(self, ctx)
    if not _CS_MEMWARM or (ctx.width, ctx.depth) != (1024, 16):
        return
    try:
        k, n = ctx.depth - 1, ctx.width
        seed = fnp.zeros((1, 1, 1), dtype=fnp.float32)
        same = fnp.broadcast_to(seed, (k, n, n))
        other = fnp.broadcast_to(seed, (k, n, n))
        fnp.einsum("kij,kij,kij->i", same, same, other)
        del same, other, seed
    except Exception:  # noqa: BLE001  a cache hint must never fail setup
        pass


Estimator.setup = _cs_mem_setup
# ================= end Claude-S MEM =================


# ======================= Claude-I FBW v2: leaf Winograd with odd peeling (2026-10-14) =======================
import functools as _ci_fbw2_functools
_CI_FBW2 = _os.environ.get("CI_FBW2", "1") != "0"
_CI_FBW2_MIN_RATIO = float(_os.environ.get("CI_FBW2_MIN_RATIO", "0"))
_CI_FBW2_MIN = float(_os.environ.get("CI_FBW2_MIN_MF", "20")) * 1e6
if _CF_BQW:
    _CI_FBW2_KEYS = frozenset((('mm', (1, 1, 1024, 2048), (1, 1, 2048, 1024), 5), ('mm', (1, 1, 960, 224), (1, 1, 224, 4096), 4), ('mm', (1, 1, 960, 224), (1, 1, 224, 6144), 4), ('mm', (1, 1, 960, 224), (1, 1, 224, 8192), 4), ('mm', (1, 1, 960, 4096), (1, 1, 4096, 224), 4), ('mm', (1, 1, 960, 6144), (1, 1, 6144, 224), 4), ('mm', (1, 1, 960, 8192), (1, 1, 8192, 224), 4), ('mm', (1, 48, 240, 224), (1, 48, 224, 2048), 4), ('mm', (1, 48, 240, 224), (1, 48, 224, 2096), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2144), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2160), 4), ('mm', (1, 48, 256, 256), (1, 48, 256, 1040), 4), ('mm', (1, 48, 256, 256), (1, 48, 256, 1552), 4), ('mm', (1, 48, 256, 256), (1, 48, 256, 2064), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2128), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2096), 4), ('mm', (1, 48, 240, 224), (1, 48, 224, 2016), 4)))
else:
    _CI_FBW2_KEYS = frozenset((('mm', (1, 1, 1024, 2048), (1, 1, 2048, 1024), 5), ('mm', (1, 1, 960, 224), (1, 1, 224, 4096), 4), ('mm', (1, 1, 960, 224), (1, 1, 224, 6144), 4), ('mm', (1, 1, 960, 224), (1, 1, 224, 8192), 4), ('mm', (1, 1, 960, 4096), (1, 1, 4096, 224), 4), ('mm', (1, 1, 960, 6144), (1, 1, 6144, 224), 4), ('mm', (1, 1, 960, 8192), (1, 1, 8192, 224), 4), ('mm', (1, 48, 240, 224), (1, 48, 224, 2048), 4), ('mm', (1, 48, 240, 224), (1, 48, 224, 2096), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2144), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2160), 4), ('mm', (1, 48, 256, 256), (1, 48, 256, 1040), 4), ('mm', (1, 48, 256, 256), (1, 48, 256, 1552), 4), ('mm', (1, 48, 256, 256), (1, 48, 256, 2064), 4)))
# Claude-I C2L56 v1 (10/20): FBW2 on the transport L5-6 leaf (FASTMM C2; default on, CI_C2L56=0 = parent statements)
_CI_C2L56 = _os.environ.get("CI_C2L56", "1") == "1"
if _CI_C2L56 and _CI_FBW2_KEYS is not None:
    _CI_FBW2_KEYS = frozenset(_CI_FBW2_KEYS) | frozenset((('mm', (1, 48, 256, 240), (1, 48, 240, 2144), 4), ('mm', (1, 48, 256, 240), (1, 48, 240, 2160), 4)))
_CI_FBW2_INFO = {"converted": [], "skipped": []}
_CI_FBW2_ACTIVE = [True]   # runtime switch for every FBW2 / F1024W / E1W dispatcher (e.g. a predict deadline guard)


def _ci_fbw2_set_active(on):
    """Turn the leaf Winograd on/off at any point (also mid-predict): off -> every converted leaf product runs the plain
    fnp.matmul on the same operands. No state crosses calls (all peel terms are inside one product), nothing is bound or
    allocated; outputs change by rounding only, FLOPs go back up."""
    _CI_FBW2_ACTIVE[0] = bool(on)


def _ci_fbw2_cost(h, q, v):
    """(F saved per leaf product, added add/sub elements per leaf product, added calls per leaf product)."""
    he, qe, ve = h - h % 2, q - q % 2, v - v % 2
    h2, q2, v2 = he // 2, qe // 2, ve // 2
    plain = h * v * (2 * q - 1)
    adds = 4 * h2 * q2 + 4 * q2 * v2 + 7 * h2 * v2
    new = 7 * h2 * v2 * (2 * q2 - 1) + adds
    calls = 21
    if q % 2:
        new += 2 * he * ve; adds += he * ve; calls += 8
    if v % 2:
        new += he * (v - ve) * (2 * q - 1); calls += 1
    if h % 2:
        new += (h - he) * v * (2 * q - 1); calls += 1
    return plain - new, adds, calls


def _ci_fbw2_inner(X11, X12, X21, X22, Y11, Y12, Y21, Y22, C11, C12, C21, C22, L, R, M, N,
                   _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    # the fused leaf's own 22-op Winograd schedule (inputs never overwritten)
    _add(X21, X22, out=L)
    _subtract(Y12, Y11, out=R)
    _matmul(L, R, out=C22)
    _subtract(L, X11, out=L)
    _subtract(Y22, R, out=R)
    _matmul(L, R, out=C12)
    _subtract(X12, L, out=L)
    _matmul(L, Y22, out=C21)
    _subtract(R, Y21, out=R)
    _matmul(X22, R, out=C11)
    _subtract(X11, X21, out=L)
    _subtract(Y22, Y12, out=R)
    _matmul(L, R, out=M)
    _matmul(X11, Y11, out=N)
    _add(C12, N, out=C12)
    _add(M, C12, out=M)
    _add(C12, C22, out=C12)
    _add(C12, C21, out=C12)
    _subtract(M, C11, out=C21)
    _add(M, C22, out=C22)
    _matmul(X12, Y21, out=C11)
    _add(C11, N, out=C11)


def _ci_fbw2_run(views, rank1, colv, rowh, _add=fnp.add, _matmul=fnp.matmul):
    _ci_fbw2_inner(*views)
    if rank1 is not None:                       # q odd: C_even += A[:, qe:] @ B[qe:, :]
        M = views[14]
        for a_, b_, c_ in rank1:
            _matmul(a_, b_, out=M)
            _add(c_, M, out=c_)
    if colv is not None:                        # v odd: last columns of the even rows
        _matmul(colv[0], colv[1], out=colv[2])
    if rowh is not None:                        # h odd: last row(s), all columns
        _matmul(rowh[0], rowh[1], out=rowh[2])


class _CiFbw2MM:
    """Per-root leaf-product dispatcher: prepared (A, B, C) triples run the peeled Winograd, anything else is plain."""
    __slots__ = ("tab", "owner", "gen")

    def __init__(self, tab, owner, gen):
        self.tab, self.owner, self.gen = tab, owner, gen

    def __call__(self, A, B, out=None):
        hit = self.tab.get((id(A), id(B), id(out)))
        if (not _CI_FBW2_ACTIVE[0] or hit is None or hit[0] is not A or hit[1] is not B or hit[2] is not out
                or self.owner._scratch_generation != self.gen or not self.owner._colored_active):
            return fnp.matmul(A, B, out=out)
        (_ci_fbw2_run_alt if _CI_FMA_W[0] else _ci_fbw2_run)(*hit[3].get())   # Claude-I FMA: FBW2-level basis
        return out


class _CfF3MM(_CiFbw2MM):
    """Claude-F FBW3FIRST v2: BQW56 transport FBW2 dispatcher, plain product on the first predict after a setup (requests)."""
    __slots__ = ()

    def __call__(self, A, B, out=None):
        if _CF_DL_ON and _CF_DL_FIRST[0] and _CF_DL_FIRST_LEFT[0] == _CF_DL_FIRST_N:
            return fnp.matmul(A, B, out=out)
        return _CiFbw2MM.__call__(self, A, B, out)


def _ci_fbw2_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb):
    X11, X12, X21, X22 = XQ
    Y11, Y12, Y21, Y22 = YQ
    C11, C12, C21, C22 = OQ
    return ((Lb, Rb, C22), (Lb, Rb, C12), (Lb, Y22, C21), (X22, Rb, C11), (Lb, Rb, Mb), (X11, Y11, Nb), (X12, Y21, C11))


def _ci_fbw2_tables(owner, triples, h, q, v, free, vc):
    """Views of every triple + 4 temporaries placed first-fit-decreasing in `free` [(size, name, arena)]; None if no room."""
    he, qe, ve = h - h % 2, q - q % 2, v - v % 2
    h2, q2, v2 = he // 2, qe // 2, ve // 2
    A0, B0, C0 = triples[0]
    lead_a, lead_b, lead_c = tuple(A0.shape[:-2]), tuple(B0.shape[:-2]), tuple(C0.shape[:-2])
    shp = (lead_a + (h2, q2), lead_b + (q2, v2), lead_c + (h2, v2), lead_c + (h2, v2))
    need = tuple(int(_np_prod(x)) for x in shp)
    room = {nm: size for size, nm, a in free}
    place = [None] * 4
    for t in sorted(range(4), key=lambda t: -need[t]):
        for size, nm, a in free:
            if room[nm] >= need[t]:
                place[t] = (nm, a, size - room[nm])
                room[nm] -= need[t]
                break
    if any(p is None for p in place):
        return None
    def cached(k_, obj, make):
        hit_ = vc.get(k_)
        if hit_ is None or hit_[0] is not obj:
            hit_ = (obj, make())
            vc[k_] = hit_
        return hit_[1]
    temps = [cached(("T", nm, off, shp[t]), a, lambda a=a, off=off, t=t: _cf_keep_rs(a[off:off + need[t]], shp[t]))
             for t, (nm, a, off) in enumerate(place)]
    tab = {}
    for A, B, C in triples:
        k3 = (id(A), id(B), id(C))
        if k3 in tab:
            continue
        tab[k3] = (A, B, C, _CiFbw2Lazy(_ci_fbw2_views_of(A, B, C, h, q, v, temps, cached)))
    return tab, "+".join(sorted({nm for nm, a, off in place}))


class _CiFbw2Lazy:
    """Slice views of one leaf-product triple, made on its first dispatch (free getitems) and kept."""
    __slots__ = ("make", "val")

    def __init__(self, make):
        self.make, self.val = make, None

    def get(self):
        v = self.val
        if v is None:
            v = self.val = self.make()
            self.make = None
        return v


def _ci_fbw2_views_of(A, B, C, h, q, v, temps, cached):
    he, qe, ve = h - h % 2, q - q % 2, v - v % 2
    h2, q2, v2 = he // 2, qe // 2, ve // 2

    def make():
        Av = cached(("A", id(A), h, q, v % 2), A, lambda A=A: (A[..., :h2, :q2], A[..., :h2, q2:qe], A[..., h2:he, :q2], A[..., h2:he, q2:qe],
                                                        (A[..., :h2, qe:], A[..., h2:he, qe:]) if q > qe else None,
                                                        A[..., :he, :] if v > ve else None, A[..., he:, :] if h > he else None))
        Bv = cached(("B", id(B), q, v), B, lambda B=B: (B[..., :q2, :v2], B[..., :q2, v2:ve], B[..., q2:qe, :v2], B[..., q2:qe, v2:ve],
                                                        (B[..., qe:, :v2], B[..., qe:, v2:ve]) if q > qe else None,
                                                        B[..., :, ve:] if v > ve else None))
        Cv = cached(("C", id(C), h, v), C, lambda C=C: (C[..., :h2, :v2], C[..., :h2, v2:ve], C[..., h2:he, :v2], C[..., h2:he, v2:ve],
                                                        C[..., :he, ve:] if v > ve else None, C[..., he:, :] if h > he else None))
        views = tuple(Av[:4]) + tuple(Bv[:4]) + tuple(Cv[:4]) + tuple(temps)
        rank1 = None
        if q > qe:
            (a1, a2), (b1, b2) = Av[4], Bv[4]
            rank1 = ((a1, b1, Cv[0]), (a1, b2, Cv[1]), (a2, b1, Cv[2]), (a2, b2, Cv[3]))
        colv = (Av[5], Bv[5], Cv[4]) if v > ve else None
        rowh = (Av[6], B, Cv[5]) if h > he else None
        return (views, rank1, colv, rowh)
    return make


def _np_prod(t):
    r = 1
    for x in t:
        r *= int(x)
    return r


def _ci_fbw2_free_arenas(self, used_ids):
    arenas = getattr(self, "_color_arenas", None) or {}
    return sorted(((a.size, nm, a) for nm, a in arenas.items() if id(a) not in used_ids and nm not in _CI_ACAP_CAPS), key=lambda t: t[0])   # Claude-I ACAP


def _ci_fbw2_convert(self, roots):
    r48 = tuple(self.pool[k][0] for k in (("M1", 16807), ("R1", 16807), ("N1", 16807)) if k in self.pool)
    vc = self.__dict__.setdefault("_ci_fbw2_views", {})
    for key in tuple(roots):
        plan = self._callplans.get(key)
        if plan is None or key[0] != "mm":
            continue
        fn, layers, leaf = plan
        if fn is _ci_cf_plan:
            XQ, YQ, OQ, Lb, Rb, Mb, Nb = leaf
            mk = lambda d: _ci_fbw2_functools.partial(_ci_cf_plan, _matmul=d)
        elif fn is _stage1_plan_mm_3_fused or fn is _stage1_plan_mm_4_fused:
            if len(leaf) != 17 or any(len(z) for z in leaf[16]):
                continue
            XQ, YQ, OQ = leaf[0:4], leaf[4:8], leaf[8:12]
            Lb, Rb, Mb, Nb = leaf[12:16]
            mk = (lambda d, fn=fn: _ci_fbw2_functools.partial(fn, _matmul=d))
        else:
            continue
        bx, P, h, q = Lb.shape
        by, v = Rb.shape[0], Rb.shape[-1]
        # cf5d: copy-free roots DFS-2 would have converted keep their extra Winograd level through FBW v2
        _dfs2like = (_CI_CF5D and fn is _ci_cf_plan and P in globals().get("_CS_DFS2_P", ())
                     and q >= globals().get("_CS_DFS2_MINQ", 1 << 30) and not (h % 2 or q % 2 or v % 2 or min(h, v) < 8))
        if _CI_FBW2_KEYS is not None and key not in _CI_FBW2_KEYS and not _dfs2like:
            continue
        if min(h, q, v) < 8:
            continue
        sav, adds, calls = _ci_fbw2_cost(h, q, v)
        if not _dfs2like and (sav <= 0 or 7 * P * sav < _CI_FBW2_MIN or sav < _CI_FBW2_MIN_RATIO * adds):
            continue
        P0 = key[1][1]
        alias = {48: 49, 336: 343, 2352: 2401, 16464: 16807} if P0 == 48 else {}
        bfsP, p_ = set(), P0
        while p_ < P:
            bfsP |= {p_, alias.get(p_, p_)}
            p_ *= 7
        leafP = {P, alias.get(P, P)}
        used = {id(entry[0]) for (role, p), entry in self.pool.items()
                if (p in bfsP and role in ("L", "R", "M")) or (p in leafP and role in ("L1", "R1", "M1", "N1"))}
        used |= {id(b) for b in r48}
        gen = self._scratch_generation
        got = _ci_fbw2_tables(self, _ci_fbw2_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb)
                              + (_ci_fma_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb) if (_CI_FMA and fn is _ci_cf_plan) else ()),   # Claude-I FMA
                              h, q, v, _ci_fbw2_free_arenas(self, used), vc)
        if got is None:
            _CI_FBW2_INFO["skipped"].append((key, "no-free-arena"))
            continue
        if self._scratch_generation != gen or not self._colored_active:
            raise RuntimeError("Claude-I FBW2 views grew scratch")
        tab, where = got
        if _CI_FMA and _CI_FMA_LAZYV and fn is _ci_cf_plan:   # Claude-F FMA v10: alternative-only products build on first dispatch
            _ci_fma_fp1_pop(tab, XQ, YQ, OQ, Lb, Rb, Mb, Nb)
        self._callplans[key] = (mk((_CfF3MM if (_CF_FBW3FIRST and key in _CF_FBW3FIRST_KEYS) else _CiFbw2MM)(tab, self, gen)),
                                layers, leaf)   # Claude-F FBW3FIRST v2: the three transport keys get the first-predict type
        if _CI_FMA and _CI_FMA_SETUPV and fn is _ci_cf_plan:   # Claude-I FMA v3: alternative-basis views at setup
            _ci_fma_setup_views(layers, leaf, self._callplans[key][0])
        _CI_FBW2_INFO["converted"].append((key, (h, q, v), P, where, getattr(fn, "__name__", str(fn))))
        if key in _cf_fp1skip_keys():   # Claude-F FP1SKIP v2: these leaves make their views on first dispatch, not in FP1
            for _cf_ent in tab.values():
                _CI_FP1_LAZY_TAB.pop(id(_cf_ent[3]), None)


_ci_fbw2_prepare_callplans_parent = _StrassenV29.prepare_callplans


def _ci_fbw2_prepare_callplans(self, roots):
    _ci_fbw2_prepare_callplans_parent(self, roots)
    if _CI_FBW2 and getattr(self, "_colored_active", False):
        _ci_fbw2_convert(self, roots)
    if _CI_FMA and _CI_FMA_SETUPV and _CI_FMA_ROOTS == "all":   # Claude-I FMA v4: plain cf roots' views at setup
        for key in tuple(roots):
            plan = self._callplans.get(key)
            if plan is not None and key[0] == "mm" and plan[0] is _ci_cf_plan:
                _ci_fma_setup_views(plan[1], plan[2], plan[0])


_StrassenV29.prepare_callplans = _ci_fbw2_prepare_callplans
# ===================== end Claude-I FBW v2 =====================


# ======================= Claude-I F1024W: peeled leaf Winograd in the Full1024 fused leaf (2026-10-14) =======================
_CI_F1024W = _os.environ.get("CI_F1024W", "1") != "0"
_CI_F1024_TAB = {}
_CI_F1024_INFO = {}
_CI_F1024_GEN_TAB = {}   # {"own": owner, "gen": scratch generation} the table was built for; guard-visible name


def _ci_f1024_mm(A, B, out=None):
    hit = _CI_F1024_TAB.get((id(A), id(B), id(out)))
    own = _CI_F1024_GEN_TAB.get("own")
    gen = _CI_F1024_GEN_TAB.get("gen")
    if (not _CI_FBW2_ACTIVE[0] or hit is None or hit[0] is not A or hit[1] is not B or hit[2] is not out
            or own is None or own._scratch_generation != gen or not own._colored_active):
        return fnp.matmul(A, B, out=out)
    _ci_fbw2_run(*hit[3].get())
    return out


def _ci_f1024_build(owner):
    _CI_F1024_TAB.clear()
    _CI_F1024_GEN_TAB.clear()
    plan = getattr(owner, "_cc_full1024_plan", None)
    if not _CI_F1024W or plan is None or not getattr(owner, "_colored_active", False):
        return
    XQ, YQ, OQ, Lb, Rb, Mb, Nb = plan[17], plan[18], plan[19], plan[20], plan[21], plan[22], plan[23]
    h, q = Lb.shape[-2], Lb.shape[-1]
    v = Rb.shape[-1]
    arenas = getattr(owner, "_color_arenas", None) or {}
    busy = {nm for _k, nm, _r in _CC_FULL1024_BACKING_REQUIREMENTS}
    r48 = {id(owner.pool[k][0]) for k in (("M1", 16807), ("R1", 16807), ("N1", 16807)) if k in owner.pool}
    free = sorted(((a.size, nm, a) for nm, a in arenas.items() if nm not in busy and id(a) not in r48 and nm not in _CI_ACAP_CAPS), key=lambda t: t[0])   # Claude-I ACAP
    gen = owner._scratch_generation
    got = _ci_fbw2_tables(owner, _ci_fbw2_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb), h, q, v, free,
                          owner.__dict__.setdefault("_ci_fbw2_views", {}))
    if got is None:
        _CI_F1024_INFO["skipped"] = "no-free-arena"
        return
    tab, where = got
    picked = [arenas[nm] for nm in where.split("+")]
    probes = tuple(XQ) + tuple(YQ) + tuple(OQ) + (Lb, Rb, Mb, Nb)
    if any(bool(fnp.shares_memory(a, t)) for a in picked for t in probes):
        _CI_F1024_INFO["skipped"] = "arena-busy"
        return
    if owner._scratch_generation != gen or not owner._colored_active:
        raise RuntimeError("Claude-I F1024W views grew scratch")
    _CI_F1024_TAB.update(tab)
    _CI_F1024_GEN_TAB["own"], _CI_F1024_GEN_TAB["gen"] = owner, gen
    _CI_F1024_INFO.update(converted=(h, q, v), arenas=where)


_ci_f1024_prepare_parent = _cc_full1024_prepare


def _cc_full1024_prepare(owner):
    _ci_f1024_prepare_parent(owner)
    _ci_f1024_build(owner)
# ===================== end Claude-I F1024W =====================


# ======================= Claude-I E1W: peeled leaf Winograd in the E1 hub's R48 children (2026-10-14) =======================
import types as _ci_e1w_types
_CI_E1W = _os.environ.get("CI_E1W", "1") != "0"
_CI_E1W_MIN_RATIO = float(_os.environ.get("CI_E1W_MIN_RATIO", "1.5"))
_CI_E1W_TAB = {}
_CI_E1W_INFO = {"converted": [], "skipped": []}


class _CiE1wFnp:
    """fnp with matmul routed through the E1W table (only used by the mm_2 clone)."""
    __slots__ = ()

    @staticmethod
    def matmul(A, B, out=None):
        hit = _CI_E1W_TAB.get((id(A), id(B), id(out)))
        if (not _CI_FBW2_ACTIVE[0] or hit is None or hit[0] is not A or hit[1] is not B or hit[2] is not out
                or hit[4][0]._scratch_generation != hit[4][1] or not hit[4][0]._colored_active):
            return fnp.matmul(A, B, out=out)   # unknown triple, or any scratch growth since setup
        (_ci_fbw2_run_alt if _CI_FMA_W[0] else _ci_fbw2_run)(*hit[3].get())   # Claude-I FMA v5: E1W FBW2-level basis
        return out

    def __getattr__(self, name):
        return getattr(fnp, name)


_ci_e1w_globals = dict(_stage1_plan_mm_2_fused.__globals__)
_ci_e1w_globals["fnp"] = _CiE1wFnp()
_ci_plan_mm_2_e1w = _ci_e1w_types.FunctionType(
    _stage1_plan_mm_2_fused.__code__, _ci_e1w_globals, "_ci_plan_mm_2_e1w",
    _stage1_plan_mm_2_fused.__defaults__, _stage1_plan_mm_2_fused.__closure__)


def _ci_e1w_convert(bank, key, m, k, n, level):
    ex = bank.executor
    entry = bank.r48.get(key)
    if entry is None or not getattr(ex, "_colored_active", False):
        return
    x, y, o, blocks, rows, child, quarters = entry
    fn, layers, leaf = child
    if fn is not _stage1_plan_mm_2_fused or len(leaf) != 8 or any(len(z) for z in leaf[7]):
        _CI_E1W_INFO["skipped"].append((key, "plan"))
        return
    LXQ, LYQ, LOQ, Lb, Rb, Mb, Nb, zbp = leaf
    h, q, v = Lb.shape[-2], Lb.shape[-1], Rb.shape[-1]
    sav, adds, calls = _ci_fbw2_cost(h, q, v)
    if min(h, q, v) < 8 or sav <= 0 or sav < _CI_E1W_MIN_RATIO * adds:
        _CI_E1W_INFO["skipped"].append((key, "ratio", (h, q, v)))
        return
    used = set()
    for role, P, shape, paired in _cc_r48_20_geometry(m, k, n, level):
        e = ex.pool.get((role, P))
        if e is not None:
            used.add(id(e[0]))
    used |= {id(ex.pool[kk][0]) for kk in (("M1", 16807), ("R1", 16807), ("N1", 16807)) if kk in ex.pool}
    gen = ex._scratch_generation
    got = _ci_fbw2_tables(ex, _ci_fbw2_triples(LXQ, LYQ, LOQ, Lb, Rb, Mb, Nb), h, q, v,
                          _ci_fbw2_free_arenas(ex, used), ex.__dict__.setdefault("_ci_fbw2_views", {}))
    if got is None:
        _CI_E1W_INFO["skipped"].append((key, "no-free-arena"))
        return
    tab, where = got
    if ex._scratch_generation != gen or not ex._colored_active:
        raise RuntimeError("Claude-I E1W views grew scratch")
    _CI_E1W_TAB.update({k3: e + ((ex, gen),) for k3, e in tab.items()})
    bank.r48[key] = (x, y, o, blocks, rows, (_ci_plan_mm_2_e1w, layers, leaf), quarters)
    _CI_E1W_INFO["converted"].append((key, (h, q, v), Lb.shape[1], where))


_ci_e1w_prepare_r48_parent = _BE1Plans.prepare_r48


def _ci_e1w_prepare_r48(self, m, k, n, level, x, y, out):
    key = _ci_e1w_prepare_r48_parent(self, m, k, n, level, x, y, out)
    if _CI_E1W:
        _ci_e1w_convert(self, key, m, k, n, level)
    return key


_BE1Plans.prepare_r48 = _ci_e1w_prepare_r48
# ===================== end Claude-I E1W =====================


# ======================= Claude-I cf5n: nested R48 child inputs built at setup (2026-10-14) =======================
def _ci_cf5n_build(owner):
    if not _CI_CF5N or not getattr(owner, "_colored_active", False):
        return
    ids = getattr(owner, "_predict_view_ids", None)
    if ids is None:
        return
    for pkey, arrays in getattr(owner, "_r48_views", {}).items():
        L4, R4, P4 = arrays[0], arrays[1], arrays[2]
        plan = owner._callplans.get(("mm", tuple(L4.shape), tuple(R4.shape), pkey[3] - 2))
        if plan is None or getattr(plan[0], "func", plan[0]) is not _ci_cf_plan:
            continue
        (Lm, Ls, XQk), (Rm, Rs, YQk), _dec = plan[1][0]
        for arr, shp in ((L4, XQk), (R4, YQk)):
            if shp is None:
                continue
            owner._remember_quarters_only(arr, ids)
            for q_ in owner._quarters(arr):
                hit = _CI_CF5_NEST.get(id(q_))
                if hit is None or hit[0] is not q_:
                    _CI_CF5_NEST[id(q_)] = (q_, fnp.reshape(q_, shp))
        owner._remember_quarters_only(P4, ids)


_ci_cf5n_prepare_r48_parent = _cb_prepare_r48


def _cb_prepare_r48(owner):
    _ci_cf5n_prepare_r48_parent(owner)
    _ci_cf5n_build(owner)
