_CI_R48V_MAIN_TAB = {}       # id(plan) -> (plan, gen, pl, pr, pp, h, q, v)
_CI_R48V_FIX_TAB = {}        # site key -> (anchor, gen, (pl, pr, pp))
_CI_R48V_VC_TAB = {}         # (gen, structural key) -> view
