def _ci_r48v_grid(Xt, sel):
    _, i0, di, j0, dj, k = sel
    if k == 1:
        return Xt[i0, j0]
    if di == 0:
        e = j0 + k * dj
        return Xt[i0, j0:(e if e >= 0 else None):dj]
    e = i0 + k * di
    return Xt[i0:(e if e >= 0 else None):di, j0]


class _CiR48vViews:
    """Structural view cache for one generation; dry mode only counts the views that would be created."""
    __slots__ = ("gen", "dry", "new")

    def __init__(self, gen, dry):
        self.gen, self.dry, self.new = gen, dry, 0

    def get(self, key, make):
        k = (self.gen,) + key
        v = _CI_R48V_VC_TAB.get(k)
        if v is None:
            self.new += 1
            if self.dry:
                return None
            v = _CI_R48V_VC_TAB[k] = make()
        return v


def _ci_r48v_bind(ops, Pk, P, Prows, Wk, W, Wrows, vw, Gk=None, Xt=None):
    """Resolve refs: k=1 slab refs -> the site's own row views; k>=2 slab slices and (setup-owned grid) selectors ->
    cached views; caller-owned grid selectors stay tuples (resolved per call)."""
    def ref(r):
        if r is None:
            return None, 0
        if r[0] == 'G' or (r[0] == 'B' and r[1] == 'G'):
            sel = ('G', r[1], r[2], r[3], r[4], r[5]) if r[0] == 'G' else ('G', r[2], 0, r[3], 0, 1)
            if Gk is None:
                return sel, 1
            return vw.get(Gk + (sel,), lambda: _ci_r48v_grid(Xt, sel)), 0
        if r[0] == 'B':
            return (Prows if r[1] == 'P' else Wrows)[r[2]], 0
        kind, s0, d, k = r
        rows, slab, key = (Prows, P, Pk) if kind == 'P' else (Wrows, W, Wk)
        if k == 1:
            return rows[s0], 0
        e = s0 + k * d
        return vw.get(key + (s0, d, k), lambda: slab[s0:(e if e >= 0 else None):d]), 0
    outp = []
    for t, o, a, b in ops:
        (vo, go), (va, ga), (vb, gb) = ref(o), ref(a), ref(b)
        outp.append(({'add': 0, 'sub': 1, 'div2': 2, 'copy': 3}[t], vo, va, vb, go | (ga << 1) | (gb << 2)))
    return tuple(outp)


def _ci_r48v_exec(prog, Xt, _add=fnp.add, _sub=fnp.subtract, _div=fnp.divide, _copy=fnp.copyto, _two=_CB_R48_TWO,
                  _grid=_ci_r48v_grid, g=None):
    if g is None:                       # Claude-I VSTAB: a persistent grid-view dict per live operand
        g = {}
    for code, o, a, b, gm in prog:
        if gm:
            if gm & 1:
                v = g.get(o)
                if v is None:
                    v = g[o] = _grid(Xt, o)
                o = v
            if gm & 2:
                v = g.get(a)
                if v is None:
                    v = g[a] = _grid(Xt, a)
                a = v
            if gm & 4:
                v = g.get(b)
                if v is None:
                    v = g[b] = _grid(Xt, b)
                b = v
        if code == 0:
            _add(a, b, out=o)
        elif code == 1:
            _sub(a, b, out=o)
        elif code == 2:
            _div(a, _two, out=o)
        else:
            _copy(o, a)


def _ci_r48v_fits(L4, LW, RW, PW):
    P_ = _CI_R48V_PROG
    return (L4.shape[1] == 48 and LW.shape[0] >= P_["left"]["W"] and RW.shape[0] >= P_["right"]["W"]
            and PW.shape[0] >= P_["post"]["W"])


def _ci_r48v_build(vw, slabs, rows, a, b, c, grids):
    """slabs = callables/arrays for (L4, R4, P4, LW, RW, PW); grids = None (caller-owned) or (Gkey, Xt, Yt, Ot) getters."""
    P_ = _CI_R48V_PROG
    L4, R4, P4, LW, RW, PW = slabs
    LO, RO, PI, LWr, RWr, PWr = rows
    l0 = vw.get(("L0", id(L4)), lambda: ((_ci_sd_v(L4, 0) if _CF_KEEP_ON[0] else L4[0]) if _CF_B_SETUP_REUSE else L4[0]))
    r0 = vw.get(("R0", id(R4)), lambda: ((_ci_sd_v(R4, 0) if _CF_KEEP_ON[0] else R4[0]) if _CF_B_SETUP_REUSE else R4[0]))
    p0 = vw.get(("P0", id(P4)), lambda: ((_ci_sd_v(P4, 0) if _CF_KEEP_ON[0] else P4[0]) if _CF_B_SETUP_REUSE else P4[0]))
    gx = gy = go = (None, None)
    if grids is not None:
        gk, X2, Y2, O2 = grids
        gx = (gk + ("X",), vw.get(gk + ("X",), lambda: fnp.swapaxes(fnp.reshape(X2[0, 0], (4, a, 4, b)), 1, 2)))
        gy = (gk + ("Y",), vw.get(gk + ("Y",), lambda: fnp.swapaxes(fnp.reshape(Y2[0, 0], (4, b, 4, c)), 1, 2)))
        go = (gk + ("O",), vw.get(gk + ("O",), lambda: fnp.swapaxes(fnp.reshape(O2[0, 0], (4, a, 4, c)), 1, 2)))
    pl = _ci_r48v_bind(P_["left"]["ops"], ("L", id(L4)), l0, LO, ("LW", id(LW)), LW, LWr, vw, gx[0], gx[1])
    pr = _ci_r48v_bind(P_["right"]["ops"], ("R", id(R4)), r0, RO, ("RW", id(RW)), RW, RWr, vw, gy[0], gy[1])
    pp = _ci_r48v_bind(P_["post"]["ops"], ("P", id(P4)), p0, PI, ("PW", id(PW)), PW, PWr, vw, go[0], go[1])
    return pl, pr, pp


def _ci_r48v_try(gen, site, build):
    """build(views) -> programs.  A dry run counts every view the site still needs (nothing is created); the real build
    runs only when that count fits this predict's remaining budget.  Known-too-big sites skip the dry run."""
    st = _CI_R48V_STATE_TAB
    if st.get("gen") != gen:
        _CI_R48V_VC_TAB.clear()
        _CI_R48V_NEED_TAB.clear()
        st["gen"] = gen
    left = st.get("left", 0)
    need = _CI_R48V_NEED_TAB.get(site)
    if need is not None and need > left:
        _CI_R48V_INFO["deferred"] += 1
        return None
    dry = _CiR48vViews(gen, True)
    build(dry)
    _CI_R48V_NEED_TAB[site] = dry.new
    if dry.new > left:
        _CI_R48V_INFO["deferred"] += 1
        return None
    vw = _CiR48vViews(gen, False)
    progs = build(vw)
    st["left"] = left - vw.new
    _CI_R48V_INFO["views"] += vw.new
    return progs


def _ci_r48v_fixed(ex, site, anchor, r48_owner, x, y, out, rows):
    """Setup-owned x/y/out site: (pl, pr, pp) with every view cached, or None (parent programs this call)."""
    gen = ex._scratch_generation
    e = _CI_R48V_FIX_TAB.get(site)
    if e is not None and e[0] is anchor and e[1] == gen:
        return e[2]
    a, b, c = x.shape[2] // 4, x.shape[3] // 4, y.shape[3] // 4
    if (x.shape[2] != 4 * a or x.shape[3] != 4 * b or y.shape[2] != 4 * b or y.shape[3] != 4 * c
            or out.shape[2] != 4 * a or out.shape[3] != 4 * c):
        return None
    base = tuple(r48_owner._r48_views.values())
    if not base:
        return None
    leaders = tuple(tuple((p[i].shape[-2], p[i].shape[-1], p[i]) for p in base) for i in range(6))
    if _CF_FROM12_KEYS_V9 and (x.shape[2], x.shape[3], y.shape[3]) in ((576,768,9920),(640,768,9920)):
        leaders = r48_owner._f12_e1_raw_leaders
    P_ = _CI_R48V_PROG
    if (base[0][0].shape[1] != 48 or base[0][3].shape[0] < P_["left"]["W"] or base[0][4].shape[0] < P_["right"]["W"]
            or base[0][5].shape[0] < P_["post"]["W"]):
        return None                                   # slot counts are role constants: checked without new views
    shp = ((0, a, b), (1, b, c), (2, a, c), (3, a, b), (4, b, c), (5, a, c))
    names = ("L4", "R4", "P4", "LW", "RW", "PW")
    grids = (("site", id(x), id(y), id(out)), x, y, out)

    def build(vw):
        if _CF_FROM12_KEYS_V9 and (x.shape[2], x.shape[3], y.shape[3]) in ((576,768,9920),(640,768,9920)):
            slabs = tuple(vw.get(("f12-e1-slab", id(r48_owner), nm, H, Q), lambda i=i, H=H, Q=Q: _cb_r48_pick_v3(leaders[i], H, Q))
                          for nm, (i, H, Q) in zip(names, shp))
        else:
            slabs = tuple(vw.get(("slab", nm, H, Q), lambda i=i, H=H, Q=Q: _cb_r48_pick_v3(leaders[i], H, Q))
                          for nm, (i, H, Q) in zip(names, shp))
        return _ci_r48v_build(vw, slabs, rows, a, b, c, grids)
    progs = _ci_r48v_try(gen, site, build)
    if progs is None:
        return None
    _CI_R48V_FIX_TAB[site] = (anchor, gen, progs)
    _CI_R48V_INFO["fixed"] += 1
    return progs


_ci_r48v_parent_run = _cb_r48_run


def _cb_r48_run(owner, X, Y, out, lev, plan):
    gen = owner._scratch_generation
    e = _CI_R48V_MAIN_TAB.get(id(plan))
    if e is None or e[0] is not plan or e[1] != gen:
        e = None
        if _CI_R48V:
            L4, R4, P4, LW, RW, PW, rows = plan
            h, q, v = L4.shape[2], L4.shape[3], R4.shape[3]
            if _ci_r48v_fits(L4, LW, RW, PW) and X.shape[2] == 4 * h and X.shape[3] == 4 * q and Y.shape[3] == 4 * v:
                progs = _ci_r48v_try(gen, id(plan), lambda vw: _ci_r48v_build(vw, (L4, R4, P4, LW, RW, PW), rows, h, q, v, None))
                if progs is not None:
                    e = _CI_R48V_MAIN_TAB[id(plan)] = (plan, gen) + progs + (h, q, v)
                    _CI_R48V_INFO["main"] += 1
        if e is None:
            return _ci_r48v_parent_run(owner, X, Y, out, lev, plan)
    _, _, pl, pr, pp, h, q, v = e
    if _CI_VSTAB:                       # Claude-I VSTAB: grid operand + its grid views kept per live X / Y / out
        Xt, gx = _ci_r48t(X, h, q)
        Yt, gy = _ci_r48t(Y, q, v)
        Ot, go = _ci_r48t(out, h, v)
        _ci_r48v_exec(pl, Xt, g=gx)
        _ci_r48v_exec(pr, Yt, g=gy)
        owner.mm(plan[0], plan[1], plan[2], lev - 2)
        _ci_r48v_exec(pp, Ot, g=go)
        return out
    _ci_r48v_exec(pl, fnp.swapaxes(fnp.reshape(X[0, 0], (4, h, 4, q)), 1, 2))
    _ci_r48v_exec(pr, fnp.swapaxes(fnp.reshape(Y[0, 0], (4, q, 4, v)), 1, 2))
    owner.mm(plan[0], plan[1], plan[2], lev - 2)
    _ci_r48v_exec(pp, fnp.swapaxes(fnp.reshape(out[0, 0], (4, h, 4, v)), 1, 2))
    return out


_ci_r48v_prep_parent = _cb_prepare_r48


def _cb_prepare_r48(owner):
    _CI_R48V_MAIN_TAB.clear()
    _CI_R48V_FIX_TAB.clear()
    _CI_R48V_VC_TAB.clear()
    _CI_R48V_STATE_TAB.clear()
    _CI_R48V_NEED_TAB.clear()
    return _ci_r48v_prep_parent(owner)


_CI_R48V_TABS = ("_CI_R48V_MAIN_TAB", "_CI_R48V_FIX_TAB", "_CI_R48V_VC_TAB", "_CI_R48V_STATE_TAB", "_CI_R48V_NEED_TAB")


def _ci_r48v_release():
    for _nm in _CI_R48V_TABS + tuple(globals().get("_CI_R48V_EXTRA_TABS", ())):
        globals()[_nm].clear()


if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):      # guard collected its list before these tables existed
    _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | set(_CI_R48V_TABS)))

_ci_r48v_setup_parent = Estimator.setup


def _ci_r48v_setup(self, ctx):
    _ci_r48v_release()                                         # before any new arena of this setup
    return _ci_r48v_setup_parent(self, ctx)


Estimator.setup = _ci_r48v_setup

_ci_r48v_begin_parent = _cc_d21_c_begin


def _cc_d21_c_begin(core, n, L, r, rfb, prune, owner, ta_active, pool):
    _CI_R48V_STATE_TAB["left"] = _CI_R48V_BUDGET            # once per predict: fresh lazy-view budget
    return _ci_r48v_begin_parent(core, n, L, r, rfb, prune, owner, ta_active, pool)
