_CI_K363V_TAB = {}


def _ci_k363v_build(vw, sl, plan):
    LO, RO, PI, LW, RW, PW, padX, padY, pout, nLO, nRO, nPI, nLW, nRW, nPW = sl
    LOr, ROr, PIr, LWr, RWr, PWr, _XI, _YI, nLOr, nROr, nPIr, nLWr, nRWr, nPWr = plan[:14]
    K, R = _CI_K363V_PROG, _CI_R48V_PROG
    B, h, q = LO.shape
    v = RO.shape[2]
    key = ("k363", id(plan))
    gX = vw.get(key + ("gX",), lambda: fnp.swapaxes(fnp.reshape(padX, (3, h, 6, q)), 1, 2))
    gY = vw.get(key + ("gY",), lambda: fnp.swapaxes(fnp.reshape(padY, (6, q, 3, v)), 1, 2))
    gO = vw.get(key + ("gO",), lambda: fnp.swapaxes(fnp.reshape(pout, (3, h, 3, v)), 1, 2))
    kl = _ci_r48v_bind(K["left"]["ops"], ("kL", id(LO)), LO, LOr, ("kLW", id(LW)), LW, LWr, vw, key + ("gX",), gX)
    kr = _ci_r48v_bind(K["right"]["ops"], ("kR", id(RO)), RO, ROr, ("kRW", id(RW)), RW, RWr, vw, key + ("gY",), gY)
    kp = _ci_r48v_bind(K["post"]["ops"], ("kP", id(PI)), PI, PIr, ("kPW", id(PW)), PW, PWr, vw, key + ("gO",), gO)
    a, b, c = h // 4, q // 4, v // 4
    nX = vw.get(key + ("nX",), lambda: fnp.transpose(fnp.reshape(LO, (B, 4, a, 4, b)), (1, 3, 0, 2, 4)))
    nY = vw.get(key + ("nY",), lambda: fnp.transpose(fnp.reshape(RO, (B, 4, b, 4, c)), (1, 3, 0, 2, 4)))
    nO = vw.get(key + ("nO",), lambda: fnp.transpose(fnp.reshape(PI, (B, 4, a, 4, c)), (1, 3, 0, 2, 4)))
    nl = _ci_r48v_bind(R["left"]["ops"], ("nL", id(nLO)), nLO, nLOr, ("nLW", id(nLW)), nLW, nLWr, vw, key + ("nX",), nX)
    nr = _ci_r48v_bind(R["right"]["ops"], ("nR", id(nRO)), nRO, nROr, ("nRW", id(nRW)), nRW, nRWr, vw, key + ("nY",), nY)
    npo = _ci_r48v_bind(R["post"]["ops"], ("nP", id(nPI)), nPI, nPIr, ("nPW", id(nPW)), nPW, nPWr, vw, key + ("nO",), nO)
    return kl, kr, kp, nl, nr, npo


def _ci_k363v_get(owner, plan):
    gen = owner._scratch_generation
    e = _CI_K363V_TAB.get(id(plan))
    if e is not None and e[0] is plan and e[1] == gen:
        return e[2]
    sl = getattr(owner, "_ci_k363v_slabs", None)
    if sl is None:
        return None
    LO, RO, PI, LW, RW, PW = sl[:6]
    nLO, nRO, nPI, nLW, nRW, nPW = sl[9:]
    K, R = _CI_K363V_PROG, _CI_R48V_PROG
    if (LO.shape[0] != 40 or LW.shape[0] < K["left"]["W"] or RW.shape[0] < K["right"]["W"] or PW.shape[0] < K["post"]["W"]
            or LO.shape[1] % 4 or LO.shape[2] % 4 or RO.shape[2] % 4 or nLO.shape[0] != 48
            or nLW.shape[0] < R["left"]["W"] or nRW.shape[0] < R["right"]["W"] or nPW.shape[0] < R["post"]["W"]):
        return None
    progs = _ci_r48v_try(gen, ("k363", id(plan)), lambda vw: _ci_k363v_build(vw, sl, plan))
    if progs is None:
        return None
    _CI_R48V_INFO["k363"] = _CI_R48V_INFO.get("k363", 0) + 1
    _CI_K363V_TAB[id(plan)] = (plan, gen, progs)
    return progs


_CI_R48V_EXTRA_TABS = ("_CI_K363V_TAB",)                     # released with the R48V tables at setup start
if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):
    _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | set(_CI_R48V_EXTRA_TABS)))
