_CI_CFE1_INFO = {"plain": [], "r48": [], "young": [], "skipped": []}
_CI_CFE1_NEST_TAB = {}       # (id(quarter), nested shape) -> (quarter, nested view), built at setup


def _ci_cfe1_first(ex, xshape, yshape, lev, tag, depth=None):
    """The copy-free plan of this root (bound first, original scratch requests mirrored), or None -> original binding."""
    if not _CI_CFE1 or tag not in _CI_CFE1_FAM or not getattr(ex, "_colored_active", False):
        return None
    xshape = tuple(int(v) for v in xshape)
    yshape = tuple(int(v) for v in yshape)
    gen = ex._scratch_generation
    cf = _ci_cf_bind(ex, xshape, yshape, lev, ("mm", xshape, yshape, lev))
    if ex._scratch_generation != gen or not ex._colored_active:
        raise RuntimeError("Claude-I CFE1b grew scratch")
    if cf is None or (depth is not None and len(cf[1]) != depth):
        _CI_CFE1_INFO["skipped"].append((tag, xshape, yshape, lev, "bind" if cf is None else "depth"))
        return None
    _CI_CFE1_INFO[tag].append((xshape, yshape, lev, len(cf[1]), cf[1][0][0][0], cf[1][0][1][0]))
    return cf


def _ci_cfe1_nest_build(cf, quarters):
    """Layer-0 boundary: nested views of FIXED input quarters, made once here instead of per call."""
    (Lm, Ls, XQk), (Rm, Rs, YQk), _dec = cf[1][0]
    for qs, mode, shp in ((quarters[0], Lm, XQk), (quarters[1], Rm, YQk)):
        if mode != "orig" or shp is None:
            continue
        for q_ in qs:
            k = (id(q_), tuple(shp))
            hit = _CI_CFE1_NEST_TAB.get(k)
            if hit is None or hit[0] is not q_:
                _CI_CFE1_NEST_TAB[k] = (q_, fnp.reshape(q_, tuple(shp)))


_ci_cfe1_nest_parent = _ci_cf5_nest


def _ci_cf5_nest(q_, shp, _reshape=fnp.reshape):
    hit = _CI_CFE1_NEST_TAB.get((id(q_), shp))
    if hit is not None and hit[0] is q_:
        return hit[1]
    return _ci_cfe1_nest_parent(q_, shp, _reshape)


def _ci_cfe1_fbw2(ex, leaf, used, tag):
    XQ, YQ, OQ, Lb, Rb, Mb, Nb = leaf
    h, q, v = Lb.shape[-2], Lb.shape[-1], Rb.shape[-1]
    gen = ex._scratch_generation
    got = _ci_fbw2_tables(ex, _ci_fbw2_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb)
                          + (_ci_fma_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb) if (_CI_FMA and _CI_FMA_E1) else ()), h, q, v,   # Claude-I FMA v5
                          _ci_fbw2_free_arenas(ex, used), ex.__dict__.setdefault("_ci_fbw2_views", {}))
    if got is not None and _CI_FMA and _CI_FMA_E1 and _CI_FMA_LAZYV:   # Claude-F FMA v10
        _ci_fma_fp1_pop(got[0], XQ, YQ, OQ, Lb, Rb, Mb, Nb)
    if ex._scratch_generation != gen or not ex._colored_active:
        raise RuntimeError("Claude-I CFE1 %s views grew scratch" % tag)
    return got, gen


# (1) E1 classical plans: Claude-F E1FW on the copy-free plan (same rules, mm_3 / mm_4 only)
def _ci_cfe1_e1fw(bank, key):
    plan = bank.plain.get(key)
    if plan is None or plan[0] is not _ci_cf_plan:
        return _cf_e1fw_convert(bank, key)
    ex = bank.executor
    if not _CF_E1FW or not getattr(ex, "_colored_active", False):
        return
    fn, layers, leaf = plan
    if len(layers) not in (3, 4):
        _CF_E1FW_INFO["skipped"].append((key, "plan"))
        return
    XQ, YQ, OQ, Lb, Rb, Mb, Nb = leaf
    bx, P, h, q = Lb.shape
    v = Rb.shape[-1]
    if min(h, q, v) < 8:
        _CF_E1FW_INFO["skipped"].append((key, "small", (h, q, v)))
        return
    sav, adds, calls = _ci_fbw2_cost(h, q, v)
    if sav <= 0 or sav < _CF_E1FW_RATIO * adds:
        _CF_E1FW_INFO["skipped"].append((key, "ratio", (h, q, v), round(sav / max(adds, 1), 2)))
        return
    bfsP, p_ = set(), 1
    while p_ < P:
        bfsP.add(p_)
        p_ *= 7
    used = {id(e[0]) for (role, p), e in ex.pool.items()
            if (p in bfsP and role in ("L", "R", "M")) or (p == P and role in ("L1", "R1", "M1", "N1"))}
    used |= {id(ex.pool[k][0]) for k in (("M1", 16807), ("R1", 16807), ("N1", 16807)) if k in ex.pool}
    got, gen = _ci_cfe1_fbw2(ex, leaf, used, "E1FW")
    if got is None:
        _CF_E1FW_INFO["skipped"].append((key, "no-free-arena"))
        return
    tab, where = got
    bank.plain[key] = (_ci_fbw2_functools.partial(_ci_cf_plan, _matmul=_CiFbw2MM(tab, ex, gen)), layers, leaf)
    if _CI_FMA and _CI_FMA_E1 and _CI_FMA_SETUPV:   # Claude-I FMA v5: E1FW root views at setup
        _ci_fma_setup_views(layers, leaf, bank.plain[key][0])
    _CF_E1FW_INFO["converted"].append((key, (h, q, v), P, where, round(sav / max(adds, 1), 2)))


def _ci_cfe1_classical(self, m, k, n, level):
    key = _cf_e1fw_classical_parent(self, m, k, n, level)
    _ci_cfe1_e1fw(self, key)
    return key


_BE1Plans.classical = _ci_cfe1_classical


# (2) E1 R48 children: Claude-I E1W on the copy-free child (same rules, mm_2 only) + setup nested input views
def _ci_cfe1_e1w(bank, key, m, k, n, level):
    entry = bank.r48.get(key)
    if entry is None or entry[5][0] is not _ci_cf_plan:
        return _ci_e1w_convert(bank, key, m, k, n, level)
    ex = bank.executor
    if not getattr(ex, "_colored_active", False):
        return
    x, y, o, blocks, rows, child, quarters = entry
    fn, layers, leaf = child
    if len(layers) != 2:
        _CI_E1W_INFO["skipped"].append((key, "plan"))
        return
    XQ, YQ, OQ, Lb, Rb, Mb, Nb = leaf
    h, q, v = Lb.shape[-2], Lb.shape[-1], Rb.shape[-1]
    sav, adds, calls = _ci_fbw2_cost(h, q, v)
    if min(h, q, v) < 8 or sav <= 0 or sav < _CI_E1W_MIN_RATIO * adds:
        _CI_E1W_INFO["skipped"].append((key, "ratio", (h, q, v)))
        return
    used = set()
    for role, P, shape, paired in _cc_r48_20_geometry(m, k, n, level):
        e = ex.pool.get((role, P))
        if e is not None:
            used.add(id(e[0]))
    used |= {id(ex.pool[kk][0]) for kk in (("M1", 16807), ("R1", 16807), ("N1", 16807)) if kk in ex.pool}
    got, gen = _ci_cfe1_fbw2(ex, leaf, used, "E1W")
    if got is None:
        _CI_E1W_INFO["skipped"].append((key, "no-free-arena"))
        return
    tab, where = got
    _CI_E1W_TAB.update({k3: e + ((ex, gen),) for k3, e in tab.items()})
    bank.r48[key] = (x, y, o, blocks, rows, (_ci_fbw2_functools.partial(_ci_cf_plan, _matmul=_CiE1wFnp.matmul), layers, leaf),
                     quarters)
    if _CI_FMA and _CI_FMA_E1 and _CI_FMA_SETUPV:   # Claude-I FMA v5: E1W root views at setup
        _ci_fma_setup_views(layers, leaf, bank.r48[key][5][0])
    _CI_E1W_INFO["converted"].append((key, (h, q, v), Lb.shape[1], where))


def _ci_cfe1_prepare_r48(self, m, k, n, level, x, y, out):
    key = _ci_e1w_prepare_r48_parent(self, m, k, n, level, x, y, out)
    entry = self.r48.get(key)
    if entry is not None and entry[5][0] is _ci_cf_plan:
        _ci_cfe1_nest_build(entry[5], entry[6])
    if _CI_E1W:
        _ci_cfe1_e1w(self, key, m, k, n, level)
    return key


