_ci_cfe1_youngw_parent = _ci_youngw_convert


def _ci_youngw_convert(owner, plan, child, bufs, apb4, gen):
    if child[0] is not _ci_cf_plan:
        return _ci_cfe1_youngw_parent(owner, plan, child, bufs, apb4, gen)
    fn, layers, leaf = child
    if not _CI_YOUNGW or _CI_YOUNGW_K <= 0 or len(layers) != 2 or not owner._colored_active:
        _CI_YOUNGW_INFO["skipped"].append("plan")
        return None
    XQ, YQ, OQ, Lb, Rb, Mb, Nb = leaf
    h, q, v = Lb.shape[-2], Lb.shape[-1], Rb.shape[-1]
    sav, adds, calls = _ci_fbw2_cost(h, q, v)
    if min(h, q, v) < 8 or sav <= 0:
        _CI_YOUNGW_INFO["skipped"].append(("ratio", (h, q, v)))
        return None
    used = set()
    cap = plan.get('cap', 864)
    for role, P, shape, paired in _cc_r48_20_geometry(cap, plan['width'], cap, 5):
        en = owner.pool.get((role, P))
        if en is not None:
            used.add(id(en[0]))
    used |= {id(owner.pool[kk][0]) for kk in (("M1", 16807), ("R1", 16807), ("N1", 16807)) if kk in owner.pool}
    used |= {id(a) for a in (getattr(owner, "_root_pack_arenas", None) or ())}
    triples = _ci_fbw2_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb)[:_CI_YOUNGW_K]
    got = _ci_fbw2_tables(owner, triples, h, q, v, _ci_fbw2_free_arenas(owner, used),
                          owner.__dict__.setdefault("_ci_fbw2_views", {}))
    if got is None:
        _CI_YOUNGW_INFO["skipped"].append("no-free-arena")
        return None
    tab, where = got
    temps = {}
    for k3, ent in tab.items():
        for t in ent[3].get()[0][12:16]:
            temps[id(t)] = t
    probes = (tuple(XQ) + tuple(YQ) + tuple(OQ) + (Lb, Rb, Mb, Nb, plan['x'], plan['y'], plan['out'],
              bufs['hub'], bufs['lap4'], apb4))
    if not _ci_fp1_yw_free(owner, used, where, probes):   # Claude-I FP1: arena-level probe first
        for t in temps.values():
            for p in probes:
                if bool(fnp.shares_memory(t, p)):
                    _CI_YOUNGW_INFO["skipped"].append("arena-busy")
                    return None
    if owner._scratch_generation != gen or not owner._colored_active:
        raise RuntimeError("Claude-I YOUNGW views grew scratch")
    _CI_E1W_TAB.update({k3: ent + ((owner, gen),) for k3, ent in tab.items()})
    _CI_YOUNGW_INFO["converted"].append(((h, q, v), len(tab), where))
    return (_ci_fbw2_functools.partial(_ci_cf_plan, _matmul=_CiE1wFnp.matmul), layers, leaf)


