# ======================= Claude-I S5L: star-D4 + (3) leg10 share monomials, byte-identical (2026-10-15) =======================
_CI_S5L = _os.environ.get("CI_S5L", "1") != "0"
_CI_S5L_AP = _os.environ.get("CI_S5L_AP", "1") == "1"     # reuse _dslices A (.) P, P (.) P slabs: NOT byte-identical (off)


_CI_S5LC = _os.environ.get("CI_S5LC", "1") != "0"   # Claude-I S5LC


def _ci_s5l_star(core, bufs, pool, Om, li, A_st, P_st, g4law, ka, ns, rfb):
    s = getattr(core, '_c_edge', None)
    k = A_st.shape[0]
    if not (_CI_S5L and s is not None and 6 <= li <= 15 and P_st is not None and bufs is not None and rfb == 0
            and k == s.count):
        return _ci_star5_g4(bufs, pool, Om, li, A_st, P_st, g4law)
    # _c_edge_pre's birth-weight normalisation (idempotent flags), before leg10's first weight use
    for slot in range(k):
        if not s.normalized[slot]:
            u = _cfv(s.birth_weights, (slot, slice(None), 3))
            norm = fnp.sqrt(fnp.sum(fnp.multiply(u, u)))
            fnp.true_divide(u, fnp.maximum(norm, 1e-20), out=u); s.normalized[slot] = True
    weights, reduction, out = _cfv(s.birth_weights, slice(None, k)), s.red, s.leg
    m = int(ns)
    _rc = _CI_S5LC and int(li) == 15 and 0 < m < A_st.shape[1]   # Claude-I S5LC: rows >= ns are +0 after the L15 band transport
    # ---- star5 (verbatim op order) with leg10's reductions interleaved ----
    if _rc:
        _ar = _cfv(A_st, (slice(None), slice(None, m)))
        X = fnp.multiply(_ar, _ar, out=_cfv(bufs["xt"], (slice(None, k), slice(None, m))))
        if _CI_S5L_AP:
            Y, Z = _cfv(bufs["ap"], (slice(None, k), slice(None, m))), _cfv(bufs["pp"], (slice(None, k), slice(None, m)))
        else:
            _pr = _cfv(P_st, (slice(None), slice(None, m)))
            Y = fnp.multiply(_ar, _pr, out=_cfv(bufs["yt"], (slice(None, k), slice(None, m))))
            Z = fnp.multiply(_pr, _pr, out=_cfv(bufs["u"], (slice(None, k), slice(None, m))))
    else:
        X = fnp.multiply(A_st, A_st, out=bufs["xt"][:k])           # A^2
    if _rc:
        pass
    elif _CI_S5L_AP:
        # _dslices already left A (.) P and P (.) P of these legs in the ap / pp slabs (rows :ns when its E3 row trim
        # was on; the legs are +0 below ns, so the products there are +0 too): reuse them, zero the stale tail rows
        Y, Z = bufs["ap"][:k], bufs["pp"][:k]
        if m < A_st.shape[1] and _TB_E3:                        # _dslices' E3 trim (rfb == 0 here): rows >= ns unwritten
            fnp.copyto(Y[:, m:], _CB_F32_ZERO); fnp.copyto(Z[:, m:], _CB_F32_ZERO)
    else:
        Y = fnp.multiply(A_st, P_st, out=bufs["yt"][:k])       # A P
        Z = fnp.multiply(P_st, P_st, out=bufs["u"][:k])        # P^2
    if _rc:
        T = _cfv(bufs["t"], (slice(None, k), slice(None, m)))
        R = _cfv(pool.get("ci_star_red", (Om.shape[2], A_st.shape[1], 1)), (slice(None, k), slice(None, m)))
    else:
        T = bufs["t"][:k]
        R = _cfv(pool.get("ci_star_red", (Om.shape[2], A_st.shape[1], 1)), slice(None, k))

    def _acc(M, mm, F):
        fnp.matmul(M, _cf_view(_cf_view(Om, (li, mm, slice(None, k))), (slice(None), slice(None), None)), out=R)
        f = fnp.sum(R, axis=0)
        return f if F is None else fnp.add(F, f, out=F)
    fnp.copyto(out, 0.0)
    live = bool(k and m)
    if live:
        a = A_st[:, :m]; p = P_st[:, :m]
        Xm, Ym, Zm, Tm = [_cf_view(bufs[name], (slice(None, k), slice(None, m)))
                          for name in (('xt', 'ap', 'pp', 't') if _CI_S5L_AP else ('xt', 'yt', 'u', 't'))]
        red = _cfv(reduction, (slice(None, k), slice(None, m), slice(None, 1)))
        red0 = _cfv(red, (slice(None), slice(None), 0))

        def contract(matrix, column_weights):
            fnp.matmul(matrix, _cfv(column_weights, (slice(None), slice(None), None)), out=red)
            return red
        fnp.sum(Zm, axis=2, out=red0); fnp.sum(red, axis=0, out=_cfv(out, (slice(None, m), slice(4, 5))))
        fnp.sum(Xm, axis=2, out=red0); fnp.sum(red, axis=0, out=_cfv(out, (slice(None, m), slice(5, 6))))
    F = _acc(fnp.multiply(X, Y, out=T), 1, None)               # A^3 P
    if live:                                                   # leg10: the newest source's A^3 P
        fnp.matmul(_cf_view(Tm, k - 1), _cf_view(weights, (k - 1, slice(None), 1)), out=_cf_view(out, (slice(None, m), 3)))
    F = _acc(fnp.multiply(Y, Z, out=T), 3, F)                  # A P^3
    F = _acc(fnp.multiply(X, X, out=X), 0, F)                  # A^4
    if live:                                                   # leg10: A^4 P
        fnp.multiply(Xm, p, out=Tm)
        contract(Tm, _cfv(weights, (slice(None, k), slice(None), 1)))
        if _CF_RPCB_R7: fnp.multiply(fnp.sum(red, axis=0), 5.0, out=_cfv(out, (slice(None, m), slice(2, 3))))
        else: fnp.multiply(fnp.sum(red, axis=0)[:, 0], 5.0, out=_cfv(out, (slice(None, m), 2)))
    F = _acc(fnp.multiply(Y, Y, out=Y), 2, F)                  # A^2 P^2
    if live:                                                   # leg10: A^2 P^2 row sums and weighted contraction
        fnp.sum(Ym, axis=2, out=red0); fnp.sum(red, axis=0, out=_cfv(out, (slice(None, m), slice(9, 10))))
        contract(Ym, _cfv(weights, (slice(None, k), slice(None), 0)))
        if _CF_RPCB_R7:
            fnp.multiply(fnp.sum(_cfv(red, slice(ka, None)), axis=0), 6.0, out=_cfv(out, (slice(None, m), slice(0, 1))))
            if ka: fnp.multiply(fnp.sum(_cfv(red, slice(None, ka)), axis=0), 6.0, out=_cfv(out, (slice(None, m), slice(1, 2))))
        else:
            fnp.multiply(fnp.sum(_cfv(red, slice(ka, None)), axis=0)[:, 0], 6.0, out=_cfv(out, (slice(None, m), 0)))
            if ka: fnp.multiply(fnp.sum(_cfv(red, slice(None, ka)), axis=0)[:, 0], 6.0, out=_cfv(out, (slice(None, m), 1)))
    F = _acc(fnp.multiply(Z, Z, out=Z), 4, F)                  # P^4
    if live:
        contract(a, _cfv(weights, (slice(None, k), slice(None), 3))); fnp.sum(red, axis=0, out=_cfv(out, (slice(None, m), slice(6, 7))))
        contract(p, _cfv(weights, (slice(None, k), slice(None), 3))); fnp.sum(red, axis=0, out=_cfv(out, (slice(None, m), slice(7, 8))))
        contract(Zm, _cfv(weights, (slice(None, k), slice(None), 2))); fnp.sum(red, axis=0, out=_cfv(out, (slice(None, m), slice(8, 9))))
    a_, b_ = _CI_STAR_AB[li]
    _gs = _CI_G['star'][li]
    g = fnp.multiply(g4law, 1.0 + _gs * (a_ - 1.0))
    fnp.add(g, _gs * b_, out=g)
    if _rc:
        _gm = _cfv(g, slice(None, m)); fnp.add(_gm, fnp.multiply(F[:, 0], _gs), out=_gm)
        _gt = _cfv(g, slice(m, None)); fnp.add(_gt, 0.0, out=_gt)
    else:
        fnp.add(g, fnp.multiply(F[:, 0], _gs), out=g)
    s._ci_s5l_done = (li, s.generation)
    return g


_ci_s5l_pre_parent = _c_edge_pre


def _c_edge_pre(core, li, mu, sigma, alpha, phi, Phi, D3, g4, C, D, A, P, ka, ns, bufs, rfb):
    s = getattr(core, '_c_edge', None)
    if s is not None and getattr(s, '_ci_s5l_done', None) == (li, s.generation):
        s._ci_s5l_done = None
        s.packet = (li, s.generation, mu, sigma, alpha, phi, Phi, D3, g4, C, D)
        return
    if s is not None:
        s._ci_s5l_done = None
    return _ci_s5l_pre_parent(core, li, mu, sigma, alpha, phi, Phi, D3, g4, C, D, A, P, ka, ns, bufs, rfb)
# ===================== end Claude-I S5L =====================



# ======================= Claude-I LZR guard (2026-10-15) =======================
_CI_LZR_THR = float(_os.environ.get("CI_LZR_THR", "1e-3"))
_CI_LZR_GUARD_INFO = {"ok": 0, "fallback": 0}


def _ci_lzr_safe(R0):
    """True when the lazy join may use R0^-1: min |r_ii| / max |r_ii| of the QR triangle above the threshold (NaN-safe)."""
    try:
        d = fnp.abs(fnp.diagonal(R0))
        lo = float(fnp.min(d))
        hi = float(fnp.max(d))
        ok = bool(hi > 0.0 and lo / hi > _CI_LZR_THR)
    except Exception:
        ok = False
    _CI_LZR_GUARD_INFO["ok" if ok else "fallback"] += 1
    return ok
# ===================== end Claude-I LZR guard =====================


# ===================== Claude-F RR: r-sized tier products through prepared Strassen roots (2026-10-15) =====================
_CF_RR = _os.environ.get("CF_RR", "1") != "0"
_CF_RR_LEVEL = 3


_CF_RR4 = _os.environ.get("CF_RR4", "1") != "0"   # Claude-F RR4: per-site persistent outputs for consumed-at-once products
_CF_RR4_BUF = {}
_CF_RRPB = _os.environ.get("CF_RRPB", "1") != "0"   # Claude-F RRPB: plain RR into the RR4 site buffers


def _cf_rr(smm, X, Y, key=None):
    if not _CF_RR or _CF_RR_PLAIN[0]:   # Claude-F C2: plain on the light first predict
        if _CF_RRPB and key is not None and _CF_RR4:   # Claude-F RRPB: plain product into the site's persistent output
            k_ = (key, (X.shape[0], Y.shape[1]), str(X.dtype))
            out = _CF_RR4_BUF.get(k_)
            if out is None:
                out = _CF_RR4_BUF[k_] = fnp.empty((X.shape[0], Y.shape[1]), dtype=X.dtype)
            return fnp.matmul(X, Y, out=out)
        return X @ Y
    shape = (X.shape[0], Y.shape[1])
    if key is not None and _CF_RR4:
        k_ = (key, shape, str(X.dtype))
        out = _CF_RR4_BUF.get(k_)
        if out is None:
            out = _CF_RR4_BUF[k_] = fnp.empty(shape, dtype=X.dtype)
    else:
        out = fnp.empty(shape, dtype=X.dtype)
    return _ci_mm(smm, X, Y, out, _CF_RR_LEVEL)
# =================== end Claude-F RR ===================



# ======================= Claude-I VSTAB: stable Strassen-root operand wrappers (2026-10-15) =======================
_CI_VSTAB = _os.environ.get("CI_VSTAB", "1") != "0"


def _ci_nn(a):
    """a[None, None]: one wrapper object per live a (F's weakref view table), so the root's cached quarters stay valid."""
    return _cf_view(a, (None, None)) if _CI_VSTAB else a[None, None]


def _ci_vT(a):
    """a.T: one transpose view per live a."""
    return _cf_T(a) if _CI_VSTAB else a.T


def _ci_vs(a, key):
    """a[key] (basic key): one view per live a and key."""
    return _cf_view(a, key) if _CI_VSTAB else a[key]


def _ci_r48t(A, a, b):
    """(swapaxes(reshape(A[0, 0], (4, a, 4, b)), 1, 2), grid-view dict) of an R48V main-run operand.  Cached per live A
    from its SECOND sighting on, and only when the reshape is a view (one shares_memory round trip then), so operands that
    are fresh on every call never pay a check (F's _cf_nest_view rule); a cached entry keeps its grid views across calls."""
    ent = _cf_vc_entry(A)
    key = ('R48T', a, b)
    e = None if ent is None else ent[2].get(key)
    if e is not None and e is not True and e is not False:
        return e
    At = fnp.swapaxes(fnp.reshape(A[0, 0], (4, a, 4, b)), 1, 2)
    if ent is None or e is False:
        return At, {}
    if e is None:
        ent[2][key] = True                       # first sighting: remember, no round trip
        return At, {}
    if bool(fnp.shares_memory(At, A)):
        e = ent[2][key] = (At, {})
        return e
    ent[2][key] = False
    return At, {}
# ===================== end Claude-I VSTAB =====================

# ===================== Claude-F CWS: slot-slab C_pre fused leaf (2026-10-15) =====================
_CF_CWS = _os.environ.get("CF_CWS", "1") != "0"
_CF_CWS_W = _os.environ.get("CF_CW", "1") != "0"
_CF_CWS_ROWS = tuple(c == "1" for c in _os.environ.get("CF_CWS_ROWS", "1100"))   # Claude-F CWS v2: Winograd rows


class _ChainCpreEncodingV4(_ChainCpreEncodingV3):
    """V3 rows, fused-leaf operands in one slot slab per side, one batched (optionally Winograd) leaf product per row."""
    def __init__(self, owner, output, n=1024):
        self._cf_v4_light = True   # Claude-F SETCUT: V2 builds only what V4 reads (encodings, inputs, fused operands)
        _ChainCpreEncodingV2.__init__(self, owner, output, n)
        h = n // 4; f32 = fnp.float32
        X11, X12, X21, X22, Y11, Y12, Y21, Y22, L3, L2, L5, L4, R3, R2, R6, R4 = self.fused
        lops = (X11, X12, L2, L3, L4, L5, X22)
        rops = (Y11, Y21, R2, R3, R4, Y22, R6)
        if any(a.shape != (4, 343, h // 16, n // 16) for a in lops) or any(b.shape != (4, 343, n // 16, h // 16) for b in rops):
            raise RuntimeError("Cpre v4 requires the v2 four-row 343-leaf geometry")
        q3, q2, q1 = h // 8, h // 4, h // 2
        a_, b_ = h // 16, n // 16
        left, right, _ = owner._root_pack_arenas
        raw = 4 * 343 * (h // 8) * (n // 8)
        S = 4 * 343 * a_ * b_
        offL, offR = left.size - 7 * S, right.size - 7 * S
        Tsz, T3sz = 7 * 4 * 343 * a_ * a_, 4 * 343 * q3 * q3
        T2sz, T1sz = 4 * 49 * q2 * q2, 4 * 7 * q1 * q1
        if (offL < 0 or offR < 0 or Tsz + T3sz > offL or T2sz + T1sz > offR
                or offL + S < raw or offR + S < raw):
            raise RuntimeError("Cpre v4 slabs do not fit the root-pack arenas")
        SL = fnp.reshape(left[offL:offL + 7 * S], (7, 4, 343, a_, b_))
        SR = fnp.reshape(right[offR:offR + 7 * S], (7, 4, 343, b_, a_))
        T = fnp.reshape(left[0:Tsz], (7, 4, 343, a_, a_))
        self._b_T3 = fnp.reshape(left[Tsz:Tsz + T3sz], (4, 343, q3, q3))
        self._b_T2 = fnp.reshape(right[0:T2sz], (4, 49, q2, q2))
        self._b_T1 = fnp.reshape(right[T2sz:T2sz + T1sz], (4, 7, q1, q1))
        self._b_Mb = self._b_Nb = None   # Claude-F SETCUT: V4 run reads Mt / Nt (W), never these
        rows = []
        if _CI_SETUPCUT:
            _c1_cws_prefix = []
        if _CI_REQ_CPRE:
            req_t3 = []
        for i in range(4):
            g = 4 - i
            L = R = None   # Claude-F SETCUT: V4 rows read the SL / SR slot views
            T3, T2, T1 = self._b_T3[:g], self._b_T2[:g], self._b_T1[:g]
            if _CI_SETUPCUT:
                _c1_cws_prefix.append((T3, T2, T1))
            if _CI_REQ_CPRE:
                req_t3.append(T3)
            O = (T3[..., :q3 // 2, :q3 // 2], T3[..., :q3 // 2, q3 // 2:], T3[..., q3 // 2:, :q3 // 2], T3[..., q3 // 2:, q3 // 2:])
            if _CI_CPRE_PAIR:   # Claude-F SETCUT: the Winograd-decode views are read only when the pair decode is off
                c3 = o2 = c2 = o1 = c1 = None
            else:
                c3 = tuple(T3[:, j * 49:(j + 1) * 49] for j in range(7))
                o2 = (T2[..., :q3, :q3], T2[..., :q3, q3:], T2[..., q3:, :q3], T2[..., q3:, q3:])
                c2 = tuple(T2[:, j * 7:(j + 1) * 7] for j in range(7))
                o1 = (T1[..., :q2, :q2], T1[..., :q2, q2:], T1[..., q2:, :q2], T1[..., q2:, q2:])
                c1 = tuple(T1[:, j] for j in range(7))
            band = fnp.reshape(output[i * h:(i + 1) * h, i * h:4 * h], (h, g, h))   # setup-time view of the row band
            o0 = tuple(None if (_CI_CPRE_PAIR and r0 == 0 and c0_ == 0) else   # Claude-F SETCUT: o0[0] only for the Winograd decode
                       fnp.transpose(band[r0:r0 + q1, :, c0_:c0_ + q1], (1, 0, 2))
                       for r0, c0_ in ((0, 0), (0, q1), (q1, 0), (q1, q1)))
            mirror = (output[(i + 1) * h:4 * h, i * h:(i + 1) * h], output[i * h:(i + 1) * h, (i + 1) * h:4 * h].T) if i < 3 else None
            # decode5 plans (pair views; same per-element order as _cb_decode7_root): levels 3 and 2 have the
            # Winograd column axis j split as (j, inner) inside axis 1; level 1 has it as axis 1 itself.
            def plan_inner(A, nin, T, q):          # A (g, 7*nin, q, q) columns; T (g, nin, 2q, 2q) outputs
                c = tuple(A[:, j * nin:(j + 1) * nin] if j in (0, 3, 5, 6) else None for j in range(7))   # Claude-F SETCUT: c1 c2 c4 unread
                c0b = fnp.reshape(c[0], (g, nin, 1, q, q))
                pair12 = fnp.transpose(fnp.reshape(A[:, nin:3 * nin], (g, 2, nin, q, q)), (0, 2, 1, 3, 4))
                pair34 = fnp.transpose(fnp.reshape(A[:, 3 * nin:5 * nin], (g, 2, nin, q, q)), (0, 2, 1, 3, 4))
                left = fnp.transpose(fnp.reshape(T[..., :q, :], (g, nin, q, 2, q)), (0, 1, 3, 2, 4))
                right = fnp.reshape(T[..., :, q:], (g, nin, 2, q, q))
                C12, C21, C22 = T[..., :q, q:], T[..., q:, :q], T[..., q:, q:]
                return (c0b, c[3], c[5], c[6], pair12, pair34, C12, C21, C22, left, right, left[:, :, 1:2])
            p3 = plan_inner(T3, 49, T2, q3)
            p2 = plan_inner(T2, 7, T1, q2)
            c0b = T1[:, 0:1]; pair12 = T1[:, 1:3]; pair34 = T1[:, 3:5]
            top = band[0:q1]                                                    # (q1, g, h)
            left1v = fnp.transpose(fnp.reshape(top, (q1, g, 2, q1)), (1, 2, 0, 3))      # (g, 2, q1, q1) = [C11, C12]
            rightv = fnp.transpose(fnp.reshape(band[:, :, q1:], (2, q1, g, q1)), (2, 0, 1, 3))  # (g, 2, q1, q1) = [C12, C22]
            p1 = (c0b, T1[:, 3], T1[:, 5], T1[:, 6], pair12, pair34, o0[1], o0[2], o0[3], left1v, rightv, left1v[:, 1:2])
            rows.append((L, R, O, None, None, c3, o2, c2, o1, c1, o0, mirror, (p3, p2, p1)))   # Claude-F SETCUT: Mb / Nb unread
        self.rows = tuple(rows)

        # slab rows: fused encodes write the slab; X22/X12 (Y22/Y21) copied first, X11/Y11 last (slot 0 overlaps x/ylast)
        if _CI_SETUPCUT:
            _c1_sl, _c1_sr = _cp_rows(SL), _cp_rows(SR)
            self.fused = (X11, X12, X21, X22, Y11, Y12, Y21, Y22, _c1_sl[3], _c1_sl[2], _c1_sl[5], _c1_sl[4], _c1_sr[3], _c1_sr[2], _c1_sr[6], _c1_sr[4])
            self._cws_copies = ((_c1_sl[6], X22), (_c1_sl[1], X12), (_c1_sr[5], Y22), (_c1_sr[1], Y21), (_c1_sl[0], X11), (_c1_sr[0], Y11))
        else:
            self.fused = (X11, X12, X21, X22, Y11, Y12, Y21, Y22, SL[3], SL[2], SL[5], SL[4], SR[3], SR[2], SR[6], SR[4])
            self._cws_copies = ((SL[6], X22), (SL[1], X12), (SR[5], Y22), (SR[1], Y21), (SL[0], X11), (SR[0], Y11))
        bl = self.executor.pool[("L", 7)][0]
        br = self.executor.pool[("R", 7)][0]
        ah, bh = a_ // 2, b_ // 2
        nL, nM = 7 * 343 * ah * bh, 7 * 4 * 343 * ah * ah
        nR = 7 * 4 * 343 * bh * ah
        if nL + 2 * nM > bl.size or nR > br.size:
            raise RuntimeError("Cpre v4 Winograd temporaries exceed the (L,7)/(R,7) encode arenas")
        Lt = fnp.reshape(bl[0:nL], (7, 1, 343, ah, bh))
        Mt = fnp.reshape(bl[nL:nL + nM], (7, 4, 343, ah, ah))
        Nt = fnp.reshape(bl[nL + nM:nL + 2 * nM], (7, 4, 343, ah, ah))
        Rt = fnp.reshape(br[0:nR], (7, 4, 343, bh, ah))
        cws = []
        if _CI_REQ_CPRE:
            self._c2_req_decode, self._c2_req_decode_keep = [], []
        for i, row in enumerate(self.rows):
            g = 4 - i
            Lv, Rv, Tg = SL[:, i:i + 1], SR[:, i:4], T[:, :g]
            if _CI_REQ_CPRE:
                req_plan, req_keep = _c2_req_cpre_decode_views(Tg, req_t3[i])
                self._c2_req_decode.append(req_plan)
                self._c2_req_decode_keep.append(req_keep)
            W = ((Lv[..., :ah, :bh], Lv[..., :ah, bh:], Lv[..., ah:, :bh], Lv[..., ah:, bh:],
                  Rv[..., :bh, :ah], Rv[..., :bh, ah:], Rv[..., bh:, :ah], Rv[..., bh:, ah:],
                  Tg[..., :ah, :ah], Tg[..., :ah, ah:], Tg[..., ah:, :ah], Tg[..., ah:, ah:],
                  Lt, Rt[:, :g], Mt[:, :g], Nt[:, :g]) if (_CF_CWS_W and _CF_CWS_ROWS[i]) else None)   # Claude-F SETCUT: plain rows
            cws.append((Lv, Rv, Tg, W, row[2]) + tuple(row[5:]))
        self._cws_rows = tuple(cws)
        self._cws_tk = (tuple(_cp_rows(r[2]) for r in self._cws_rows) if _CI_SETUPCUT else
                        tuple(tuple(r[2][k] for k in range(7)) for r in self._cws_rows))   # setup-time views
        # Claude-F CWS v2: FD5 for the V4 decode plans ([c5, c3] views made here, at setup)
        if _CI_FD5:
            for i, row in enumerate(self.rows):
                g = 4 - i
                p3, p2, p1 = row[12]
                T3, T2, T1 = (_c1_cws_prefix[i] if _CI_SETUPCUT else
                              (self._b_T3[:g], self._b_T2[:g], self._b_T1[:g]))
                for plan, A, nin in ((p3, T3, 49), (p2, T2, 7)):
                    f7 = fnp.reshape(A, (g, 7, nin) + tuple(A.shape[2:]))
                    _CI_FD5_PLAN_TAB[id(plan)] = (plan, fnp.swapaxes(f7[:, 5:2:-2], 1, 2))
                _CI_FD5_PLAN_TAB[id(p1)] = (p1, T1[:, 5:2:-2])

    def run(self, X, Y, out):
        self.require_current(self.owner, out)
        for sl, xp, yp in self.inputs:
            fnp.copyto(xp, X[sl, :])
            fnp.copyto(yp, Y[:, sl])
        if _CI_REQ_CPRE:
            for (lc, rc, xq, yq), (ld, ls, rd, rs) in zip(self.encodings, self._c2_req_enc_copy):
                _c2_req_cpre_encode_left(lc, xq, ld, ls)
                _c2_req_cpre_encode_right(rc, yq, rd, rs)
        else:
            for lc, rc, xq, yq in self.encodings:
                _chain_v2_encode_left(lc, xq)
                _chain_v2_encode_right(rc, yq)
        X11, X12, X21, X22, Y11, Y12, Y21, Y22, L3, L2, L5, L4, R3, R2, R6, R4 = self.fused
        fnp.add(X21, X22, out=L3)
        fnp.subtract(L3, X11, out=L2)
        fnp.subtract(X12, L2, out=L5)
        fnp.subtract(X11, X21, out=L4)
        fnp.subtract(Y12, Y11, out=R3)
        fnp.subtract(Y22, R3, out=R2)
        fnp.subtract(R2, Y21, out=R6)
        fnp.subtract(Y22, Y12, out=R4)
        for d_, s_ in self._cws_copies:
            fnp.copyto(d_, s_)
        for i_, (Lv, Rv, Tg, W, O, c3, o2, c2, o1, c1, o0, mirror, plans) in enumerate(self._cws_rows):
            Tk = self._cws_tk[i_]
            if _CF_CWS_W and _CF_CWS_ROWS[i_] and _CI_FBW2_ACTIVE[0]:   # Claude-F: guard level 1 (FBW2 off) also turns CWS off
                _ci_fbw2_inner(*W)
            else:
                fnp.matmul(Lv, Rv, out=Tg)
            if _CI_REQ_CPRE:
                _c2_req_cpre_decode5(Tk, O, self._c2_req_decode[i_])
            else:
                C11, C12, C21, C22 = O
                fnp.add(Tk[2], Tk[0], out=C12)
                fnp.add(Tk[4], C12, out=Tk[4])
                fnp.add(C12, Tk[3], out=C12)
                fnp.add(C12, Tk[5], out=C12)
                fnp.subtract(Tk[4], Tk[6], out=C21)
                fnp.add(Tk[4], Tk[3], out=C22)
                fnp.add(Tk[1], Tk[0], out=C11)
            if _CI_CPRE_PAIR:
                _cb_decode5_cached(plans[0])
                _cb_decode5_cached(plans[1])
                _cb_decode5_cached(plans[2])
            else:
                _ci_wino_decode(c3, *o2)
                _ci_wino_decode(c2, *o1)
                _ci_wino_decode(c1, *o0)
            if mirror is not None:
                fnp.copyto(mirror[0], mirror[1])
        return out
_CF_CWS_INFO = {}


def _cf_cws_make(owner, output, n=1024):
    try:
        enc = _ChainCpreEncodingV4(owner, output, n)
        _CF_CWS_INFO["mode"] = "v4"
        return enc
    except RuntimeError as exc:
        _CF_CWS_INFO["mode"] = "v3 fallback: " + str(exc)[:80]
        return _ChainCpreEncodingV3(owner, output, n)
# =================== end Claude-F CWS ===================



# ======================= Claude-I SDUP: one view object per (live backing, key) in the preparers (2026-10-15) =======================
_CI_SDUP = _os.environ.get("CI_SDUP", "1") != "0"
_CI_SD_CFC_TAB = {}     # cf binder chain / decode cache shared by every executor (live-object keys, `is`-checked)


def _ci_sd_v(base, key):
    """base[key] (basic key), one object per live base and key (Claude-F's view table); plain getitem when off."""
    return _cf_view(base, key) if _CI_SDUP else base[key]


def _ci_sd_rows(slab):
    """_cp_rows(slab), one tuple per live slab."""
    if not _CI_SDUP:
        return _cp_rows(slab)
    ent = _cf_vc_entry(slab)
    if ent is None:
        return _cp_rows(slab)
    v = ent[2].get('SDR')
    if v is None:
        v = ent[2]['SDR'] = _cp_rows(slab)
    return v


def _ci_sd_memo(base, key, make):
    ent = _cf_vc_entry(base) if _CI_SDUP else None
    if ent is None:
        return make()
    v = ent[2].get(key)
    if v is None:
        v = ent[2][key] = make()
    return v


def _ci_sd_rs(a, shape):
    """fnp.reshape(a, shape) where it is a view (prefix / axis split), one object per live a and shape."""
    return _ci_sd_memo(a, ('SDRS', tuple(int(x) for x in shape)), lambda: fnp.reshape(a, shape))


def _ci_sd_tp(a, axes=None):
    return _ci_sd_memo(a, ('SDTP', None if axes is None else tuple(axes)), lambda: fnp.transpose(a, axes))


def _ci_sd_sw(a, i, j):
    return _ci_sd_memo(a, ('SDSW', int(i), int(j)), lambda: fnp.swapaxes(a, i, j))


def _ci_sd_blocks(A):
    """_cb_r48_blocks4(A[0, 0]), one grid per live operand (Claude-F's _cf_r48_blocks)."""
    return _cf_r48_blocks(A) if _CI_SDUP else _cb_r48_blocks4(A[0, 0])
if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):
    _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | {"_CI_SD_CFC_TAB"}))
# ===================== end Claude-I SDUP =====================



# ======================= Claude-I FP1: fewer first-predict remote calls, byte-identical (2026-10-15) =======================
_CI_FP1_PRE = _os.environ.get("CI_FP1_PRE", "1") != "0"
_CI_FP1_PRE_MAX = int(_os.environ.get("CI_FP1_PRE_MAX", "-1"))   # at most this many setup lazies made early (-1: all)
_CI_FP1_GRID = _os.environ.get("CI_FP1_GRID", "1") != "0"
_CI_FP1_YW = _os.environ.get("CI_FP1_YW", "1") != "0"
_CI_FP1_LAZY_TAB = {}            # id -> _CiFbw2Lazy made during the running setup
_CI_FP1_SETUP = [False]
_CI_FP1_INFO = {"pre": 0, "pre_fail": 0, "yw_free": 0, "yw_busy": 0}

_ci_fp1_lazy_init_parent = _CiFbw2Lazy.__init__


def _ci_fp1_lazy_init(self, make):
    _ci_fp1_lazy_init_parent(self, make)
    if _CI_FP1_SETUP[0]:
        _CI_FP1_LAZY_TAB[id(self)] = self


_CiFbw2Lazy.__init__ = _ci_fp1_lazy_init
_ci_fp1_setup_parent = Estimator.setup


def _ci_fp1_setup(self, ctx):
    _CI_FP1_LAZY_TAB.clear()
    _CI_FP1_SETUP[0] = True
    try:
        res = _ci_fp1_setup_parent(self, ctx)
    finally:
        _CI_FP1_SETUP[0] = False
    try:
        if _CI_FP1_PRE:
            for i_, lz in enumerate(list(_CI_FP1_LAZY_TAB.values())):
                if 0 <= _CI_FP1_PRE_MAX <= i_:
                    break
                if lz.val is None and lz.make is not None:
                    try:
                        lz.get()
                        _CI_FP1_INFO["pre"] += 1
                    except Exception:
                        _CI_FP1_INFO["pre_fail"] += 1
    finally:
        _CI_FP1_LAZY_TAB.clear()
    return res


Estimator.setup = _ci_fp1_setup


def _ci_fp1_yw_free(owner, used, where, probes):
    """True when no probe shares memory with any free arena holding this conversion's temporaries (then no temporary
    can overlap a probe either); False -> the caller runs the original per-temporary check."""
    if not _CI_FP1_YW:
        return False
    names = set(str(where).split("+"))
    arenas = [a for size, nm, a in _ci_fbw2_free_arenas(owner, used) if nm in names]
    if not arenas:
        return False
    for a in arenas:
        for p in probes:
            if bool(fnp.shares_memory(a, p)):
                _CI_FP1_INFO["yw_busy"] += 1
                return False
    _CI_FP1_INFO["yw_free"] += 1
    return True


