# ======================= Claude-I TRACE: compression trace loss carried as one vector (2026-10-15) =======================
def _ci_tr_layers(txt):
    out_ = set()
    for part in str(txt).replace(" ", "").split(","):
        if not part:
            continue
        if "-" in part:
            a_, b_ = part.split("-")
            out_ |= set(range(int(a_), int(b_) + 1))
        else:
            out_.add(int(part))
    return frozenset(out_)


_CI_TR_ON = _os.environ.get("CI_TR", "1") != "0"
_CI_TR_L = _ci_tr_layers(_os.environ.get("CI_TR_LAYERS", "10-14"))
_CI_TR_GAIN = float(_os.environ.get("CI_TR_GAIN", "0.4"))   # B05n: N2 eta* (0.47 fitted / 0.54 holdout)
_CI_TR_REC = ""                                    # production build: recording compiled out
_CI_TR_LZRF = _os.environ.get("CI_TR_LZRF", "0") != "0"   # 0: no fresh loss on LZR layers (skips R0 FAj; tau still carried)
_CI_TR_INJ = _os.environ.get("CI_TR_INJ", "1") != "0"     # 0: carry tau / expose features only, no K21 injection
_CI_TR_LAST = (max(_CI_TR_L) if (_CI_TR_L and not _CI_TR_REC) else 99)   # nothing to carry past the last injected layer
_CI_TR_TAB = {}           # id(core) -> state dict: tau, g, delta (this layer's join), li
_CI_TR_REC_TAB = {}


def _ci_tr_state(core):
    e = _CI_TR_TAB.get(id(core))
    if e is None or e[0] is not core:
        e = _CI_TR_TAB[id(core)] = (core, {})
    return e[1]


def _ci_tr_v(mAP, mPP, mAA, mZLP, myA, myP, w2, s_, e_, c1, c2):
    """LA^T 1, LP^T 1 and 1^T R of the _dslices formulas from unit-weight column moments."""
    vA = fnp.add(fnp.multiply(fnp.multiply(mAP, w2), 2.0), fnp.multiply(mPP, e_))
    vP = fnp.multiply(mAA, w2)
    fnp.add(vP, fnp.multiply(mPP, fnp.multiply(s_, 1.0 / 3.0)), out=vP)
    mp = fnp.add(mZLP, fnp.multiply(mPP, s_))
    fnp.add(mp, fnp.multiply(fnp.multiply(mAP, e_), 3.0), out=mp)
    fnp.add(mp, fnp.add(fnp.multiply(myA, c1), fnp.multiply(myP, c2)), out=mp)
    fnp.add(vP, fnp.multiply(mp, 2.0 / 3.0), out=vP)
    rho = fnp.add(fnp.sum(fnp.multiply(mAP, c1)), fnp.sum(fnp.multiply(mPP, c2)))
    return vA, vP, rho


def _ci_tr_join(core, li, j, Aj, Pj, FAj, FPj, Qn, R0, Z_st, L_st, w2b_list, s_list, e_list, c1_list, c2_list, rres,
                w1_prev, nj, bufs):
    nj = int(nj)
    if int(li) > _CI_TR_LAST or bufs is None or int(Aj.shape[0]) != nj or int(Qn.shape[0]) != nj or (
            R0 is not None and not _CI_TR_LZRF):
        return
    st = _ci_tr_state(core)
    w2, s_, e_, c1, c2 = w2b_list[j], s_list[j], e_list[j], c1_list[j], c2_list[j]
    L = L_st[j]                                                  # (n_a, q)
    Zp = fnp.multiply(Z_st[j][:nj], w1_prev[:nj, None])          # post-wick join-frame thin leg (nj, q)
    y = Zp[:, int(rres) + 1]
    Tm = bufs["t"][0][:nj]                                        # dead work plane (the layer's _dslices writes it later)
    # dense (pre-compression) moments
    fnp.multiply(Aj, Pj, out=Tm); mAP = fnp.sum(Tm, axis=0)
    fnp.multiply(Pj, Pj, out=Tm); mPP = fnp.sum(Tm, axis=0)
    fnp.multiply(Aj, Aj, out=Tm); mAA = fnp.sum(Tm, axis=0)
    mZLP = fnp.sum(fnp.multiply(L.T, fnp.matmul(Zp.T, Pj)), axis=0)
    myA = fnp.matmul(y, Aj); myP = fnp.matmul(y, Pj)
    vA, vP, rho = _ci_tr_v(mAP, mPP, mAA, mZLP, myA, myP, w2, s_, e_, c1, c2)
    tz = fnp.matmul(Zp, fnp.matmul(L.T, mPP))
    t_pre = fnp.add(fnp.matmul(Aj, vA), fnp.matmul(Pj, vP))
    fnp.add(t_pre, fnp.multiply(fnp.add(fnp.multiply(y, rho), tz), 1.0 / 3.0), out=t_pre)
    # projected (formed) moments from the factors: F = Qn^T A_j
    r_ = int(FAj.shape[0])
    if R0 is not None:                                            # LZR: FAj = R0^-1 Qn^T A_j
        FA = fnp.matmul(R0, FAj, out=bufs["t"][1][:r_])
        FP = fnp.matmul(R0, FPj, out=bufs["t"][2][:r_])
    else:
        FA, FP = FAj, FPj
    Tr = bufs["t"][3][:r_]
    fnp.multiply(FA, FP, out=Tr); fAP = fnp.sum(Tr, axis=0)
    fnp.multiply(FP, FP, out=Tr); fPP = fnp.sum(Tr, axis=0)
    fnp.multiply(FA, FA, out=Tr); fAA = fnp.sum(Tr, axis=0)
    QZ = fnp.matmul(Qn.T, Zp)                                     # (r, q)
    fZLP = fnp.sum(fnp.multiply(L.T, fnp.matmul(QZ.T, FP)), axis=0)
    Qy = fnp.matmul(y, Qn)                                        # (r,)
    fyA = fnp.matmul(Qy, FA); fyP = fnp.matmul(Qy, FP)
    uA, uP, rf = _ci_tr_v(fAP, fPP, fAA, fZLP, fyA, fyP, w2, s_, e_, c1, c2)
    t_fm = fnp.matmul(Qn, fnp.add(fnp.matmul(FA, uA), fnp.matmul(FP, uP)))
    tzf = fnp.matmul(Zp, fnp.matmul(L.T, fPP))
    fnp.add(t_fm, fnp.multiply(fnp.add(fnp.multiply(y, rf), tzf), 1.0 / 3.0), out=t_fm)
    st["delta"] = (int(li), fnp.subtract(t_pre, t_fm))


def _ci_tr_apply(core, li, b2, D21, alpha, W, W_all, n, ns, bufs):
    if int(li) > _CI_TR_LAST:
        return
    st = _ci_tr_state(core)
    n = int(n); ns = int(ns)
    ncol = int(W.shape[1])
    tau, gp = st.get("tau"), st.get("g")
    d = st.pop("delta", None)
    if d is not None and d[0] != int(li):
        d = None
    if tau is None and d is None:
        st["g"] = W_all[:, core._i11]
        return
    x = fnp.zeros(ncol, dtype=fnp.float32)
    if tau is not None:
        m = min(ncol, int(tau.shape[0]))
        fnp.add(x[:m], fnp.multiply(gp[:m], tau[:m]), out=x[:m])
    if d is not None:
        m = min(ncol, int(d[1].shape[0]))
        fnp.add(x[:m], d[1][:m], out=x[:m])
    g = W_all[:, core._i11]
    u = fnp.greater(alpha, -2.5).astype(fnp.float32)
    if ns < n:
        fnp.copyto(u[ns:], 0.0)
    _rw = _cf_trww_take(li, W, ncol)   # Claude-F TRWW: the loop's W * W row sum (same op, same bits)
    if _rw is not None:
        rn = _rw
    else:
        Wsq = bufs["mp"][0][:, :ncol]                                 # dead n x n plane at this anchor
        fnp.multiply(W, W, out=Wsq)
        rn = fnp.sum(Wsq, axis=1)
    ur = fnp.multiply(u, rn)
    kap = fnp.sum(ur) / float(ncol)
    kap2 = fnp.sum(fnp.multiply(ur, fnp.multiply(g, g))) / float(ncol)
    v = fnp.matmul(W, x)
    t = fnp.multiply(v, kap)
    st["tau"] = fnp.multiply(v, kap2)
    st["g"] = g
    st["feat"] = (int(li), t, u)                                  # for _ci_tr_feat (corrector inputs), no extra op
    if int(li) in _CI_TR_L and n == 1024 and _CI_TR_INJ:
        N = float(fnp.sum(u))
        if N < 2:
            return
        dv = fnp.multiply(fnp.multiply(t, u), _CI_TR_GAIN / (N - 1.0))
        Dc = bufs["t1"]                                             # dead (n, n) slab here (pair-head skeleton's choice)
        fnp.multiply(u[:, None], dv[None, :], out=Dc)
        fnp.fill_diagonal(Dc, 0.0)
        fnp.add(Dc, D21, out=Dc)
        b2["d21"] = Dc
        b2["d21T"] = fnp.transpose(Dc)


def _ci_tr_feat(core, li, out=None, uout=None):
    """TRACE feature hook for the corrector heads: t_li (.) u of this predict's layer li (the K21 column-trace vector TRACE
    carries, made at the layer's pair anchor, i.e. before _cb_head_alive / _c_edge_apply of the same layer), written into
    `out` when given (one op); `uout` also receives the alive-row mask u (one copy).  None when TRACE did not run at li
    (off, before the first join, past the last layer).  _ci_tr_u(core, li) returns u itself (no op)."""
    if not _CI_TR_ON:
        return None
    e = _CI_TR_TAB.get(id(core))
    if e is None or e[0] is not core:
        return None
    f = e[1].get("feat")
    if f is None or f[0] != int(li):
        return None
    if uout is not None:
        fnp.copyto(uout, f[2])
    return fnp.multiply(f[1], f[2], out=out) if out is not None else fnp.multiply(f[1], f[2])


def _ci_tr_u(core, li):
    """The alive-row mask u (float32 0/1) TRACE used at layer li of this predict, or None."""
    e = _CI_TR_TAB.get(id(core))
    if not _CI_TR_ON or e is None or e[0] is not core:
        return None
    f = e[1].get("feat")
    return f[2] if (f is not None and f[0] == int(li)) else None


_ci_tr_begin_parent = _cc_d21_c_begin


def _cc_d21_c_begin(core, n, L, r, rfb, prune, owner, ta_active, pool):
    if _CI_TR_ON:
        _CI_TR_TAB.pop(id(core), None)                           # once per predict: no state across nets
        _CI_TR_REC_TAB.clear()
    return _ci_tr_begin_parent(core, n, L, r, rfb, prune, owner, ta_active, pool)


if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):
    _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | {"_CI_TR_TAB", "_CI_TR_REC_TAB"}))
# ===================== end Claude-I TRACE =====================



