_ci_r48vp_setup_parent = Estimator.setup


def _ci_r48vp_direct(gen, site, build):
    """_ci_r48v_try without the dry pre-count: at setup the budget is unbounded, so every site is simply built (same
    views, same programs, half the Python work)."""
    st = _CI_R48V_STATE_TAB
    if st.get("gen") != gen:
        _CI_R48V_VC_TAB.clear()
        _CI_R48V_NEED_TAB.clear()
        st["gen"] = gen
    vw = _CiR48vViews(gen, False)
    progs = build(vw)
    _CI_R48V_INFO["views"] += vw.new
    return progs


def _ci_r48vp_prebuild(est):
    global _ci_r48v_try
    smm = getattr(getattr(est, "core", None), "_smm", None)          # the setup-prepared executor (Estimator.core._smm)
    plans = getattr(smm, "_r48_views", None) if smm is not None else None
    if not plans or not _CI_R48V:
        return
    gen = smm._scratch_generation
    st = _CI_R48V_STATE_TAB
    left0 = st.get("left")
    v0 = _CI_R48V_INFO["views"]
    st["left"] = (1 << 30) if _CI_R48VP_MAX < 0 else _CI_R48VP_MAX
    try_parent = _ci_r48v_try
    if _CI_R48VP_MAX < 0:
        _ci_r48v_try = _ci_r48vp_direct                 # also used by _ci_k363v_get below
    try:
        for key, plan in list(plans.items()):
            if key in _CI_R48VP_NEVER or (_CI_R48VP_LEVEL <= 2 and key in _CI_R48VP_HEAVY) or (
                    _CI_R48VP_LEVEL <= 1 and key in _CI_R48VP_MID) or key in _CF_R48VPSET2_SKIP:   # Claude-F R48VPSET2
                _CI_R48VP_INFO["skipped"] += 1
                continue
            e = _CI_R48V_MAIN_TAB.get(id(plan))
            if e is not None and e[0] is plan and e[1] == gen:
                continue
            L4, R4, P4, LW, RW, PW, rows = plan
            h, q, v = L4.shape[2], L4.shape[3], R4.shape[3]
            xs, ys = key[1], key[2]
            if not (_ci_r48v_fits(L4, LW, RW, PW) and xs[2] == 4 * h and xs[3] == 4 * q and ys[3] == 4 * v):
                continue
            progs = _ci_r48v_try(gen, id(plan), lambda vw, sl=(L4, R4, P4, LW, RW, PW), rows=rows, h=h, q=q, v=v:
                                 _ci_r48v_build(vw, sl, rows, h, q, v, None))
            if progs is None:
                _CI_R48VP_INFO["deferred"] += 1
                continue
            _CI_R48V_MAIN_TAB[id(plan)] = (plan, gen) + progs + (h, q, v)
            _CI_R48V_INFO["main"] += 1
            _CI_R48VP_INFO["main"] += 1
        fp = getattr(smm, "_cc_full1024_plan", None)
        if fp is not None and _CI_R48VP_LEVEL >= 1 and _ci_k363v_get(smm, fp) is not None:
            _CI_R48VP_INFO["k363"] += 1
    finally:
        _ci_r48v_try = try_parent
        _CI_R48VP_INFO["views"] += _CI_R48V_INFO["views"] - v0
        if left0 is None:
            st.pop("left", None)
        else:
            st["left"] = left0


def _ci_r48vp_setup(self, ctx):
    res = _ci_r48vp_setup_parent(self, ctx)
    if _CI_R48VP:
        try:
            _ci_r48vp_prebuild(self)
            _CI_R48VP_FIRST[0] = True
        except Exception as ex:                         # leave R48V lazy, exactly as without R48VP
            _CI_R48VP_INFO["error"] = repr(ex)[:200]
            _ci_r48v_release()
    return res


Estimator.setup = _ci_r48vp_setup
_ci_r48vp_begin_parent = _cc_d21_c_begin


def _cc_d21_c_begin(core, n, L, r, rfb, prune, owner, ta_active, pool):
    res = _ci_r48vp_begin_parent(core, n, L, r, rfb, prune, owner, ta_active, pool)   # R48V sets this predict's budget
    if _CI_R48VP_FIRST[0]:
        _CI_R48VP_FIRST[0] = False
        if _CI_R48VP_FIRST_BUDGET >= 0:
            _CI_R48V_STATE_TAB["left"] = _CI_R48VP_FIRST_BUDGET
    return res
