# ======================= Claude-I K4CP: kappa4-diagonal corrector k4c, production form (2026-10-18) =======================
def _ci_k4p_layers(txt):
    out_ = set()
    for part in str(txt).replace(" ", "").split(","):
        if "-" in part:
            a_, b_ = part.split("-"); out_ |= set(range(int(a_), int(b_) + 1))
        elif part:
            out_.add(int(part))
    return frozenset(out_)


_CI_K4P_LAY = [6, 7, 8, 9, 10, 11, 12, 13, 14]
_CI_K4P_W1T = _hxl_n('', 'f', [66, 64])   # (66, 64)
_CI_K4P_B1L = _hxl_n('', 'f', [9, 64])   # (L, 64) = b1 + layer one-hot column
_CI_K4P_W2T = _hxl_n('', 'f', [64, 64])
_CI_K4P_B2 = _hxl_n('', 'f', [64])
_CI_K4P_W3T = _hxl_n('', 'f', [64, 1])   # (64, 1)
_CI_K4P_B3 = -0.04614812508225441
_CI_K4P_MEAN = _hxl_n('', 'f', [9, 66])
_CI_K4P_ISTD = _hxl_n('', 'f', [9, 66])
_CI_K4P_SCALE = [0.004498733207583427, 0.005917046684771776, 0.006807076744735241, 0.007800186052918434, 0.008427676744759083, 0.009894747287034988, 0.010972175747156143, 0.011799574829638004, 0.01287029217928648]
_CI_K4P_TAU = float(_os.environ.get("CI_K4C_TAU", "0.5"))
_CI_K4P_LI = _ci_k4p_layers(_os.environ.get("CI_K4C_LI", "6-14")) & frozenset(_CI_K4P_LAY)
_CI_K4P_X3IN_PRE = _os.environ.get("CI_K4C_X3IN", "post") == "pre"
_CI_K4P_ON = _CI_K4P_TAU != 0.0 and bool(_CI_K4P_LI)
_CI_K4P_FIRST_SKIP = _os.environ.get("CI_K4C_FIRST", "on") == "skip"
_CI_K4P_DLSKIP = _os.environ.get("CI_K4C_DL", "0") != "0"
_CI_K4P_IDX66 = [0, 1, 2, 3, 4, 5, 6, 7] + list(range(11, 21)) + [21 + 10 * q + j for q in range(6) for j in range(8)]
_CI_K4P_INFO = {"applied": {}, "skip": {}}


def _ci_k4p_skip(why):
    _CI_K4P_INFO["skip"][why] = _CI_K4P_INFO["skip"].get(why, 0) + 1


def _ci_k4p_state(s):
    """Per-(3)-state constants, buffers and views, made on first use in predict (no setup RPC)."""
    K = getattr(s, 'k4p', None)
    if K is not None:
        return K
    n = s.n; f32 = fnp.float32
    K = {'W1T': fnp.asarray(_CI_K4P_W1T, dtype=f32), 'B1L': fnp.asarray(_CI_K4P_B1L, dtype=f32), 'W2T': fnp.asarray(_CI_K4P_W2T, dtype=f32),
         'b2': fnp.asarray(_CI_K4P_B2, dtype=f32), 'W3T': fnp.asarray(_CI_K4P_W3T, dtype=f32), 'mean': fnp.asarray(_CI_K4P_MEAN, dtype=f32),
         'istd': fnp.asarray(_CI_K4P_ISTD, dtype=f32), 'idx': fnp.asarray(_CI_K4P_IDX66, dtype=fnp.int64)}
    K['h1'] = fnp.zeros((n, 64), dtype=f32); K['h2'] = fnp.zeros((n, 64), dtype=f32)
    K['o'] = fnp.zeros((n, 1), dtype=f32); K['d'] = fnp.zeros((n,), dtype=f32)
    K['o0'] = _cfv(K['o'], (slice(None), 0))
    # (3) buffers: basis columns 0-7, queries and outputs for 8 basis columns, and the post-call column windows
    K['b8'] = _cfv(s.basis, (slice(None), slice(0, 8)))
    K['bN8'] = _cfv(s.ce_basisN, (slice(None), slice(None), slice(0, 8)))
    K['Q28'] = _cfv(s.ce_Q2, (slice(None), slice(None), slice(0, 8)))
    K['Q08'], K['Q18'] = _cfv(K['Q28'], 0), _cfv(K['Q28'], 1)
    K['T8'] = tuple(_cfv(T, (slice(None), slice(0, 8))) for T in s.ce_T)
    K['o38'] = _cfv(s.ce_out3, (slice(None), slice(None), slice(0, 8)))
    c0 = 8 if _CI_K4P_X3IN_PRE else 7
    K['c0'] = c0
    K['bNc'] = _cfv(s.ce_basisN, (slice(None), slice(None), slice(c0, 10)))
    K['Q2c'] = _cfv(s.ce_Q2, (slice(None), slice(None), slice(c0, 10)))
    K['Q0c'], K['Q1c'] = _cfv(K['Q2c'], 0), _cfv(K['Q2c'], 1)
    K['Tc'] = tuple(_cfv(T, (slice(None), slice(c0, 10))) for T in s.ce_T)
    K['o3c'] = _cfv(s.ce_out3, (slice(None), slice(None), slice(c0, 10)))
    K['s4'] = _cfv(s.ce_S23, 1)
    K['rows'] = {}
    s.k4p = K
    return K


def _ci_k4p_pre(core, bufs, li, mu, sigma, alpha, phi, Phi, D3, g, C, D):
    li = int(li)
    s = getattr(core, '_c_edge', None)
    if s is not None:
        s.k4p_tok = None                  # v3 (R K1): no token survives a layer whose (3) call did not run
    if s is None or not getattr(s, 'ce_ok', False):
        _ci_k4p_skip("no-ce-edge"); return g
    if C is None or D is None or bufs is None:
        _ci_k4p_skip("no-C-D"); return g
    if getattr(s, '_ci_s5l_done', None) != (li, s.generation):
        _ci_k4p_skip("no-s5l-leg10"); return g
    if ((str(D3.dtype) != 'float32' or str(g.dtype) != 'float32') if _CF_RPCB_R6 else (D3.dtype != fnp.float32 or g.dtype != fnp.float32)):
        _ci_k4p_skip("dtype"); return g
    _gl = globals()
    _dls = _gl.get('_CF_DL_STATE')
    if _CI_K4P_DLSKIP and _dls is not None and _dls.get('level', 0) >= 1:
        _ci_k4p_skip("dl-light"); return g
    _f1, _fl, _fn = _gl.get('_CF_DL_FIRST'), _gl.get('_CF_DL_FIRST_LEFT'), _gl.get('_CF_DL_FIRST_N')
    if _CI_K4P_FIRST_SKIP and _f1 is not None and _f1[0] and _fl is not None and _fl[0] == _fn:
        _ci_k4p_skip("first-predict"); return g
    _ce_v(s)
    K = _ci_k4p_state(s)
    t = _CI_K4P_LAY.index(li)
    rw = K['rows'].get(t)
    if rw is None:
        rw = K['rows'][t] = (_cfv(K['mean'], t), _cfv(K['istd'], t), _cfv(K['B1L'], t))
    # basis columns 0-7 (= _ce_basis10, same ops and buffers)
    ss, s2 = s.ce_s, s.ce_s2
    fnp.maximum(sigma, 1e-6, out=ss)
    fnp.multiply(ss, ss, out=s2)
    fnp.multiply(s.ce_s2N, s.ce_S01, out=s.ce_S23)
    fnp.stack((s.ce_ones, mu, ss, alpha, phi, Phi, D3, g), axis=1, out=K['b8'])
    fnp.true_divide(s.ce_b67, s.ce_S23T, out=s.ce_b67)
    # row scales and the 8-column queries (= _ce_same60)
    R0, R1, R4, R5 = s.ce_R
    fnp.true_divide(1.0, ss, out=R0)
    s.ce_inv_fresh = False; s.ce_inv_src = None
    fnp.multiply(R0, R0, out=R1)
    fnp.multiply(R1, R0, out=R4)
    fnp.multiply(R1, R1, out=R5)
    fnp.copyto(s.ce_R23, s.ce_R10)
    fnp.multiply(K['bN8'], s.ce_R01c, out=K['Q28'])
    Q0, Q1, T = K['Q08'], K['Q18'], K['T8']
    S = bufs["t"][0]                                                                  # fresh square view of the dead 't' slab
    fnp.copyto(S, C); fnp.fill_diagonal(S, 0.0); fnp.matmul(S, Q0, out=T[0])          # C,      inv
    fnp.multiply(S, S, out=S); fnp.matmul(S, Q1, out=T[1])                            # C*C,    i2
    fnp.copyto(S, D); fnp.fill_diagonal(S, 0.0); fnp.matmul(S, Q0, out=T[2])          # D,      inv
    fnp.matmul(S.T, Q1, out=T[3])                                                     # D^T,    i2
    fnp.multiply(S, S, out=S); fnp.matmul(S, Q1, out=T[5])                            # D*D,    i2
    fnp.multiply(C, D, out=S); fnp.fill_diagonal(S, 0.0); fnp.matmul(S, Q1, out=T[4]) # C*D,    i2
    fnp.multiply(K['o38'], s.ce_R6T, out=K['o38'])
    # the MLP on the 66 columns
    x = fnp.take(s.raw, K['idx'], axis=1)
    mean_t, istd_t, b1_t = rw
    fnp.subtract(x, mean_t, out=x); fnp.multiply(x, istd_t, out=x); fnp.clip(x, -8.0, 8.0, out=x)
    h1, h2 = K['h1'], K['h2']
    fnp.matmul(x, K['W1T'], out=h1); fnp.add(h1, b1_t, out=h1)
    gelu_inplace(fnp, flops.stats.norm.cdf, h1, h1, 'exact_erf')
    fnp.matmul(h1, K['W2T'], out=h2); fnp.add(h2, K['b2'], out=h2)
    gelu_inplace(fnp, flops.stats.norm.cdf, h2, h2, 'exact_erf')
    fnp.matmul(h2, K['W3T'], out=K['o'])
    d = K['d']
    fnp.add(K['o0'], _CI_K4P_B3, out=d)
    fnp.multiply(d, float(_CI_K4P_SCALE[t] * _CI_K4P_TAU), out=d)
    fnp.multiply(d, K['s4'], out=d)
    s.k4p_tok = (li, s.generation)
    _CI_K4P_INFO["applied"][li] = _CI_K4P_INFO["applied"].get(li, 0) + 1
    return fnp.add(g, d)


_ci_k4p_same60_parent = _ce_same60


def _ce_same60(s, C, D, sig):
    """(3)'s same60; after a K4CP pre in this layer only the columns c0..9 are computed (0..c0-1 were made in the pre)."""
    tok = getattr(s, 'k4p_tok', None)
    pk = s.packet
    if tok is None or pk is None or C is None or D is None or (pk[0], pk[1]) != tok:
        s.k4p_tok = None
        return _ci_k4p_same60_parent(s, C, D, sig)
    s.k4p_tok = None
    _ce_v(s)
    K = s.k4p
    s.ce_inv_fresh = False; s.ce_inv_src = None          # v2: the six row scales are still the pre's (same sigma; only R0 was rewritten, same value)
    fnp.multiply(K['bNc'], s.ce_R01c, out=K['Q2c'])
    S = s.scratch
    Q0, Q1, T = K['Q0c'], K['Q1c'], K['Tc']
    fnp.copyto(S, C); fnp.fill_diagonal(S, 0.0); fnp.matmul(S, Q0, out=T[0])          # C,      inv
    fnp.multiply(S, S, out=S); fnp.matmul(S, Q1, out=T[1])                            # C*C,    i2
    fnp.copyto(S, D); fnp.fill_diagonal(S, 0.0); fnp.matmul(S, Q0, out=T[2])          # D,      inv
    fnp.matmul(s.ce_ST, Q1, out=T[3])                                                 # D^T,    i2
    fnp.multiply(S, S, out=S); fnp.matmul(S, Q1, out=T[5])                            # D*D,    i2
    fnp.multiply(C, D, out=S); fnp.fill_diagonal(S, 0.0); fnp.matmul(S, Q1, out=T[4]) # C*D,    i2
    fnp.multiply(K['o3c'], s.ce_R6T, out=K['o3c'])
# ===================== end Claude-I K4CP =====================


_CF_WARM0 = _os.environ.get("CF_WARM0", "0") == "1"   # Claude-H warm0 (tier-1)



# ======================= Claude-H cub1: cubic first-join range-finder weights (production form) =======================
_CF_CUB1 = _os.environ.get("CF_CUB1", "1") == "1"


def _cf_cub1_weights(Aj, Pj, dA, e, s):
    u = fnp.sum(fnp.multiply(Aj, Aj), axis=0); v = fnp.sum(fnp.multiply(Pj, Pj), axis=0); w = fnp.sum(fnp.multiply(Aj, Pj), axis=0)
    d = fnp.sqrt(fnp.maximum(dA - 9.0 - 9.0 * e * e, 0.0))
    wAA = 2 * d * d * (u * v + w * w) + 4 * d * e * w * v + e * e * v * v
    wPP = (d * d * u * u + 2 * e * e * (u * v + w * w) + s * s * v * v + 4 * d * e * u * w
           + 2 * d * s * w * w + 4 * e * s * w * v)
    wAP = 2 * d * d * u * w + d * e * (2 * u * v + 3 * w * w) + 2 * d * s * w * v + 2 * e * e * w * v + e * s * v * v
    return wAA, wPP, wAP


def _cf_cub1_join(smm, Aj, Pj, dA, dP, e, s, Om, Yq):
    wAA, wPP, wAP = _cf_cub1_weights(Aj, Pj, dA, e, s)
    f32 = Om.dtype
    cAA = wAA.astype(f32)[:, None]; cPP = wPP.astype(f32)[:, None]; cAP = wAP.astype(f32)[:, None]
    ki = Aj.shape[0]
    F, FT, mid, Ajp, Pjp, midA, midP = smm._cb_join_packs[ki]
    fnp.copyto(Ajp, Aj)
    fnp.copyto(Pjp, Pj)
    _StrassenV29.mm(smm, FT, _ci_nn(Om), mid, 5)
    tA = fnp.multiply(midA, cAP)                 # wAP * (A^T Om), for the P rows
    tP = fnp.multiply(midP, cAP)                 # wAP * (P^T Om), for the A rows
    fnp.multiply(midA, cAA, out=midA)
    fnp.add(midA, tP, out=midA)
    fnp.multiply(midP, cPP, out=midP)
    fnp.add(midP, tA, out=midP)
    _StrassenV29.mm(smm, F, mid, _ci_nn(Yq), 5)
# ===================== end Claude-H cub1 =====================



# ======================= Claude-F NELZR / QP2ONE (2026-10-18): arithmetic-only join cuts =======================
_CF_NELZR = _os.environ.get("CF_NELZR", "1") != "0"
_CF_NELZR_MIN = float(_os.environ.get("CF_NELZR_MIN", "0.05"))
_CF_QP2ONE = _os.environ.get("CF_QP2ONE", "1") != "0"
_CF_NELZR_INFO = {"ok": 0, "guard": 0, "error": 0, "qp2one": 0, "lsjskip": 0, "warm0u": 0, "last_error": ""}   # v3: cumulative counters (read by gates)
_CF_WARM0U = _os.environ.get("CF_WARM0U", "1") != "0"      # v5: Claude-H warm0u (tier-2 range finder from U)
_CF_WARM0U_P = max(1, int(_os.environ.get("CF_WARM0U_P", "1")))   # v5: passes from U (1 = b5 one-pass, 2 = H's v1 values)


def _cf_nelzr(Qp, li=None):
    """(G, chol(G), G^-1 Qp^T) for an LZR lazy join, or None -> the caller keeps the parent's QR path.  G = Qp^T Qp is the aliased
    two-operand einsum (symmetric output, half billed); the Cholesky diagonal (positive) is |r_ii| of QR(Qp), so the guard is the
    parent's, tightened to CF_NELZR_MIN because the normal equations square the condition number in float32.  Requests match the
    parent's qr + guard (diagonal, abs, min, max) + .T + solve: einsum + cholesky + diagonal + min + max + .T + solve."""
    try:
        G = fnp.einsum('ia,ib->ab', Qp, Qp)
        Lc = fnp.linalg.cholesky(G)
        d = fnp.diagonal(Lc)
        lo = float(fnp.min(d))
        hi = float(fnp.max(d))
        if not (hi > 0.0 and lo / hi >= _CF_NELZR_MIN and lo / hi > _CI_LZR_THR):
            _CF_NELZR_INFO["guard"] += 1
            return None
        M = fnp.linalg.solve(G, Qp.T)
        _CI_LZR_GUARD_INFO["ok"] += 1
        _CF_NELZR_INFO["ok"] += 1
        return G, Lc, M
    except Exception as e:  # noqa: BLE001
        _k = "err_" + type(e).__name__
        _CF_NELZR_INFO["error"] += 1
        _CF_NELZR_INFO[_k] = _CF_NELZR_INFO.get(_k, 0) + 1
        _CF_NELZR_INFO["last_error"] = repr(e)[:160]
        return None
# ===================== end Claude-F NELZR / QP2ONE =====================



# ======================= Claude-H TRLZ v1: TR fresh loss on LZR lazy joins without R0 products =======================
def _cf_trlz_layers(txt):
    out_ = set()
    for part in str(txt).replace(" ", "").split(","):
        if "-" in part:
            a_, b_ = part.split("-"); out_ |= set(range(int(a_), int(b_) + 1))
        elif part:
            out_.add(int(part))
    return frozenset(out_)


_CF_TRLZ = str(_os.environ.get("CF_TRLZ", "samp")).strip().lower()
_CF_TRLZ = _CF_TRLZ if _CF_TRLZ in ("samp", "exact") else ""   # v2: only samp / exact turn it on
_CF_TRLZ_K, _CF_TRLZ_LI = 64, frozenset((13, 14))
if _CF_TRLZ:
    try:
        _CF_TRLZ_K = int(_os.environ.get("CF_TRLZ_K", "32"))
        _CF_TRLZ_LI = _cf_trlz_layers(_os.environ.get("CF_TRLZ_LI", "13-14"))
    except ValueError:
        _CF_TRLZ = ""
_CF_TRLZ_INFO = {"samp": 0, "exact": 0, "skip": 0}


def _cf_trlz_join(core, li, j, Aj, Pj, Qp, Z_st, L_st, w2b_list, s_list, e_list, c1_list, c2_list, rres, nj, bufs, _x4, _f4, _w1c):
    X3 = None if _x4 is None else (_cf_view(_x4, (slice(None), 0)) if (_x4.ndim == 4 and _x4.shape[1] == 1) else _x4)
    F3 = None if _f4 is None else (_cf_view(_f4, (slice(None), 0)) if (_f4.ndim == 4 and _f4.shape[1] == 1) else _f4)
    if (not _CI_TR2 or X3 is None or F3 is None or _w1c is None or X3.ndim != 3 or F3.ndim != 3
            or int(X3.shape[1]) != nj or int(Qp.shape[0]) != nj or int(Qp.shape[1]) != int(F3.shape[1])):
        _CF_TRLZ_INFO["skip"] += 1
        return
    st = _ci_tr_state(core)
    n = int(X3.shape[2])
    r_ = int(F3.shape[1])
    b = _ci_tr2_buf(n)
    bv = b["v"]
    X0, X1 = _cf_view(X3, (0,)), _cf_view(X3, (1,))
    F0, F1 = _cf_view(F3, (0,)), _cf_view(F3, (1,))
    tb = bufs["t"]
    Td = _cf_view(tb, (slice(0, 2), slice(None, nj)))
    L = _ci_vs(L_st, j)
    LT = _ci_vT(L)
    Zp = fnp.multiply(_ci_vs(_ci_vs(Z_st, j), slice(None, nj)), _w1c)
    y = Zp[:, int(rres) + 1]
    # dense moments (side 0): exactly as TR2
    fnp.multiply(X3, X3, out=Td); fnp.sum(Td, axis=1, out=bv["AAPP0"])
    Td0 = _cf_view(Td, (slice(0, 1),))
    fnp.multiply(_cf_view(X3, (slice(0, 1),)), _cf_view(X3, (slice(1, 2),)), out=Td0); fnp.sum(Td0, axis=1, out=bv["AP0"])
    fnp.matmul(y, X3, out=bv["y0"])
    G = fnp.matmul(Zp, LT)
    fnp.multiply(_cf_view(X3, (slice(1, 2),)), G, out=Td0); fnp.sum(Td0, axis=1, out=bv["ZLP0"])
    # factor moments (side 1) = moments of P X, P = Qp Qp^+ (orthogonal), P X = Qp F
    if _CF_TRLZ == "exact":
        _CF_TRLZ_INFO["exact"] += 1
        GQ = fnp.matmul(_ci_vT(Qp), Qp)                               # (r, r)
        GF = fnp.matmul(GQ, F3)                                       # (2, r, n)
        fnp.sum(fnp.multiply(F3, GF), axis=1, out=bv["AAPP1"])
        fnp.sum(fnp.multiply(F0, GF[1]), axis=0, out=_cf_view(bv["AP1"], (0,)))
    else:
        _CF_TRLZ_INFO["samp"] += 1
        k = max(1, min(int(_CF_TRLZ_K), nj))
        idx = fnp.floor_divide(fnp.multiply(fnp.arange(k), nj), k)   # v2: spread over all nj rows (k=64, nj=832: = v1 rows)
        kk = int(idx.shape[0])
        Xs = fnp.take(X3, idx, axis=1)                                # (2, k, n)
        Qs = fnp.take(Qp, idx, axis=0)                                # (k, r)
        RX = fnp.subtract(Xs, fnp.matmul(Qs, F3))                      # (2, k, n) residual rows
        sc = float(nj) / float(kk)
        rAAPP = fnp.multiply(fnp.sum(fnp.multiply(RX, RX), axis=1), sc)
        rAP = fnp.multiply(fnp.sum(fnp.multiply(RX[0], RX[1]), axis=0), sc)
        fnp.subtract(bv["AAPP0"], rAAPP, out=bv["AAPP1"])
        fnp.subtract(_cf_view(bv["AP0"], (0,)), rAP, out=_cf_view(bv["AP1"], (0,)))
    Qy = fnp.matmul(y, Qp)
    fnp.matmul(Qy, F3, out=bv["y1"])
    QG = fnp.matmul(fnp.matmul(_ci_vT(Qp), Zp), LT)
    Tr0 = fnp.multiply(F1, QG)
    fnp.sum(Tr0, axis=0, out=_cf_view(bv["ZLP1"], (0,)))
    # v of both sides and the delta: exactly as TR2
    w2, s_, e_, c1, c2 = w2b_list[j], s_list[j], e_list[j], c1_list[j], c2_list[j]
    fnp.copyto(bv["e0"], e_); fnp.multiply(w2, 2.0, out=bv["w2x2"])
    fnp.copyto(bv["w2"], w2); fnp.copyto(bv["s"], s_); fnp.multiply(e_, 2.0, out=bv["ex2"])
    fnp.multiply(c1, 2.0 / 3.0, out=bv["c1"]); fnp.multiply(c2, 2.0 / 3.0, out=bv["c2"])
    fnp.multiply(bv["Mb1"], bv["CCb"], out=b["T4"])
    fnp.sum(b["T4"], axis=1, out=b["Vb"])
    fnp.matmul(b["PM3"], bv["PPAP"], out=b["DM"])
    rho3 = fnp.add(fnp.dot(bv["dAP"], c1), fnp.dot(bv["dPP"], c2))
    td = fnp.add(fnp.matmul(X0, bv["vAd"]), fnp.matmul(X1, bv["vPd"]))
    tf = fnp.matmul(Qp, fnp.add(fnp.matmul(F0, bv["vAf"]), fnp.matmul(F1, bv["vPf"])))
    fnp.subtract(td, tf, out=td)
    fnp.add(td, fnp.multiply(y, rho3), out=td)
    fnp.add(td, fnp.matmul(Zp, fnp.matmul(LT, bv["dPP"])), out=td)
    if _CF_TRLZ_G != 1.0:   # Claude-H TRLZ gain
        fnp.multiply(td, _CF_TRLZ_G, out=td)
    st["delta"] = (int(li), td)
# ===================== end Claude-H TRLZ v1 =====================



# ======================= Claude-H JSK v2: physical heavy-column join sketch =======================
def _cf_jsk_layers(txt):
    out_ = set()
    for part in str(txt).replace(" ", "").split(","):
        if "-" in part:
            a_, b_ = part.split("-"); out_ |= set(range(int(a_), int(b_) + 1))
        elif part:
            out_.add(int(part))
    return frozenset(out_)


try:
    _CF_JSK_LI = _cf_jsk_layers(_os.environ.get("CF_JSK_LI", "5-11")) if _CF_JSK else frozenset()
except ValueError:
    _CF_JSK_LI = frozenset()
_CF_JSK_INFO = {"hit": 0, "skip": 0}


def _cf_jsk_ok(smm, bd_active, li, j, ka, lazy, Aj):
    _CF_JSK_CUR[0] = int(li)   # v2c: layer for the width lookup in _cf_jsk_join
    if lazy or int(li) not in _CF_JSK_LI or (_CF_CUB1 and ka == 0):
        return False
    if int(Aj.shape[0]) not in getattr(smm, "_cf_jsk_packs", {}):
        _CF_JSK_INFO["skip"] += 1
        return False
    if bd_active:
        wide = getattr(smm, "_bd_wide_sources", [])
        q = 1024 if (_BD_FULLWIDTH_CONTROL or (j < len(wide) and wide[j])) else _BD_Q[j]
        if q != 1024 and not (_CF_JSK_NARROW and 2 * q > _CF_JSK_WL.get(int(li), _CF_JSK_W)):   # v2d: narrow sources allowed
            _CF_JSK_INFO["skip"] += 1
            return False
    return True


def _cf_jsk_join(smm, Aj, Pj, dAj, dPj, Om, Yq):
    ki = int(Aj.shape[0])
    _wl = _CF_JSK_WL.get(_CF_JSK_CUR[0])
    if _wl and (ki, _wl) in getattr(smm, "_cf_jsk_packs_w", {}):   # v2c per-layer width
        F1, FT1, mid1 = smm._cf_jsk_packs_w[ki, _wl]
        _cbuf = smm._cf_jsk_cbuf_w[ki, _wl]
    else:
        F1, FT1, mid1 = smm._cf_jsk_packs[ki]
        _cbuf = smm._cf_jsk_cbuf[ki]
    W_ = int(F1.shape[-1])
    wA = fnp.multiply(fnp.sum(fnp.multiply(Aj, Aj), axis=0), dAj[:, 0])
    wP = fnp.multiply(fnp.sum(fnp.multiply(Pj, Pj), axis=0), dPj[:, 0])
    idx = fnp.argsort(fnp.negative(fnp.concatenate([wA, wP])))[:W_]
    C = _cbuf                                                     # v2b/v2c: (ki, 2n) staging in pack_left after F1, no allocation
    n_ = int(Aj.shape[1])
    fnp.copyto(C[:, :n_], Aj)
    fnp.copyto(C[:, n_:], Pj)
    fnp.take(C, idx, axis=1, out=_cf_view(F1, (0, 0)))
    dsel = fnp.take(fnp.concatenate([dAj[:, 0], dPj[:, 0]]), idx)
    _StrassenV29.mm(smm, FT1, _ci_nn(Om), mid1, 5)
    m0 = _cf_view(mid1, (0, 0))
    fnp.multiply(m0, dsel[:, None], out=m0)
    _StrassenV29.mm(smm, F1, mid1, _ci_nn(Yq), 5)
    _CF_JSK_INFO["hit"] += 1
# ===================== end Claude-H JSK v2 =====================


_CF_JSK_NARROW = _os.environ.get("CF_JSK_NARROW", "1") == "1"   # Claude-H JSK v2d


