def _cf_fp1skip_keys():
    """v2: group F only while fbw3first runs those keys plain on the first predict (fbw3first and the deadline machinery on)."""
    ks = _CF_FP1SKIP_R if "R" in _CF_FP1SKIP else frozenset()
    if "U" in _CF_FP1SKIP:   # Claude-F FP1SKIP v3: views made on first dispatch (#2+) or never
        ks = ks | _CF_FP1SKIP_U
    if "F" in _CF_FP1SKIP and globals().get("_CF_" + "FBW3FIRST") and globals().get("_CF_" + "DL_ON"):
        ks = ks | _CF_FP1SKIP_F
    return ks


# Claude-F FBW3FIRST v2: BQW56 v3 transport FBW2 keys run plain on the first predict after a setup (requests)
_CF_FBW3FIRST = _os.environ.get("CF_FBW3FIRST", "1") != "0"
_CF_FBW3FIRST_KEYS = frozenset((('mm', (1, 48, 256, 224), (1, 48, 224, 2128), 4), ('mm', (1, 48, 256, 224), (1, 48, 224, 2096), 4), ('mm', (1, 48, 240, 224), (1, 48, 224, 2016), 4)))


