# ===================== Claude-I CDIAG production v2 (= v1 + failed-predict guards): pruned-neuron covariance block on the diagonal (2026-10-19) =====================
_CI_CDG = _os.environ.get("CI_CDG", "1") != "0"
_CI_CDG_PEND = [None]
_CI_CDG_INFO = {"stash": 0, "fix": 0, "mismatch": 0}


def _ci_cdg_stash(li, W, APin, APout, mi):
    """Instead of W[mi:] @ C: zero the pruned rows of the W C slot and keep v_i = sum_j W[i, j]^2 C[j, j]."""
    fnp.copyto(APout[-1, 0, mi:], _CB_F32_ZERO)
    if _CI_REQC4:
        _reqc4_wt = W[mi:]
        w2 = fnp.multiply(_reqc4_wt, _reqc4_wt)
    else:
        w2 = fnp.multiply(W[mi:], W[mi:])
    v = fnp.matmul(w2, fnp.diagonal(APin[-1, 0]))
    _CI_CDG_PEND[0] = (int(li), int(mi), v)
    _CI_CDG_INFO["stash"] += 1


def _ci_cdg_fix(C, li):
    """C_pre rows of the pruned neurons: mirror the formed columns inside their diagonal tile, diagonal block = diag(v)."""
    pend = _CI_CDG_PEND[0]
    _CI_CDG_PEND[0] = None
    sli, mi, v = pend
    if sli != int(li):
        _CI_CDG_INFO["mismatch"] += 1
        return                        # Claude-I CDIAG v2: a block stashed at another layer is never applied
    n = C.shape[0]
    t0 = (mi // (n // 4)) * (n // 4)
    if t0 < mi:
        fnp.copyto(C[mi:, t0:mi], C[t0:mi, mi:].T)
    if _CI_REQC4:
        _reqc4_ct = C[mi:, mi:]
        fnp.copyto(_reqc4_ct, _CB_F32_ZERO)
        fnp.fill_diagonal(_reqc4_ct, v)
    else:
        fnp.copyto(C[mi:, mi:], _CB_F32_ZERO)
        fnp.fill_diagonal(C[mi:, mi:], v)
    _CI_CDG_INFO["fix"] += 1
# ===================== end Claude-I CDIAG production v2 =====================


_CF_BCOPY = _os.environ.get("CF_BCOPY", "1") == "1"   # Claude-H bundle-copy grouping


# Claude-H FROM12: young window 5 from this layer on (99 = never = parent bytes)
_CF_AGE5_FROM = int(_os.environ.get("CF_AGE5_FROM", "12"))
_CF_F12_PKT = int(_os.environ.get("CF_F12_PKT", "99"))   # Claude-H FROM12 v10 diagnostic
_C_TMD_MODE = _os.environ.get("CI_TMD_LITE", "2")   # Claude-R tmd-lite v2 (LV502)
if _C_TMD_MODE not in ("0", "1", "2"):
    raise ValueError("CI_TMD_LITE must be 0, 1 or 2")
_C_TMD_ON = _C_TMD_MODE != "0"
_C_TMD_SITES = _os.environ.get("CI_TMD_LITE_SITES", "f68")
_C_TMD_G22S = float(_os.environ.get("CI_TMD_G22S", "1.0"))   # v3: g22 metric = METRIC_C + s (d - METRIC_C)
_C_TMD_G22_LI = (lambda t_: frozenset(range(int(t_.partition("-")[0]), int(t_.partition("-")[2] or t_.partition("-")[0]) + 1)))(_os.environ.get("CI_TMD_G22_LI", "0-15"))
_CF_DROWQ = _os.environ.get("CF_DROWQ", "1") != "0"   # Claude-R DROW-q v1: L7/L8 h678 young hub rows = source width _BD_Q[li]
_CF_DROWQ_M = ({7: int(_BD_Q[7]), 8: int(_BD_Q[8])} if (_CF_DROWQ and int(_BD_Q[7]) == 928 and int(_BD_Q[8]) == 928) else {})


# ===================== Team4 H678/KIFIX-P source draft v1 =====================
_CI_DR_ACTIVE = any(_os.environ.get(_ci_dr_env, "1" if _ci_dr_env in ("CI_H6", "CI_H7", "CI_H8") else "0") == "1"   # M h678_on_v1: 켜짐 문 기본값 = 안쪽 기본값
                    for _ci_dr_env in ("CI_H6", "CI_H7", "CI_H8", "CI_H78", "CI_KFX"))
if _CI_DR_ACTIVE:
    # Flags are read once; a parent-derived setup is required for each setting.
    _CI_DR_H6 = _os.environ.get("CI_H6", "1") == "1"
    _CI_DR_H7 = (_os.environ.get("CI_H7", "1") == "1" or _os.environ.get("CI_H78", "0") == "1")
    _CI_DR_H8 = (_os.environ.get("CI_H8", "1") == "1" or _os.environ.get("CI_H78", "0") == "1")
    _CI_DR_KFX = _os.environ.get("CI_KFX", "1") == "1"

    # KIFIX-P: fixed layer range and existing prepared-key requirements.
    if _CI_DR_KFX:
        if _os.environ.get("CI_KFX_LI", "11-14").strip() != "11-14":
            raise ValueError("KIFIX-P supports CI_KFX_LI=11-14 only")
        if (_CB_PRUNE_M[11:15] != (960,) * 4
                or _CB_PRUNE_K[11:15] != (832,) * 4
                or _CB_PRUNE_M[10:14] != (960,) * 4):
            raise RuntimeError("KIFIX-P parent correction geometry changed")
        if ("mm", (1, 1, 960, 128), (1, 1, 128, 1024), 3) not in _STAGE1_CALLPLAN_ROOTS:
            raise RuntimeError("KIFIX-P existing level-3 correction root missing")
        if ((960, 128, 1024, 3) in _CI_RRLEV_MAP
                and ("mm", (1, 1, 960, 128), (1, 1, 128, 1024), 4) not in _STAGE1_CALLPLAN_ROOTS):
            raise RuntimeError("KIFIX-P selected RRLEV sibling missing")

    if _CI_DR_H6 or _CI_DR_H7 or _CI_DR_H8:
        # H6/H7/H8: setup-owned fixed R48V programs for selected young hubs.
        _CI_DR_H678_PREWARM = _os.environ.get("CI_H678_PREWARM", "0") != "0"
        _ci_dr_hub_setup_parent = Estimator.setup

        def _ci_dr_hub_setup(self, *args, **kwargs):
            global _ci_r48v_try
            result = _ci_dr_hub_setup_parent(self, *args, **kwargs)
            if not _CI_DR_H678_PREWARM:
                return result
            state = getattr(getattr(self, "core", None), "_be1", None)
            if state is None or not _BE1_EXACT or not _CI_R48V:
                return result
            bank = state.bank
            bank.require()
            layers = ((6,) if _CI_DR_H6 else ()) + ((7,) if _CI_DR_H7 else ()) + ((8,) if _CI_DR_H8 else ())
            previous_try = _ci_r48v_try
            _ci_r48v_try = _ci_r48vp_direct
            try:
                seen = set()
                for li in layers:
                    key = (_CF_DROWQ_M.get(li,960), 2*sum(_BD_Q[li-4:li]), _CF_DROWQ_M.get(li,960), 5)
                    if key in seen:
                        continue
                    seen.add(key)
                    entry = bank.r48.get(key)
                    if entry is None:
                        raise RuntimeError("H6/H7/H8 setup missing young plan: " + repr((li,key)))
                    x,y,out,blocks,rows,child,quarters = entry
                    programs = _ci_r48v_fixed(bank.executor, (id(bank),key), x,
                                              bank.owner, x,y,out,rows)
                    if programs is None:
                        raise RuntimeError("H6/H7/H8 setup could not prewarm R48V: " + repr((li,key)))
                bank.require()
            finally:
                _ci_r48v_try = previous_try
            return result

        Estimator.setup = _ci_dr_hub_setup

        if not _CI_DR_H678_PREWARM:
            # Parent lazy budgets default to zero. Only these selected E1 sites may
            # build on first use; do not change budgets or other R48V call paths.
            _ci_dr_h678_lazy_keys = frozenset(
                (_CF_DROWQ_M.get(li,960), 2*sum(_BD_Q[li-4:li]), _CF_DROWQ_M.get(li,960), 5)
                for li, enabled in ((6, _CI_DR_H6), (7, _CI_DR_H7), (8, _CI_DR_H8))
                if enabled)
            _ci_dr_hub_run_r48_parent = _BE1Plans.run_r48

            def _ci_dr_hub_run_r48(self, key):
                global _ci_r48v_try
                if _CI_R48V and _BE1_EXACT and key in _ci_dr_h678_lazy_keys:
                    self.require()
                    x, y, out, blocks, rows, child, quarters = self.r48[key]
                    site = (id(self), key)
                    cached = _CI_R48V_FIX_TAB.get(site)
                    if cached is None or cached[0] is not x or cached[1] != self.executor._scratch_generation:
                        previous_try = _ci_r48v_try
                        _ci_r48v_try = _ci_r48vp_direct
                        try:
                            programs = _ci_r48v_fixed(self.executor, site, x, self.owner, x, y, out, rows)
                            if programs is None:
                                raise RuntimeError("H6/H7/H8 first use could not build R48V: " + repr(key))
                        finally:
                            _ci_r48v_try = previous_try
                return _ci_dr_hub_run_r48_parent(self, key)

            _BE1Plans.run_r48 = _ci_dr_hub_run_r48

# ===================== end Team4 H678/KIFIX-P source draft v1 =====================


# ===================== Claude-F OPF v2: oldpack routes at the FROM tier bounds (2026-10-20) =====================
_CF_OPF = _os.environ.get("CF_OPF", "1") != "0"


def _cf_opf_bounds(li):
    """(ka, kb) of the oldpack routes at layer li: (li-4, li-7); with the young window 5 from FROM (H: no join at FROM, KBCAP)
    (li-5, li-8) for li >= FROM."""
    _f = globals().get('_CF_AGE5_FROM', 99)
    if _CF_OPF and _f < 99 and li >= _f:
        return li - 5, li - 8
    return li - 4, li - 7
# ===================== end Claude-F OPF v2 =====================


# ======================= Claude-F TAKESPLIT v3: contiguous prefix of a packet gather copied, tail taken =======================
_CF_TKS = _os.environ.get("CF_TKS", "1") != "0"
_CF_TKS_YOUNG = _os.environ.get("CF_TKS_YOUNG", "1") != "0"
_CF_TKS_P0L = {(10, 896): 819, (10, 928): 860, (11, 864): 795, (11, 896): 833, (11, 928): 889, (12, 864): 775, (12, 896): 823, (13, 832): 772, (13, 864): 808, (14, 832): 750, (14, 864): 807, (9, 896): 852, (9, 928): 871, 10: 819, 11: 795, 12: 775, 13: 772, 14: 750, 9: 852}
_CF_TKS_LI = [None]
_CF_TKS_INFO = {"split": 0, "fallback": 0, "skip": 0, "first": 0}


def _cf_tks_ok(li, idx):
    """P0 of key li (young: layer; oldpack: (layer, cap), else that layer's young value) when idx[:P0] == 0..P0-1, else 0 (parent take)."""
    if _CF_RR_PLAIN[0]:          # the first predict after a setup keeps the parent gathers (its request headroom)
        _CF_TKS_INFO["first"] += 1
        return 0
    p0 = _CF_TKS_P0L.get(li) or (_CF_TKS_P0L.get(li[0], 0) if isinstance(li, tuple) else 0)
    if p0 <= 0 or idx.shape[0] < p0:
        _CF_TKS_INFO["skip"] += 1
        return 0
    if int(idx[p0 - 1]) != p0 - 1:
        _CF_TKS_INFO["fallback"] += 1
        return 0
    _CF_TKS_INFO["split"] += 1
    return p0


def _cf_tks_rows(base, source, q, tail, out, p0):
    """out = base[source, 0, idx, :q] with idx = 0..p0-1 then `tail`: prefix rows copied, tail rows gathered."""
    fnp.copyto(_cf_view(out, (slice(None, p0),)), _cf_view(base, (source, 0, slice(None, p0), slice(None, q))))
    fnp.take(_cf_view(base, (source, 0, slice(None, 960), slice(None, q))), tail, axis=0,
             out=_cf_view(out, (slice(p0, None),)), mode='clip')
# ===================== end Claude-F TAKESPLIT v3 =====================


# Claude-F PSCAT1: permutation scatter (put_along_axis by the inverse) instead of take + copyto at the BD birth / slot sites
_CF_PSCAT = _os.environ.get("CF_PSCAT", "1") != "0"


# ===================== Team4 XSG young-only source draft v1 =====================
_CF_XSG = _os.environ.get("CF_XSG", "1") == "1"
if _CF_XSG:
    def _cf_xsg_steady():
        # Match terminal RG's first-predict marker, including restore/re-setup.
        # Do not depend on _CF_DL_ON: its lightening policy is separate.
        return not (_CF_DL_FIRST[0] and _CF_DL_FIRST_LEFT[0] == _CF_DL_FIRST_N)

    def _cf_xsg_map(indices, count, cap):
        # Parent packets provide unique ascending flatnonzero indices in [0,960).
        # All unselected rows target the last padding row, repaired below.
        inverse = fnp.full(960, cap - 1, dtype=fnp.int64)
        positions = fnp.arange(count, dtype=fnp.int64)
        fnp.put_along_axis(inverse, indices, positions, axis=0)
        return fnp.reshape(inverse, (960, 1))

    def _cf_xsg_rows(destination, source, inverse, count):
        fnp.put_along_axis(destination, inverse, source, axis=0)
        # Original padded indices are zero: copy SOURCE ROW ZERO, not scalar 0.
        # Repair every padding row before any R48 transform consumes the pack.
        # Transient basic views: do not cache a new destination slice per count.
        fnp.copyto(destination[count:, :], source[0:1, :])
# ===================== end Team4 XSG young-only source draft v1 =====================


# ======================= Claude-I ACAP: smaller keep_L_1 / keep_L_7 color arenas (2026-10-20) =======================
_CI_ACAP = _os.environ.get("CI_ACAP", "1") != "0"
_CI_ACAP_SKIP = _CI_ACAP and _os.environ.get("CI_ACAP_SKIP", "1") != "0"
_CI_ACAP_INFO = {"capped": {}, "skipped": 0, "unfit_premake": 0}


def _ci_acap_parse(v):
    out = {}
    for part in (v or "").split(","):
        part = part.strip()
        if part:
            nm, _, n = part.partition(":")
            out[nm.strip()] = int(n)
    return out


_CI_ACAP_CAPS = _ci_acap_parse(_os.environ.get("CI_ACAP_CAPS", "keep_L_1:4194304,keep_L_7:6815744")) if _CI_ACAP else {}
_CI_ACAP_ROLE_ARENA = {(row[0], row[1]): row[2] for row in _STAGE1_COLORED_ASSIGNMENT}


def _ci_acap_outer_ok(role, P, shape):
    """v2: an L / R layer shape that misses only because its arena is capped (the cf5 copy-free binder never asks for it)."""
    if not (_CI_ACAP_SKIP and _CI_CF5) or role not in ("L", "R"):
        return False
    nm = _CI_ACAP_ROLE_ARENA.get((role, P))
    if nm is None or nm not in _CI_ACAP_CAPS:
        return False
    _CI_ACAP_INFO["e1_outer_ok"] = _CI_ACAP_INFO.get("e1_outer_ok", 0) + 1
    return True


def _ci_acap_fits(key, shape):
    nm = _CI_ACAP_ROLE_ARENA.get(tuple(key))
    cap = _CI_ACAP_CAPS.get(nm) if nm is not None else None
    if cap is None or math.prod(shape) <= cap:
        return True
    _CI_ACAP_INFO["unfit_premake"] += 1
    return False
_CI_ACAP_LAZY_TAB = {}   # v3: lazy root key -> "cf" (bind copy-free) | "fail" (dense guard, not retried)
if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):
    _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | {"_CI_ACAP_LAZY_TAB"}))


def _ci_acap_lazy_outer_ok(role, P, shape):
    """v3: the lazy-root twin of _ci_acap_outer_ok (the caller has checked P0 == 1 and that P is an outer layer)."""
    if not (_CI_ACAP_SKIP and _CI_CF5 and _CI_CF) or role not in ("L", "R"):
        return False
    nm = _CI_ACAP_ROLE_ARENA.get((role, P))
    if nm is None or nm not in _CI_ACAP_CAPS:
        return False
    _CI_ACAP_INFO["lazy_outer_ok"] = _CI_ACAP_INFO.get("lazy_outer_ok", 0) + 1
    return True


def _ci_acap_lazy_bind(owner, key):
    """v3: predict-time binding of a lazy root.  Marked roots (an outer slab only fits uncapped) go to the copy-free binder, which
    skips the outer L / R slabs; if it declines or raises, the root stays on the dense guard path (v2 behaviour) for good."""
    if _CI_ACAP_LAZY_TAB.get(key) != "cf":
        return owner._bind_callplan(*key)
    try:
        plan = _ci_cf_bind(owner, key[1], key[2], key[3], key)
    except Exception:  # noqa: BLE001  binding is an optimisation only
        plan = None
    if plan is None:
        _CI_ACAP_LAZY_TAB[key] = "fail"
        _CI_ACAP_INFO["lazy_cf_fail"] = _CI_ACAP_INFO.get("lazy_cf_fail", 0) + 1
    else:
        _CI_ACAP_INFO["lazy_cf"] = _CI_ACAP_INFO.get("lazy_cf", 0) + 1
    return plan


# ===================== end Claude-I ACAP =====================


_CF_E1BCOPY = _os.environ.get("CF_E1BCOPY", "recon")   # Claude-H E1 old-pack copy grouping: 1 | read | recon
if _CF_E1BCOPY not in ('1', 'read', 'recon'): _CF_E1BCOPY = ''


def _e1bc_runs(widths):
    """(c0, c1, q, column offset) for each run of equal widths over the (source, leg) channels."""
    ch = [q for q in widths for _leg in range(2)]
    runs, c0, off = [], 0, 0
    while c0 < len(ch):
        c1 = c0
        while c1 < len(ch) and ch[c1] == ch[c0]:
            c1 += 1
        runs.append((c0, c1, ch[c0], off))
        off += (c1 - c0) * ch[c0]
        c0 = c1
    return tuple(runs)


_CF_GRX = _os.environ.get("CF_GRX", "1") != "0"   # Claude-H GRAM-RETIRE-11


def _cf_grx_layer():
    """Last non-lazy join layer: JOIN_LAZY_FROM - 1, or one earlier when that layer is the window-5 FROM layer (no join there)."""
    last = JOIN_LAZY_FROM - 1
    frm = globals().get("_CF_AGE5_FROM", 99)
    return last - 1 if (frm < 99 and last == frm) else last


def _cf_grx_s2_layer():
    """Claude-F GRX-LZ: last non-lazy tier-2 move: MOVE_LAZY_FROM - 1, or one earlier when that is the window-5 FROM layer (no join, so no move)."""
    last = MOVE_LAZY_FROM - 1
    frm = globals().get("_CF_AGE5_FROM", 99)
    return last - 1 if (frm < 99 and last == frm) else last


def _cf_grx_sched_ok():
    """Claude-F GRX-LZ: the lazy schedules the retire was checked on: moves lazy from 13, joins lazy from 13 (H's GRX) or 11."""
    return MOVE_LAZY_FROM == 13 and JOIN_LAZY_FROM in (11, 13)


# ======================= Claude-H HE78: HUBM column mask on the L7/8 young hubs (production core v1, 2026-10-20) =======================
_CF_HE78 = _os.environ.get("CF_HE78", "1") == "1"
_CF_HE78_F = float(_os.environ.get("CF_HE78_F", "0.08"))
_CF_HE78_LAYERS = frozenset(int(v) for v in _os.environ.get("CF_HE78_LAYERS", "7,8").split(",") if v.strip())
_HE78_INFO = {"calls": 0, "r48": 0, "dense": 0}


def _he78_qn(q):
    qn = [int((1.0 - _CF_HE78_F) * v + 0.5) for v in q]
    ex = sum(qn) - (sum(qn) // 32) * 32
    qn[max(range(len(q)), key=lambda i: (q[i], -i))] -= ex
    return qn


def _he78_hub(state, bufs, apb4, start, end, m):
    q = [int(v) for v in _BD_Q[start:end]]
    qn = _he78_qn(q)
    if min(qn) < 64 or (2 * sum(qn)) % 64:
        return None
    wn = 2 * sum(qn)
    key = (m, wn, m, 5)
    lap = bufs['lap4']
    cols = []
    for t, s_ in enumerate(range(start, end)):
        w = None
        for leg in range(2):
            Ls = _cfv(lap, (2 * s_ + leg, 0, slice(None, m), slice(None, q[t])))
            Xs = _cfv(apb4, (2 * s_ + leg, 0, slice(None, m), slice(None, q[t])))
            nl = fnp.sum(fnp.multiply(Ls, Ls), axis=0)
            nx = fnp.sum(fnp.multiply(Xs, Xs), axis=0)
            v = fnp.sqrt(fnp.multiply(nl, nx))
            w = v if w is None else fnp.add(w, v)
        order = fnp.argsort(w, kind='stable')
        cols.append(fnp.sort(order[q[t] - qn[t]:]))          # kept columns, ascending (same order as the full pack)
    if key in state.bank.r48:
        x, y, o = state.bank.r48[key][:3]
        off = 0
        for t, s_ in enumerate(range(start, end)):
            for leg in range(2):
                fnp.take(_cfv(lap, (2 * s_ + leg, 0, slice(None, m), slice(None, q[t]))), cols[t], axis=1, out=x[0, 0, :, off:off + qn[t]])
                fnp.copyto(y[0, 0, off:off + qn[t], :], fnp.swapaxes(fnp.take(_cfv(apb4, (2 * s_ + leg, 0, slice(None, m), slice(None, q[t]))), cols[t], axis=1), -1, -2))
                off += qn[t]
        state.bank.run_r48(key)
        fnp.copyto(bufs['hub'][:m, :m], o[0, 0])
        _HE78_INFO["r48"] += 1
    else:
        X = fnp.concatenate([fnp.take(_cfv(lap, (2 * s_ + leg, 0, slice(None, m), slice(None, q[t]))), cols[t], axis=1)
                             for t, s_ in enumerate(range(start, end)) for leg in range(2)], axis=1)
        Y = fnp.concatenate([fnp.take(_cfv(apb4, (2 * s_ + leg, 0, slice(None, m), slice(None, q[t]))), cols[t], axis=1)
                             for t, s_ in enumerate(range(start, end)) for leg in range(2)], axis=1)
        fnp.matmul(X, fnp.transpose(Y), out=bufs['hub'][:m, :m])
        _HE78_INFO["dense"] += 1
    fnp.copyto(bufs['hub'][m:, :], _CB_F32_ZERO)
    fnp.copyto(bufs['hub'][:m, m:], _CB_F32_ZERO)
    state.count('L%d_young%d_he78' % (state.li, m))
    _HE78_INFO["calls"] += 1
    return bufs['hub']
# ===================== end Claude-H HE78 =====================


# ===================== Claude-F HE78 lazy keys (2026-10-20): masked-width R48V programs build on first use =====================
if _CF_HE78 and '_ci_dr_h678_lazy_keys' in globals():
    _cf_he78lz = set(_ci_dr_h678_lazy_keys)
    for _cf_he78lz_li, _cf_he78lz_on in ((6, globals().get('_CI_DR_H6')), (7, globals().get('_CI_DR_H7')), (8, globals().get('_CI_DR_H8'))):
        if _cf_he78lz_on and _cf_he78lz_li in _CF_HE78_LAYERS:
            _cf_he78lz_q = _he78_qn([int(v) for v in _BD_Q[_cf_he78lz_li - 4:_cf_he78lz_li]])
            if min(_cf_he78lz_q) >= 64 and (2 * sum(_cf_he78lz_q)) % 64 == 0:
                _cf_he78lz.add((_CF_DROWQ_M.get(_cf_he78lz_li,960), 2 * sum(_cf_he78lz_q), _CF_DROWQ_M.get(_cf_he78lz_li,960), 5))
    _ci_dr_h678_lazy_keys = frozenset(_cf_he78lz)
# ===================== end Claude-F HE78 lazy keys =====================


# ======================= Claude-I FMA v9: alternative-basis Winograd on the deep levels of copy-free plans (2026-10-20) =======================
if "_CI_REQ_CF_L" not in globals():   # bases without the in-place request pairing
    _CI_REQ_CF_L = False
_CI_FMA = _os.environ.get("CI_FMA", "1") != "0"
_CI_FMA_LEV = _os.environ.get("CI_FMA_LEV", "fw")
_CI_FMA_ROOTS = _os.environ.get("CI_FMA_ROOTS", "all")
_CI_FMA_FIRST = _os.environ.get("CI_FMA_FIRST", "1") == "1"
_CI_FMA_SETUPV = _os.environ.get("CI_FMA_SETUPV", "1") != "0"
_CI_FMA_MINF = float(_os.environ.get("CI_FMA_MINF", "2.5")) * 1e6   # v8: least estimated F saved per call (elements)
_ci_fma_n = _ci_cf_plan.__code__.co_varnames[:_ci_cf_plan.__code__.co_argcount]
_ci_fma_d = _ci_cf_plan.__defaults__ or ()
_CI_FMA_PLAIN_MM = ((_ci_cf_plan.__kwdefaults__ or {}).get("_matmul")   # the plain leaf product (the _matmul default)
                    or dict(zip(_ci_fma_n[len(_ci_fma_n) - len(_ci_fma_d):], _ci_fma_d))["_matmul"])
_CI_FMA_E1 = _os.environ.get("CI_FMA_E1", "1") != "0"
_CI_FMA_E1W_MM = getattr(globals().get("_CiE1wFnp"), "matmul", None)   # the E1W table dispatcher (a plain function)
_CI_FMA_TAB = {}      # id(layers) -> record (layers kept: no id reuse)
_CI_FMA_VTAB = {}     # id(layer-0 slot tuple) -> (tuple, V0 nested view (b, 7, P0, bits.., H, bits.., W))
_CI_FMA_MTAB = {}     # id(root decode columns) -> (columns, layer-0 M slab (b, 7 P0, h1, v1))
_CI_FMA_W = [False]   # True while a root runs its fused leaf with FBW2-level transformed operands
_CI_FMA_INFO = {"registered": 0, "enabled": 0, "calls": 0, "std_fallback": 0, "views": 0, "setup_views": 0, "no_table": 0, "small": 0}
if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):
    _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | {"_CI_FMA_TAB", "_CI_FMA_VTAB", "_CI_FMA_MTAB"}))


def _ci_fma_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb):
    """(A, B, C) of the seven products of the alternative-basis fused leaf (prepared next to the standard ones)."""
    X11, X12, X21, X22 = XQ
    Y11, Y12, Y21, Y22 = YQ
    C11, C12, C21, C22 = OQ
    return ((Lb, Y22, C12), (Lb, Rb, Mb), (X21, Y12, C21), (X11, Y11, Nb), (Lb, Rb, C22), (X22, Rb, C21), (X12, Y21, C11))


def _ci_fbw2_inner_alt(X11, X12, XS2, X22, Y11, YT2, Y21, Y22, C11, C12, C21, C22, L, R, M, N,
                       _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    # alternative-basis Winograd, 19 ops: X21 slot = S2, Y12 slot = T2 in; C12 slot = C12 - C22 out
    _subtract(X12, XS2, out=L)
    _matmul(L, Y22, out=C12)
    _subtract(X22, XS2, out=L)
    _subtract(YT2, Y11, out=R)
    _matmul(L, R, out=M)
    _subtract(C12, M, out=C12)
    _matmul(XS2, YT2, out=C21)
    _matmul(X11, Y11, out=N)
    _add(C21, N, out=C21)
    _add(M, C21, out=M)
    _add(XS2, X11, out=L)
    _subtract(Y22, YT2, out=R)
    _matmul(L, R, out=C22)
    _add(C22, M, out=C22)
    _subtract(YT2, Y21, out=R)
    _matmul(X22, R, out=C21)
    _subtract(M, C21, out=C21)
    _matmul(X12, Y21, out=C11)
    _add(C11, N, out=C11)


def _ci_fbw2_run_alt(views, rank1, colv, rowh):
    if rank1 is not None or colv is not None or rowh is not None:
        raise RuntimeError("Claude-I FMA: FBW2-level basis on an odd split")
    _ci_fbw2_inner_alt(*views)


def _ci_fma_fbw2_live(mm, rec):
    if type(mm) is _CiFbw2MM:
        return bool(_CI_FBW2_ACTIVE[0] and mm.owner._scratch_generation == mm.gen and mm.owner._colored_active)
    st = rec.get("e1w")                                     # v5: E1W, the (executor, generation) of the root's table entries
    return bool(st is not None and _CI_FBW2_ACTIVE[0] and st[0]._scratch_generation == st[1] and st[0]._colored_active)


def _ci_fma_register(layers, leaf, mm):
    rec = {"layers": layers, "on": False, "f": False, "w": False, "views": {}}
    _CI_FMA_TAB[id(layers)] = rec
    _CI_FMA_INFO["registered"] += 1
    K = len(layers)
    if K < 2 or len(leaf) != 7:
        return rec
    (Lm0, Ls0, XQk0), (Rm0, Rs0, YQk0), dec0 = layers[0]
    if Lm0 != "orig" or Rm0 != "orig" or XQk0 is None or YQk0 is None:
        return rec
    if any(layers[k][0][0] != "inplace" or layers[k][1][0] != "inplace" for k in range(1, K)):
        return rec
    vl, vr, mt = _CI_FMA_VTAB.get(id(Ls0)), _CI_FMA_VTAB.get(id(Rs0)), _CI_FMA_MTAB.get(id(dec0))
    if vl is None or vr is None or mt is None or vl[0] is not Ls0 or vr[0] is not Rs0 or mt[0] is not dec0:
        return rec
    XQL, YQL, OQL, Lb, Rb, Mb, Nb = leaf
    bx, P, h, q = (int(x) for x in Lb.shape)
    v = int(Rb.shape[-1])
    e1w = _CI_FMA_E1 and _CI_FMA_E1W_MM is not None and mm is _CI_FMA_E1W_MM
    fbw = type(mm) is _CiFbw2MM or e1w
    if _CI_FMA_ROOTS == "fbw2" and not fbw:
        return rec
    if fbw:                                                 # v4: every alternative leaf product must be in the table
        tab = _CI_E1W_TAB if e1w else mm.tab
        ents = [tab.get((id(A), id(B), id(C))) for A, B, C in _ci_fma_triples(XQL, YQL, OQL, Lb, Rb, Mb, Nb)]
        f_ok = all(e is not None for e in ents)
        if f_ok and e1w:
            rec["e1w"] = ents[0][4]
    else:
        f_ok = mm is _CI_FMA_PLAIN_MM
    if not f_ok:
        _CI_FMA_INFO["no_table"] += 1
        return rec
    w_ok = bool(fbw and "w" in _CI_FMA_LEV and not (h % 2 or q % 2 or v % 2))
    H_l, W_l = int(vl[1].shape[2 + K]), int(vl[1].shape[-1])
    H_r, W_r = int(vr[1].shape[2 + K]), int(vr[1].shape[-1])
    nbit = 2 if w_ok else 1
    if any(x % (1 << nbit) for x in (H_l, W_l, H_r, W_r)):
        return rec
    if _CI_FMA_MINF > 0:                                   # v8: estimated F saved per call
        sz = lambda a: float(math.prod(int(x) for x in a.shape))
        lrm, v0, m0 = sz(Lb) + sz(Rb) + sz(Mb), sz(vl[1]) + sz(vr[1]), sz(mt[1])
        est = (lrm - 2.0 * v0 / 7.0 - m0 / 4.0) if "f" in _CI_FMA_LEV else 0.0
        if w_ok:
            est += 1.75 * lrm - v0 / 14.0 - m0 / 16.0
        rec["est"] = est
        if est < _CI_FMA_MINF:
            _CI_FMA_INFO["small"] += 1
            return rec
    rec.update(on=True, f="f" in _CI_FMA_LEV, w=w_ok, K=K, V0L=vl[1], V0R=vr[1], M0=mt[1], nbit=nbit)
    _CI_FMA_INFO["enabled"] += 1
    return rec


def _ci_fma_split(V, K, nbit):
    """V (b, k, P, bits(K-1).., H, bits(K-1).., W) -> H and W split into (2,)*nbit + (rest,)."""
    shp = tuple(int(x) for x in V.shape)
    ha, wa = 2 + K, 2 + 2 * K          # axes of H and W in the bundle view (b, k, P, K-1 bits, H, K-1 bits, W)
    new = shp[:ha] + (2,) * nbit + (shp[ha] >> nbit,) + shp[ha + 1:wa] + (2,) * nbit + (shp[wa] >> nbit,) + shp[wa + 1:]
    return fnp.reshape(V, new), ha, wa + nbit


def _ci_fma_quads(Vs, ha, wa, j, pick, sl):
    """Quadrant views at split level j (0 = fused, 1 = FBW2) of a split view, slot bundle sl on axis 1: pick = ((rbit, cbit), ...)."""
    nd = len(Vs.shape)
    out = []
    for rb, cb in pick:
        idx = [slice(None)] * nd
        idx[1] = sl
        idx[ha + j] = rb
        idx[wa + j] = cb
        out.append(Vs[tuple(idx)])
    return tuple(out)


def _ci_fma_views(rec, levels):
    hit = rec["views"].get(levels)
    if hit is not None:
        return hit
    full = rec["views"].get("all")
    if full is None:                                        # every level of the root, once
        K, nbit = rec["K"], rec["nbit"]
        lv = []
        for V0, pick, bundles in ((rec["V0L"], ((0, 0), (1, 0), (1, 1)), ((0, 2, 1), (4, 7, 2))),
                                  (rec["V0R"], ((0, 0), (0, 1), (1, 1)), ((0, 2, 1), (4, 6, 1)))):
            if nbit == 1:                                   # v9: fused level only -> basic slices of V0's H / W halves
                ha, wa = 2 + K, 2 + 2 * K
                H2, W2 = int(V0.shape[ha]) // 2, int(V0.shape[wa]) // 2
                side = []
                for a, b, st in bundles:
                    qs = []
                    for rb, cb in pick:
                        idx = [slice(None)] * len(V0.shape)
                        idx[1] = slice(a, b, st)
                        idx[ha] = slice(rb * H2, (rb + 1) * H2)
                        idx[wa] = slice(cb * W2, (cb + 1) * W2)
                        qs.append(V0[tuple(idx)])
                    side.append((tuple(qs),))
                lv.append(tuple(side))
                continue
            Vs, ha, wa = _ci_fma_split(V0, K, nbit)         # one reshape per side; the bundles are sliced with the quadrants
            lv.append(tuple(tuple(_ci_fma_quads(Vs, ha, wa, j, pick, slice(a, b, st)) for j in range(nbit))
                            for a, b, st in bundles))
        M0 = rec["M0"]
        by, P7, h1, v1 = (int(x) for x in M0.shape)
        nb = K - 1 + nbit
        Ms = fnp.reshape(M0, (by, P7) + (2,) * nb + (h1 >> nb,) + (2,) * nb + (v1 >> nb,))
        inv = []
        for j in range(nbit):
            idx12 = [slice(None)] * len(Ms.shape); idx22 = [slice(None)] * len(Ms.shape)
            idx12[2 + K - 1 + j] = 0; idx12[2 + nb + 1 + K - 1 + j] = 1
            idx22[2 + K - 1 + j] = 1; idx22[2 + nb + 1 + K - 1 + j] = 1
            inv.append((Ms[tuple(idx12)], Ms[tuple(idx22)]))
        full = (lv[0], lv[1], tuple(inv))
        rec["views"]["all"] = full
        _CI_FMA_INFO["views"] += 1
    TL, TR, INV = full                                      # a level subset = tuples of those views (v2 order: bundle, level)
    hit = (tuple(qs[j] for qs in TL for j in levels), tuple(qs[j] for qs in TR for j in levels), tuple(INV[j] for j in levels))
    rec["views"][levels] = hit
    return hit


def _ci_fma_setup_views(layers, leaf, plan_fn):
    """v3: register a just-converted FBW2 copy-free root and make all its views now (setup), not on its first call."""
    mm = _CI_FMA_PLAIN_MM if plan_fn is _ci_cf_plan else (getattr(plan_fn, "keywords", None) or {}).get("_matmul")
    if mm is None:
        return
    rec = _CI_FMA_TAB.get(id(layers))
    if rec is None or rec["layers"] is not layers:
        rec = _ci_fma_register(layers, leaf, mm)
    if rec["on"] and not _CI_FMA_LAZYV:   # Claude-F FMA v10: register only; the views come on the first (budgeted) call
        _ci_fma_views(rec, (0, 1) if rec["w"] else (0,))
        _CI_FMA_INFO["setup_views"] += 1


def _ci_fma_try(layers, leaf, XQ, YQ, OQ, mm, _copyto=fnp.copyto, _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    rec = _CI_FMA_TAB.get(id(layers))
    if rec is None or rec["layers"] is not layers:
        rec = _ci_fma_register(layers, leaf, mm)
    if not rec["on"]:
        return False
    if not _CI_FMA_FIRST and globals().get("_CI_HUBM_P1", [False])[0]:
        _CI_FMA_INFO["std_fallback"] += 1
        return False
    lev_f = rec["f"]
    lev_w = rec["w"] and _ci_fma_fbw2_live(mm, rec)
    if not (lev_f or lev_w):
        _CI_FMA_INFO["std_fallback"] += 1
        return False
    levels = tuple(j for j, on in ((0, lev_f), (1, lev_w)) if on)
    if _CI_FMA_LAZYV and rec["views"].get("all") is None:   # Claude-F FMA v10: first-call views within the predict's request budget
        _cost = (15 if rec["nbit"] == 1 else 31) + (12 if lev_w else 0)
        if _CI_FMA_BUDGET[0] < _cost:
            _CI_FMA_INFO["budget_wait"] += 1
            return False
        _CI_FMA_BUDGET[0] -= _cost
        _CI_FMA_INFO["lazy_built"] += 1
    TL, TR, INV = _ci_fma_views(rec, levels)
    K = len(layers)
    for k in range(K):
        (Lm, Ls, XQk), (Rm, Rs, YQk), _dec = layers[k]
        if k == 0:
            X11, X12, X21, X22 = tuple(_ci_cf5_nest(q_, XQk) for q_ in XQ)
            _copyto(Ls[0], X11)
            _copyto(Ls[1], X12)
            _copyto(Ls[6], X22)
            _subtract(X11, X21, out=Ls[4])                 # S3
            for A11, A21, A22 in TL:                        # A21-quadrant <- (A21 + A22) - A11
                _add(A21, A22, out=A21)
                _subtract(A21, A11, out=A21)
            _subtract(Ls[6], Ls[4], out=Ls[2])              # S2 = X22 - S3
            _add(Ls[2], Ls[0], out=Ls[3])                   # S1 = S2 + X11
            _subtract(Ls[1], Ls[2], out=Ls[5])              # S4 = X12 - S2
            Y11, Y12, Y21, Y22 = tuple(_ci_cf5_nest(q_, YQk) for q_ in YQ)
            _copyto(Rs[0], Y11)
            _copyto(Rs[1], Y21)
            _copyto(Rs[5], Y22)
            _subtract(Y22, Y12, out=Rs[4])                 # T3
            for B11, B12, B22 in TR:                        # B12-quadrant <- B22 - (B12 - B11)
                _subtract(B12, B11, out=B12)
                _subtract(B22, B12, out=B12)
            _add(Rs[4], Rs[0], out=Rs[2])                   # T2 = T3 + Y11
            _subtract(Rs[5], Rs[2], out=Rs[3])              # T1 = Y22 - T2
            _subtract(Rs[1], Rs[2], out=Rs[6])              # T4 = Y21 - T2
            continue
        if _CI_REQ_CF_L:
            req_pair = _c2_req_cf_get(XQk, Ls)
            if req_pair is not None:
                req_lhs, req_rhs, req_dst = req_pair
                _add(Ls[3], Ls[4], out=Ls[2])
                _subtract(req_lhs, req_rhs, out=req_dst)
                _subtract(Ls[1], Ls[5], out=Ls[3])
            else:
                _subtract(Ls[0], Ls[3], out=Ls[6])
                _add(Ls[3], Ls[4], out=Ls[2])
                _subtract(Ls[2], Ls[0], out=Ls[5])
                _subtract(Ls[1], Ls[5], out=Ls[3])
        else:
            _subtract(Ls[0], Ls[3], out=Ls[6])
            _add(Ls[3], Ls[4], out=Ls[2])
            _subtract(Ls[2], Ls[0], out=Ls[5])
            _subtract(Ls[1], Ls[5], out=Ls[3])
        _subtract(Rs[3], Rs[2], out=Rs[6])
        _subtract(Rs[2], Rs[0], out=Rs[2])
        _subtract(Rs[3], Rs[2], out=Rs[5])
        _subtract(Rs[1], Rs[5], out=Rs[4])
    XQL, YQL, OQL, Lb, Rb, Mb, Nb = leaf
    X11, X12, X21, X22 = XQL
    Y11, Y12, Y21, Y22 = YQL
    C11, C12, C21, C22 = OQL
    _CI_FMA_W[0] = lev_w
    try:
        if lev_f:                                           # fused leaf in the alternative basis, 19 ops
            _subtract(X12, X21, out=Lb)                     # S4 (X21 slot = S2)
            mm(Lb, Y22, out=C12)                            # P3
            _subtract(X22, X21, out=Lb)                     # S3
            _subtract(Y12, Y11, out=Rb)                     # T3 (Y12 slot = T2)
            mm(Lb, Rb, out=Mb)                              # P7
            _subtract(C12, Mb, out=C12)                     # D2 = P3 - P7
            mm(X21, Y12, out=C21)                           # P6
            mm(X11, Y11, out=Nb)                            # P1
            _add(C21, Nb, out=C21)                          # U2
            _add(Mb, C21, out=Mb)                           # U3
            _add(X21, X11, out=Lb)                          # S1
            _subtract(Y22, Y12, out=Rb)                     # T1
            mm(Lb, Rb, out=C22)                             # P5
            _add(C22, Mb, out=C22)                          # C22 = U3 + P5
            _subtract(Y12, Y21, out=Rb)                     # T4
            mm(X22, Rb, out=C21)                            # P4
            _subtract(Mb, C21, out=C21)                     # C21 = U3 - P4
            mm(X12, Y21, out=C11)                           # P2
            _add(C11, Nb, out=C11)                          # C11 = P1 + P2
        else:                                               # the parent's standard fused leaf (22 ops)
            _add(X21, X22, out=Lb)
            _subtract(Y12, Y11, out=Rb)
            mm(Lb, Rb, out=C22)
            _subtract(Lb, X11, out=Lb)
            _subtract(Y22, Rb, out=Rb)
            mm(Lb, Rb, out=C12)
            _subtract(X12, Lb, out=Lb)
            mm(Lb, Y22, out=C21)
            _subtract(Rb, Y21, out=Rb)
            mm(X22, Rb, out=C11)
            _subtract(X11, X21, out=Lb)
            _subtract(Y22, Y12, out=Rb)
            mm(Lb, Rb, out=Mb)
            mm(X11, Y11, out=Nb)
            _add(C12, Nb, out=C12)
            _add(Mb, C12, out=Mb)
            _add(C12, C22, out=C12)
            _add(C12, C21, out=C12)
            _subtract(Mb, C11, out=C21)
            _add(Mb, C22, out=C22)
            mm(X12, Y21, out=C11)
            _add(C11, Nb, out=C11)
    finally:
        _CI_FMA_W[0] = False
    for k in range(K - 1, 0, -1):
        _cb_decode5_cached(layers[k][2])
    for C12v, C22v in INV:                                  # D basis -> standard: C12 = D2 + C22, all seven products
        _add(C12v, C22v, out=C12v)
    _cb_decode7_root(layers[0][2], OQ)
    _CI_FMA_INFO["calls"] += 1
    return True
# ===================== end Claude-I FMA v9 =====================

# ======================= Claude-F FMA v10: no FMA requests at setup (lazy, budgeted views), 2026-10-20 =======================
_CI_FMA_LAZYV = _os.environ.get("CI_FMA_LAZYV", "1") != "0"
_CI_FMA_BREQ = int(_os.environ.get("CI_FMA_BREQ", "300"))
_CI_FMA_BUDGET = [0]
_CI_FMA_INFO.update(fp1_pop=0, lazy_built=0, budget_wait=0)


def _ci_fma_fp1_pop(tab, XQ, YQ, OQ, Lb, Rb, Mb, Nb):
    """Pop the alternative-only leaf products (keys not among the standard triples) from the FP1 prewarm table."""
    lazy_tab = globals().get("_CI_FP1_LAZY_TAB")
    if lazy_tab is None:
        return
    std = {(id(A), id(B), id(C)) for A, B, C in _ci_fbw2_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb)}
    for A, B, C in _ci_fma_triples(XQ, YQ, OQ, Lb, Rb, Mb, Nb):
        k3 = (id(A), id(B), id(C))
        ent = tab.get(k3)
        if k3 not in std and ent is not None and lazy_tab.pop(id(ent[3]), None) is not None:
            _CI_FMA_INFO["fp1_pop"] += 1


_ci_fma_predict_parent = Estimator.predict


def _ci_fma_predict(self, mlp, budget):
    _CI_FMA_BUDGET[0] = _CI_FMA_BREQ   # Claude-F FMA v10: a fresh view-request budget for every predict
    return _ci_fma_predict_parent(self, mlp, budget)


Estimator.predict = _ci_fma_predict
# ===================== end Claude-F FMA v10 =====================



# ===================== Claude-P gkport v3 (10/20): Codex D gk transport gate (fragment.py f9ff3a9b) on valid-row inputs, default ON =====================
# D research: exact partial derivative of the current card mean, cumulants/var fixed.
# One switch; support masks, mean/head coefficients, w2, engines are unchanged.
# v3: in production frames the C3 P1/P2 plans reuse the bank rows of a4/i5/a5/i6 for PK1 before this hook, so the gate takes only
# a2, phi, i3, i4 (rows that stay valid) and builds a4 and sigma^-7 itself.
_GK_GATE = _os.environ.get("ARC_GK_GATE", "1") == "1"

def _gk_transport_gate(q, wick, d3, k4, a2, phi, i3, i4):
    # m=W0+d3/6 W3+k4/24 W4+d3^2/72 W6+d3*k4/144 W7.
    # d_mu Wk = W(k+1). All but W8 already exist in this layer's paid wick table.
    gate = q + (d3 * (1.0 / 6.0)) * wick[:, 12]
    gate = gate + (k4 * (1.0 / 24.0)) * wick[:, 16]
    gate = gate + ((d3 * d3) * (1.0 / 72.0)) * wick[:, 20]
    a4 = a2 * a2
    he6 = a4 * a2 - 15.0 * a4 + 45.0 * a2 - 15.0
    w8 = (he6 * phi) * (i4 * i3)
    gate = gate + ((d3 * k4) * (1.0 / 144.0)) * w8
    return gate
# ===================== end Claude-P gkport v3 =====================


_CI_HERM2 = _os.environ.get("CI_HERM2", "1") != "0"   # Claude-I HERM v2 (2026-10-19): q/p/h He3..He6 from the G recurrence


_CI_C0SYM = _os.environ.get("CI_C0SYM", "1") != "0"   # Claude-I C0SYM: layer-0 C_pre via the symmetric block product


# ===================== Claude-F T78 production v1: L7-8 transport rows 960 (2026-10-20) =====================
_CI_T78 = _os.environ.get("CI_T78", "0") == "1"
if _CI_T78:
    # T78 relies on the shipped CDIAG completion of C_pre[mi:, mi:] (mirror + diagonal), as M896 does.
    if not _CI_CDG:
        raise ValueError("CI_T78=1 requires CI_CDG enabled")
    if (_CB_PRUNE_M[7:9] != (1024, 1024) or _CB_PRUNE_K[7:9] != (896, 896)
            or _CB_PRUNE_S_OUT[7:9] != (992, 992)):
        raise RuntimeError("T78 parent transport geometry changed")
    _CI_T78_M = _CB_PRUNE_M[:7] + (960, 960) + _CB_PRUNE_M[9:]
    _CB_PRUNE_S_OUT = _CB_PRUNE_S_OUT[:7] + (960, 960) + _CB_PRUNE_S_OUT[9:]
    _CI_T78_WIDTHS = (8512, 8384)
    if tuple(row[3] for row in _BD_BUNDLE_SPECS if 7 <= row[0] <= 8) != _CI_T78_WIDTHS:
        raise RuntimeError("T78 BD packet widths changed")
    _CI_T78_ROOT_MAP = {("mm", (1, 1, 1024, 896), (1, 1, 896, _p), 6): ("mm", (1, 1, 960, 896), (1, 1, 896, _p), 6)
                        for _p in _CI_T78_WIDTHS}
    _CI_T78_CHILD_MAP = {("mm", (1, 48, 256, 224), (1, 48, 224, _p // 4), 4): ("mm", (1, 48, 240, 224), (1, 48, 224, _p // 4), 4)
                         for _p in _CI_T78_WIDTHS}
    _CI_T78_PLAN_MAP = dict(_CI_T78_ROOT_MAP)
    _CI_T78_PLAN_MAP.update(_CI_T78_CHILD_MAP)
    for _ci_t78_inventory in (_STAGE1_CALLPLAN_ROOTS, _CF_PRUNE_FULL):
        if any(_ci_t78_inventory.count(key) != 1 for key in _CI_T78_PLAN_MAP):
            raise RuntimeError("T78 expects exactly two transport roots and their children")
    if any(_CB_R48_ROOTS.count(key) != 1 for key in _CI_T78_ROOT_MAP):
        raise RuntimeError("T78 R48 root inventory changed")

    def _ci_t78_remap(seq):
        """map old keys to new ones; a new key that is already present is not added twice."""
        out = []
        for key in seq:
            key = _CI_T78_PLAN_MAP.get(key, key)
            if key not in out:
                out.append(key)
        return tuple(out)

    _STAGE1_CALLPLAN_ROOTS = _ci_t78_remap(_STAGE1_CALLPLAN_ROOTS)
    _CF_PRUNE_FULL = _ci_t78_remap(_CF_PRUNE_FULL)
    _CB_R48_ROOTS = _ci_t78_remap(_CB_R48_ROOTS)
    _CI_R48VP_HEAVY = frozenset(_CI_T78_ROOT_MAP.get(key, key) for key in _CI_R48VP_HEAVY)
    _CI_R48VP_MID = frozenset(_CI_T78_ROOT_MAP.get(key, key) for key in _CI_R48VP_MID)
    if globals().get("_CI_FBW2_KEYS") is not None:
        _CI_FBW2_KEYS = frozenset(_CI_T78_PLAN_MAP.get(key, key) for key in _CI_FBW2_KEYS)
    if globals().get("_CF_FBW3FIRST_KEYS") is not None:
        _CF_FBW3FIRST_KEYS = frozenset(_CI_T78_PLAN_MAP.get(key, key) for key in _CF_FBW3FIRST_KEYS)
    # the 960-row transport roots are prepared now; the root-bundle wide-source fallback keeps its old key + a 960 sibling
    _CI_T78_FALLBACK_OLD = ("mm", (1, 1, 1024, 896), (1, 1, 896, 8640), 6)
    _CI_T78_FALLBACK = ("mm", (1, 1, 960, 896), (1, 1, 896, 8640), 6)
    _CF_LAZY_ROOTS = (frozenset(_CF_LAZY_ROOTS) - frozenset(_CI_T78_ROOT_MAP.values())) | frozenset((_CI_T78_FALLBACK,))

    def _ci_t78_prepare_child_views(owner):
        """Reuse owned parent backings; bind the changed R48 child crops in setup (fails closed on any growth)."""
        generation = owner._scratch_generation
        required = set()
        for _kind, xs, ys, level in _CI_T78_ROOT_MAP.values():
            required.update(_cc_r48_20_geometry(xs[-2], xs[-1], ys[-1], level))
        for role, P, shape, paired in sorted(required):
            entry = owner.pool.get((role, P))
            if entry is None or entry[0].size < math.prod(shape):
                raise RuntimeError("T78 R48 child exceeds parent backing")
            _cc_r48_20_alias(owner, role, P, shape, paired)
        for _kind, xs, ys, level in (_CI_T78_FALLBACK,):
            for role, P, shape, paired in _be1_geometry(xs[-2], xs[-1], ys[-1], level):
                entry = owner.pool.get((role, P))
                if entry is None or entry[0].size < math.prod(shape):
                    raise RuntimeError("T78 fallback exceeds parent backing")
        if owner._scratch_generation != generation or not owner._colored_active:
            raise RuntimeError("T78 setup changed parent scratch ownership")
    del _ci_t78_inventory
# ===================== end Claude-F T78 production v1 =====================


# ======================= Claude-H REQOP v3: cached old-tier read views (2026-10-20) =======================
_CF_REQOP = _os.environ.get("CF_REQOP", "1") != "0"
def _cf_rq_cached(v, tag, make):
    ent = _cf_vc_entry(v)
    if ent is None:
        return make(v)
    k_ = ("RQ", tag)
    r_ = ent[2].get(k_)
    if r_ is None:
        r_ = ent[2][k_] = make(v)
    return r_


def _cf_rq_sw(v):
    return _cf_rq_cached(v, "sw", lambda a: fnp.swapaxes(a, -1, -2))


def _cf_rq_tr(v):
    return _cf_rq_cached(v, "tr", lambda a: fnp.transpose(a, (0, 2, 1)))
# ===================== end Claude-H REQOP v3 =====================


# ======================= crypto-03 FMAODD v4 (2026-10-20): side-masked FBW2-level alternative basis on odd leaves + FMAF3 =======================
# Design docs/FMAODD-DESIGN-20261020.md (builder experiments/crypto03_fmaodd_20261020/make_fmaodd_v4.py).  Default OFF.
_C3_FMAODD = _os.environ.get("CI_FMAODD", "1") == "1"
_C3_FMAF3 = _os.environ.get("CI_FMAF3", "1") == "1"
_C3_FMAODD_MINW = float(_os.environ.get("CI_FMAODD_MINW_MF", "10")) * 1e6   # least odd FBW2-level saving per root call (elements)
_CI_FMA_WMASK = [0]          # FBW2-level side mask of the root now running (L=1, R=2, C=4); 0 = not set by _c3_fma_try (v9 original)
_C3_TVIEW_TAB = {}           # id(FBW2 L temporary) -> (temporary, (.., h2, q-qe) slice, width): the rank-1 D-basis temporary


def _c3_first_predict():
    return bool(_CF_DL_ON and _CF_DL_FIRST[0] and _CF_DL_FIRST_LEFT[0] == _CF_DL_FIRST_N)   # = the _CfF3MM plain-product condition


def _c3_fbw2_like(mm):
    return isinstance(mm, _CiFbw2MM) if _C3_FMAF3 else type(mm) is _CiFbw2MM


def _c3_fma_fbw2_live(mm, rec):   # = v9 _ci_fma_fbw2_live with _c3_fbw2_like
    if _c3_fbw2_like(mm):
        return bool(_CI_FBW2_ACTIVE[0] and mm.owner._scratch_generation == mm.gen and mm.owner._colored_active)
    st = rec.get("e1w")
    return bool(st is not None and _CI_FBW2_ACTIVE[0] and st[0]._scratch_generation == st[1] and st[0]._colored_active)


def _c3_fma_register(layers, leaf, mm):   # = v9 _ci_fma_register + c3 lines
    rec = {"layers": layers, "on": False, "f": False, "w": False, "views": {}}
    _CI_FMA_TAB[id(layers)] = rec
    _CI_FMA_INFO["registered"] += 1
    K = len(layers)
    if K < 2 or len(leaf) != 7:
        return rec
    (Lm0, Ls0, XQk0), (Rm0, Rs0, YQk0), dec0 = layers[0]
    if Lm0 != "orig" or Rm0 != "orig" or XQk0 is None or YQk0 is None:
        return rec
    if any(layers[k][0][0] != "inplace" or layers[k][1][0] != "inplace" for k in range(1, K)):
        return rec
    vl, vr, mt = _CI_FMA_VTAB.get(id(Ls0)), _CI_FMA_VTAB.get(id(Rs0)), _CI_FMA_MTAB.get(id(dec0))
    if vl is None or vr is None or mt is None or vl[0] is not Ls0 or vr[0] is not Rs0 or mt[0] is not dec0:
        return rec
    XQL, YQL, OQL, Lb, Rb, Mb, Nb = leaf
    bx, P, h, q = (int(x) for x in Lb.shape)
    v = int(Rb.shape[-1])
    e1w = _CI_FMA_E1 and _CI_FMA_E1W_MM is not None and mm is _CI_FMA_E1W_MM
    fbw = _c3_fbw2_like(mm) or e1w                     # c3 FMAF3: isinstance (the _CfF3MM transport keys)
    if _CI_FMA_ROOTS == "fbw2" and not fbw:
        return rec
    if fbw:                                                 # v4: every alternative leaf product must be in the table
        tab = _CI_E1W_TAB if e1w else mm.tab
        ents = [tab.get((id(A), id(B), id(C))) for A, B, C in _ci_fma_triples(XQL, YQL, OQL, Lb, Rb, Mb, Nb)]
        f_ok = all(e is not None for e in ents)
        if f_ok and e1w:
            rec["e1w"] = ents[0][4]
    else:
        f_ok = mm is _CI_FMA_PLAIN_MM
    if not f_ok:
        _CI_FMA_INFO["no_table"] += 1
        return rec
    w_ok = bool(fbw and "w" in _CI_FMA_LEV and not (h % 2 or q % 2 or v % 2))
    w_odd = bool(_C3_FMAODD and fbw and "w" in _CI_FMA_LEV and not w_ok and min(h, q, v) >= 2)   # c3 FMAODD
    wmask = (4 | (1 if v % 2 == 0 else 0) | (2 if h % 2 == 0 else 0)) if w_odd else 7
    H_l, W_l = int(vl[1].shape[2 + K]), int(vl[1].shape[-1])
    H_r, W_r = int(vr[1].shape[2 + K]), int(vr[1].shape[-1])
    nbit = 2 if w_ok else 1
    if any(x % (1 << nbit) for x in (H_l, W_l, H_r, W_r)):
        return rec
    if _CI_FMA_MINF > 0:                                   # v8: estimated F saved per call
        sz = lambda a: float(math.prod(int(x) for x in a.shape))
        lrm, v0, m0 = sz(Lb) + sz(Rb) + sz(Mb), sz(vl[1]) + sz(vr[1]), sz(mt[1])
        est = (lrm - 2.0 * v0 / 7.0 - m0 / 4.0) if "f" in _CI_FMA_LEV else 0.0
        if w_ok:
            est += 1.75 * lrm - v0 / 14.0 - m0 / 16.0
        if w_odd:                                          # c3: the masked FBW2 level on the even part
            he_, qe_, ve_ = h - h % 2, q - q % 2, v - v % 2
            eo = 0.0
            if wmask & 1:
                eo += (he_ * qe_) / (h * q) * (1.75 * sz(Lb) - sz(vl[1]) / 14.0)
            if wmask & 2:
                eo += (qe_ * ve_) / (q * v) * (1.75 * sz(Rb) - sz(vr[1]) / 14.0)
            if wmask & 4:
                eo += (he_ * ve_) / (h * v) * (1.75 * sz(Mb) - m0 / 16.0) - (7.0 * bx * P * (he_ // 2) if q % 2 else 0.0)
            rec['est_v9'] = est                         # c3: the v9 estimate (first-predict refusal)
            if eo < _C3_FMAODD_MINW:
                w_odd, wmask = False, 7
                _CI_FMA_INFO['c3_odd_small'] += 1
            else:
                est += eo
                rec['est_odd'] = eo
        rec["est"] = est
        if est < _CI_FMA_MINF:
            _CI_FMA_INFO["small"] += 1
            return rec
    rec.update(on=True, f="f" in _CI_FMA_LEV, w=(w_ok or w_odd), K=K, V0L=vl[1], V0R=vr[1], M0=mt[1], nbit=nbit,
               wmask=wmask, wodd=w_odd)                    # c3
    if w_odd:
        _CI_FMA_INFO['c3_odd_on'] += 1
    _CI_FMA_INFO["enabled"] += 1
    return rec



def _c3_odd1_cost(rec):
    m = rec["wmask"]
    return (7 if m & 1 else 0) + (7 if m & 2 else 0) + (3 if m & 4 else 0)   # one reshape + six slices per side, M0 reshape + 2 slices


def _c3_odd1_views(rec):
    """FBW2-level (level 1) views of an odd-leaf root: per active side, the even part's quadrants of every fused block."""
    K, m = rec["K"], rec["wmask"]
    ha, wa = 2 + K, 2 + 2 * K
    sides = []
    for V0, pick, bundles, on in ((rec["V0L"], ((0, 0), (1, 0), (1, 1)), ((0, 2, 1), (4, 7, 2)), m & 1),
                                  (rec["V0R"], ((0, 0), (0, 1), (1, 1)), ((0, 2, 1), (4, 6, 1)), m & 2)):
        if not on:
            sides.append(tuple(() for _ in bundles))
            continue
        shp = tuple(int(x) for x in V0.shape)
        H2, W2 = shp[ha] // 2, shp[wa] // 2                # the leaf rows / columns of this side (fused halves are exact)
        Vs = fnp.reshape(V0, shp[:ha] + (2, H2) + shp[ha + 1:wa] + (2, W2) + shp[wa + 1:])
        eh, ew = H2 // 2, W2 // 2                          # half of the even part (the peeled row / column stays out)
        side = []
        for a, b, st in bundles:
            qs = []
            for rb, cb in pick:
                idx = [slice(None)] * (len(shp) + 2)
                idx[1] = slice(a, b, st)
                idx[ha + 1] = slice(rb * eh, (rb + 1) * eh)
                idx[wa + 2] = slice(cb * ew, (cb + 1) * ew)
                qs.append(Vs[tuple(idx)])
            side.append(tuple(qs))
        sides.append(tuple(side))
    inv = None
    if m & 4:
        M0 = rec["M0"]
        by, P7, h1, v1 = (int(x) for x in M0.shape)
        Ms = fnp.reshape(M0, (by, P7) + (2,) * K + (h1 >> K,) + (2,) * K + (v1 >> K,))
        eh, ev = (h1 >> K) // 2, (v1 >> K) // 2
        ra, ca = 2 + K, 3 + 2 * K
        j12 = [slice(None)] * len(Ms.shape)
        j22 = [slice(None)] * len(Ms.shape)
        j12[ra], j12[ca] = slice(0, eh), slice(ev, 2 * ev)
        j22[ra], j22[ca] = slice(eh, 2 * eh), slice(ev, 2 * ev)
        inv = (Ms[tuple(j12)], Ms[tuple(j22)])
    _CI_FMA_INFO["c3_odd_views"] += 1
    return (sides[0], sides[1], inv)


def _c3_fma_views(rec, levels):
    if not rec.get("wodd") or 1 not in levels:
        return _c3_fma_views_parent(rec, levels)          # v9 (an odd root's fused level = the v9 nbit-1 views)
    odd = rec["views"].get("odd1")
    if odd is None:                                       # only a setup prebuild can get here (the steady call builds odd1 first)
        return _c3_fma_views_parent(rec, (0,))
    key = ("c3", levels)
    hit = rec["views"].get(key)
    if hit is not None:
        return hit
    TL0, TR0, INV0 = _c3_fma_views_parent(rec, (0,)) if 0 in levels else ((), (), ())
    OL, OR, OI = odd
    nb = len(TL0) if 0 in levels else 0
    TL, TR = [], []
    for i in range(2):                                    # v9 order: bundle-major, level-minor
        if 0 in levels:
            TL.append(TL0[i]); TR.append(TR0[i])
        if OL[i]:
            TL.append(OL[i])
        if OR[i]:
            TR.append(OR[i])
    INV = tuple(INV0) + ((OI,) if OI is not None else ())
    hit = (tuple(TL), tuple(TR), INV)
    rec["views"][key] = hit
    return hit


def _c3_fma_try(layers, leaf, XQ, YQ, OQ, mm, *args, **kwargs):
    first = _c3_first_predict()
    if _C3_FMAF3 and first and type(mm) is _CfF3MM:
        _CI_FMA_INFO["c3_f3_first"] += 1
        return False                                      # first predict after a setup: the F3 keys keep their plain products
    rec = _CI_FMA_TAB.get(id(layers))
    if rec is None or rec["layers"] is not layers:
        rec = _ci_fma_register(layers, leaf, mm)
    if not rec.get("wodd"):
        return _c3_fma_try_parent(layers, leaf, XQ, YQ, OQ, mm, *args, **kwargs)
    use_w = not first and rec["views"].get("all") is not None
    if first:
        _CI_FMA_INFO["c3_odd_first"] += 1
        if rec.get("est_v9", rec.get("est", 0.0)) < _CI_FMA_MINF:
            return False                                  # v9 would have refused this root ('small'): first predict = parent
    if use_w and rec["views"].get("odd1") is None:
        cost = _c3_odd1_cost(rec)
        if _CI_FMA_LAZYV and _CI_FMA_BUDGET[0] < cost:
            use_w = False
            _CI_FMA_INFO["budget_wait"] += 1
        else:
            if _CI_FMA_LAZYV:
                _CI_FMA_BUDGET[0] -= cost
            rec["views"]["odd1"] = _c3_odd1_views(rec)
    if not use_w:                                         # the v9 fused-level path (first predict / views not ready)
        rec["w"] = False
        try:
            return _c3_fma_try_parent(layers, leaf, XQ, YQ, OQ, mm, *args, **kwargs)
        finally:
            rec["w"] = True
    _CI_FMA_WMASK[0] = rec["wmask"]
    try:
        return _c3_fma_try_parent(layers, leaf, XQ, YQ, OQ, mm, *args, **kwargs)
    finally:
        _CI_FMA_WMASK[0] = 0


def _c3_fbw2_inner_m6(X11, X12, X21, X22, Y11, YT2, Y21, Y22, C11, C12, C21, C22, L, R, M, N,
                      _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    # R|C (20 ops): L standard, Y12 slot = T2, C12 slot out = C12 - C22
    _add(X21, X22, out=L)                                 # S1
    _subtract(Y22, YT2, out=R)                            # T1 = Y22 - T2
    _matmul(L, R, out=C22)                                # P5
    _subtract(L, X11, out=L)                              # S2
    _matmul(L, YT2, out=C21)                              # P6
    _subtract(X12, L, out=L)                              # S4
    _matmul(L, Y22, out=C12)                              # P3
    _subtract(X11, X21, out=L)                            # S3
    _subtract(YT2, Y11, out=R)                            # T3 = T2 - Y11
    _matmul(L, R, out=M)                                  # P7
    _subtract(C12, M, out=C12)                            # D2 = P3 - P7
    _matmul(X11, Y11, out=N)                              # P1
    _add(C21, N, out=C21)                                 # U2
    _add(M, C21, out=M)                                   # U3
    _add(C22, M, out=C22)                                 # C22 = U3 + P5
    _subtract(YT2, Y21, out=R)                            # T4 = T2 - Y21
    _matmul(X22, R, out=C21)                              # P4
    _subtract(M, C21, out=C21)                            # C21 = U3 - P4
    _matmul(X12, Y21, out=C11)                            # P2
    _add(C11, N, out=C11)                                 # C11 = P1 + P2


def _c3_fbw2_inner_m5(X11, X12, XS2, X22, Y11, Y12, Y21, Y22, C11, C12, C21, C22, L, R, M, N,
                      _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    # L|C (20 ops): X21 slot = S2, R standard, C12 slot out = C12 - C22
    _add(XS2, X11, out=L)                                 # S1 = S2 + X11
    _subtract(Y12, Y11, out=R)                            # T1
    _matmul(L, R, out=C22)                                # P5
    _subtract(Y22, R, out=R)                              # T2
    _matmul(XS2, R, out=C21)                              # P6
    _subtract(R, Y21, out=R)                              # T4
    _matmul(X22, R, out=C11)                              # P4 (C11 as temporary)
    _subtract(X12, XS2, out=L)                            # S4
    _matmul(L, Y22, out=C12)                              # P3
    _subtract(X22, XS2, out=L)                            # S3
    _subtract(Y22, Y12, out=R)                            # T3
    _matmul(L, R, out=M)                                  # P7
    _subtract(C12, M, out=C12)                            # D2
    _matmul(X11, Y11, out=N)                              # P1
    _add(C21, N, out=C21)                                 # U2
    _add(M, C21, out=M)                                   # U3
    _add(C22, M, out=C22)                                 # C22
    _subtract(M, C11, out=C21)                            # C21 = U3 - P4
    _matmul(X12, Y21, out=C11)                            # P2
    _add(C11, N, out=C11)                                 # C11


def _c3_fbw2_inner_m4(X11, X12, X21, X22, Y11, Y12, Y21, Y22, C11, C12, C21, C22, L, R, M, N,
                      _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    # C only (21 ops): both sides standard, C12 slot out = C12 - C22
    _add(X21, X22, out=L)                                 # S1
    _subtract(Y12, Y11, out=R)                            # T1
    _matmul(L, R, out=C22)                                # P5
    _subtract(L, X11, out=L)                              # S2
    _subtract(Y22, R, out=R)                              # T2
    _matmul(L, R, out=C21)                                # P6
    _subtract(X12, L, out=L)                              # S4
    _matmul(L, Y22, out=C12)                              # P3
    _subtract(R, Y21, out=R)                              # T4
    _matmul(X22, R, out=C11)                              # P4 (C11 as temporary)
    _subtract(X11, X21, out=L)                            # S3
    _subtract(Y22, Y12, out=R)                            # T3
    _matmul(L, R, out=M)                                  # P7
    _subtract(C12, M, out=C12)                            # D2
    _matmul(X11, Y11, out=N)                              # P1
    _add(C21, N, out=C21)                                 # U2
    _add(M, C21, out=M)                                   # U3
    _add(C22, M, out=C22)                                 # C22
    _subtract(M, C11, out=C21)                            # C21 = U3 - P4
    _matmul(X12, Y21, out=C11)                            # P2
    _add(C11, N, out=C11)                                 # C11


_C3_INNER = {6: _c3_fbw2_inner_m6, 5: _c3_fbw2_inner_m5, 4: _c3_fbw2_inner_m4}


def _c3_tview(Lt, a1):
    w = int(a1.shape[-1])
    hit = _C3_TVIEW_TAB.get(id(Lt))
    if hit is None or hit[0] is not Lt or hit[2] != w:
        hit = (Lt, Lt[..., :, :w], w)
        _C3_TVIEW_TAB[id(Lt)] = hit
    return hit[1]


def _c3_fbw2_run_alt(views, rank1, colv, rowh, _add=fnp.add, _subtract=fnp.subtract, _matmul=fnp.matmul):
    m = _CI_FMA_WMASK[0]
    if m == 0 or (m == 7 and rank1 is None and colv is None and rowh is None):
        return _c3_fbw2_run_alt_parent(views, rank1, colv, rowh)   # v9 even leaves (m 0: no c3 root -> v9 raises on an odd split)
    if m not in (4, 5, 6, 7) or (m & 1 and colv is not None) or (m & 2 and rowh is not None):
        raise RuntimeError("crypto-03 FMAODD: side mask %d on an incompatible peel" % m)
    _CI_FMA_INFO["c3_odd_calls"] += 1
    (_ci_fbw2_inner_alt if m == 7 else _C3_INNER[m])(*views)
    if rank1 is not None:                                 # q odd: C_even += A[:, qe:] @ B[qe:, :], C12 slot in the D basis
        (a1, b1, c11), (_a1, b2, c12), (a2, _b1, c21), (_a2, _b2, c22) = rank1
        M = views[14]
        _matmul(a1, b1, out=M)
        _add(c11, M, out=c11)
        _matmul(a2, b1, out=M)
        _add(c21, M, out=c21)
        _matmul(a2, b2, out=M)
        _add(c22, M, out=c22)
        t = _c3_tview(views[12], a1)
        _subtract(a1, a2, out=t)                          # (a1 - a2) b2 = the C12 - C22 share of the rank-1 term
        _matmul(t, b2, out=M)
        _add(c12, M, out=c12)
    if colv is not None:                                  # v odd: only with L standard
        _matmul(colv[0], colv[1], out=colv[2])
    if rowh is not None:                                  # h odd: only with R standard
        _matmul(rowh[0], rowh[1], out=rowh[2])


if _C3_FMAODD or _C3_FMAF3:
    _CI_FMA_INFO.update(c3_odd_on=0, c3_odd_small=0, c3_odd_calls=0, c3_odd_views=0, c3_odd_first=0, c3_f3_first=0)
    _CI_FMA_INFO.setdefault("budget_wait", 0)
    if isinstance(globals().get("_CF_GUARD_TABLES"), tuple):   # every setup / restore clears it (old arenas must not stay alive)
        _CF_GUARD_TABLES = tuple(sorted(set(_CF_GUARD_TABLES) | {"_C3_TVIEW_TAB"}))
    _ci_fma_fbw2_live = _c3_fma_fbw2_live
    _ci_fma_register = _c3_fma_register
    _c3_fma_try_parent = _ci_fma_try
    _ci_fma_try = _c3_fma_try
    _c3_fma_views_parent = _ci_fma_views
    _ci_fma_views = _c3_fma_views
if _C3_FMAODD:
    _c3_fbw2_run_alt_parent = _ci_fbw2_run_alt
    _ci_fbw2_run_alt = _c3_fbw2_run_alt
# ===================== end crypto-03 FMAODD v4 =====================


