_CI_CFD_INFO = {"deferred": 0, "bound": 0, "stale": 0, "keys": []}
_CI_CFD_ARM = [None]          # the BD owner whose prepare_callplans is running (setup only)


class _CiCfdRec:
    """One deferred root: who owns the slot (weakref, no strong owner edge, no cycle), its key, generation and view epoch."""
    __slots__ = ("ref", "key", "gen", "epoch", "kind")

    def __init__(self, holder, key, gen, kind):
        self.ref = _cf_vc_weakref.ref(holder)
        self.key, self.gen, self.epoch, self.kind = key, gen, _CF_VIEW_EPOCH[0], kind


def _ci_cfd_run(layers, leaf, XQ, YQ, OQ):
    """Plan function of a deferred root: bind now (this key's setup sequence), then run the real plan."""
    rec = layers[0]
    plan = _ci_cfd_bind_owner(rec) if rec.kind == "owner" else _ci_cfd_bind_e1(rec)
    return plan[0](plan[1], plan[2], XQ, YQ, OQ)


class _CiCfdWindow:
    """Setup-like view batching for one first-dispatch bind: _CF_KEEP (one free round trip), split / unstack (_CP_IN_SETUP)
    and no new CF-L pair (_c2_req_cf_open False on the executor).  _CF_KEEP is empty outside setup, so clearing it at the
    end drops only this bind's intermediates."""
    __slots__ = ("ex", "keep", "split", "opened")

    def __init__(self, ex):
        self.ex = ex

    def __enter__(self):
        self.keep, self.split = _CF_KEEP_ON[0], _CP_IN_SETUP[0]
        self.opened = getattr(self.ex, "_c2_req_cf_open", None)
        _CF_KEEP_ON[0] = True
        if _CI_CFD_SPLIT:
            _CP_IN_SETUP[0] = True
        if self.opened is not None:
            self.ex._c2_req_cf_open = False
        return self

    def __exit__(self, *exc):
        _CF_KEEP_ON[0], _CP_IN_SETUP[0] = self.keep, self.split
        if self.opened is not None:
            self.ex._c2_req_cf_open = self.opened
        if not self.keep:
            del _CF_KEEP[:]
        return False


def _ci_cfd_bind_owner(rec):
    owner = rec.ref()
    key = rec.key
    cur = owner._callplans.get(key) if owner is not None else None
    if (owner is None or not owner._colored_active or owner._scratch_generation != rec.gen
            or _CF_VIEW_EPOCH[0] != rec.epoch or cur is None or cur[0] is not _ci_cfd_run or cur[1][0] is not rec):
        _CI_CFD_INFO["stale"] += 1
        raise RuntimeError("Claude-I CFD: deferred root is stale: %r" % (key,))
    gen = owner._scratch_generation
    with _CiCfdWindow(owner):
        plan = (_ci_cfd_bind_parent(owner, key[1], key[2], key[3], key)
                or owner._bind_callplan(*key))                     # prepare_callplans' binding line, this key only
        owner._callplans[key] = plan
        if _CS_DFS2:
            _cs_dfs2_convert(owner, (key,))                         # DFS-2 wrapper of prepare_callplans
        if _CI_FBW2:
            _ci_fbw2_convert(owner, (key,))                         # FBW2 wrapper: same filters, same free arenas
        plan = owner._callplans[key]
        if _CI_FMA and _CI_FMA_SETUPV and _CI_FMA_ROOTS == "all" and plan[0] is _ci_cf_plan:
            _ci_fma_setup_views(plan[1], plan[2], plan[0])          # FMA v4 registration (LAZYV: no request)
        if key[1][1] in _CB_R48_CHILD_P:
            _ci_cf5n_build(owner)                                   # nested child inputs (idempotent)
    if owner._scratch_generation != gen or not owner._colored_active:
        raise RuntimeError("Claude-I CFD: deferred bind grew scratch")
    _CI_CFD_INFO["bound"] += 1
    return owner._callplans[key]


def _ci_cfd_bind_e1(rec):
    bank = rec.ref()
    key = rec.key
    cur = bank.plain.get(key) if bank is not None else None
    if (bank is None or cur is None or cur[0] is not _ci_cfd_run or cur[1][0] is not rec
            or bank.executor._scratch_generation != rec.gen or _CF_VIEW_EPOCH[0] != rec.epoch):
        _CI_CFD_INFO["stale"] += 1
        raise RuntimeError("Claude-I CFD: deferred E1 root is stale: %r" % (key,))
    bank.require()
    del bank.plain[key]
    with _CiCfdWindow(bank.executor):
        _ci_cfd_e1_classical_parent(bank, *key)                     # the classical chain: CFE1 bind + E1FW
    _CI_CFD_INFO["bound"] += 1
    return bank.plain[key]


_ci_cfd_bind_parent = _ci_cf_bind


def _ci_cf_bind(self, xshape, yshape, lev, root_key):
    if _CI_CFD_ARM[0] is self and root_key in _CI_CFD_KEYS and _CP_IN_SETUP[0]:
        _CI_CFD_INFO["deferred"] += 1
        if len(_CI_CFD_INFO["keys"]) < 64:                          # bounded across re-setups (R8d: key tuples only, no arrays)
            _CI_CFD_INFO["keys"].append(root_key)
        return (_ci_cfd_run, (_CiCfdRec(self, root_key, self._scratch_generation, "owner"),), ((),))
    return _ci_cfd_bind_parent(self, xshape, yshape, lev, root_key)


_ci_cfd_prepare_parent = _StrassenV29.prepare_callplans


def _ci_cfd_prepare_callplans(self, roots):
    armed = bool(_CI_CFD and _CI_CFD_KEYS and type(self) is _BDPackedStrassen and getattr(self, "_colored_active", False))
    prev = _CI_CFD_ARM[0]
    _CI_CFD_ARM[0] = self if armed else None
    try:
        return _ci_cfd_prepare_parent(self, roots)
    finally:
        _CI_CFD_ARM[0] = prev


_StrassenV29.prepare_callplans = _ci_cfd_prepare_callplans
_ci_cfd_e1_classical_parent = _BE1Plans.classical


def _ci_cfd_e1_classical(self, m, k, n, level):
    key = (m, k, n, level)
    if not (_CI_CFD and _CP_IN_SETUP[0] and key in _CI_CFD_E1_KEYS) or key in self.plain:
        return _ci_cfd_e1_classical_parent(self, m, k, n, level)
    for role, P, shape, _paired in _be1_geometry(m, k, n, level):   # the parent's metadata check, kept eager
        e = self.executor.pool.get((role, P))
        if (e is None or e[0].size < math.prod(shape)) and not _ci_acap_outer_ok(role, P, shape):
            raise RuntimeError('E1 classical plan exceeds parent backing: ' + repr((role, P, shape)))
    self.plain[key] = (_ci_cfd_run, (_CiCfdRec(self, key, self.executor._scratch_generation, "e1"),), ((),))
    self.require()
    _CI_CFD_INFO["deferred"] += 1
    if len(_CI_CFD_INFO["keys"]) < 64:
        _CI_CFD_INFO["keys"].append(("e1",) + key)
    return key


_BE1Plans.classical = _ci_cfd_e1_classical
