_CF_RG_Q = (0.00768, 0.02894, 0.03827, 0.03908, 0.04448, 0.05276, 0.06404, 0.07530, 0.08815, 0.09994, 0.09723, 0.09372, 0.08931, 0.07423, 0.07391, 0.03170)
_CF_RG_Q1_PRE = 0.00141
_CF_RG_Q1 = (0.00811, 0.03310, 0.04281, 0.04265, 0.04674, 0.05757, 0.06937, 0.07040, 0.07960, 0.08927, 0.08113, 0.08795, 0.09040, 0.08045, 0.08309, 0.03595)
_CF_RG_S = {'zero': (0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.03000, 0.03000, 0.03000, 0.03000, 0.03000, 0.03000, 0.03000, 0.03000, 0.03000, 0.03000, 0.00000),
            'rr': (0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.06268, 0.05212, 0.09867, 0.14884, 0.14850, 0.15345, 0.10875, 0.00000, 0.00000, 0.00000),
            'fbw2': (0.00000, 0.00000, 0.19003, 0.19511, 0.20547, 0.10896, 0.06731, 0.10572, 0.14730, 0.13350, 0.13175, 0.10323, 0.11475, 0.14789, 0.14778, 0.17700),
            'head': (0.00000, 0.00000, 0.09806, 0.10068, 0.08806, 0.07446, 0.10185, 0.08469, 0.06664, 0.05908, 0.05895, 0.06091, 0.06580, 0.08696, 0.08445, 0.15653)}
_CF_RG_S1 = {'zero': (0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.02000, 0.02000, 0.02000, 0.02000, 0.02000, 0.02000, 0.02000, 0.02000, 0.02000, 0.02000, 0.00000),
             'rr': (0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000, 0.00000),
             'fbw2': (0.00000, 0.00000, 0.18110, 0.18062, 0.19695, 0.09942, 0.06156, 0.10497, 0.14979, 0.14107, 0.14405, 0.11410, 0.11604, 0.13154, 0.13476, 0.16110),
             'head': (0.00000, 0.00000, 0.09345, 0.09321, 0.08441, 0.06795, 0.10619, 0.08703, 0.07014, 0.06506, 0.06671, 0.06772, 0.06888, 0.08034, 0.07999, 0.16055)}
_CF_RG_LEVERS = ('zero', 'rr', 'fbw2', 'head')
_CF_RG_ZNAMES = ('_CR_' + 'G2', '_CI_RRLEV_' + 'LMAX')   # v7: built at run time
_CF_RG_ZOFF = (False, -1)
_CF_RG_TAIL = 0.00000    # v6: table units after the last layer start that the per-layer shares miss (steady)
_CF_RG_TAIL1 = 0.08000   # v6: same for the first predict after a setup
_CF_RG_RNOM = 0.3720   # v6: the chain's official median residual (s) of a steady predict
_CF_RG_RNOM1 = 0.3780   # v6: same for the first predict after a setup
_CF_RG_WNOM = 106.89   # v6: the chain's official median predict wall (s)
_CF_RG_CUM = (0.00014, 0.00461, 0.02602, 0.06175, 0.10765, 0.16335, 0.22691, 0.29653, 0.37738, 0.46656, 0.55702, 0.64746, 0.73260, 0.81858, 0.89304, 0.96847)   # v6: share of the predict wall elapsed at each layer start (steady)
_CF_RG_WON = 1   # v6: 1 = use the wall rate as a floor under the meter rate
_CF_RG_WLI = 8   # v8: first layer start at which the wall rate is used (official wall profile +-4 % from L8)
_CF_RG_WDISC = 0.050   # v8: wall slowness discount (profile / per-net compute spread)
_CF_RG_STICKY_REL = 1.0370   # v9: arm RR for the next steady predict when r_eq >= this x RNOM
_CF_RG_STICKY_WREL = 1.0600   # v9: ... or when the last predict's wall >= this x WNOM (wall follows residual at r = 0.97)
_CF_RG_STICKY = {'arm': False, 'n0': None, 'd0': None, 'w0': None, 'last': None}


def _cf_rg_prefix(q, s):
    """Prefix sums: P[l] = sum of q[m] for m < l, and per lever sum of q[m] * s[m] (so a projection costs O(levers))."""
    pq, acc = [0.0], 0.0
    for x in q:
        acc += x
        pq.append(acc)
    ps = {}
    for k in _CF_RG_LEVERS:
        p, acc = [0.0], 0.0
        for x, y in zip(q, s[k]):
            acc += x * y
            p.append(acc)
        ps[k] = tuple(p)
    return tuple(pq), ps


_CF_RG_P = _cf_rg_prefix(_CF_RG_Q, _CF_RG_S)
_CF_RG_P1 = _cf_rg_prefix(_CF_RG_Q1, _CF_RG_S1)
_CF_RG_STATE = {'first': False, 'zero': None, 'zsaved': None, 'rr': None, 'fbw2': None, 'head': None, 'nocorr': None, 'log': [], 'prev': None, 'dead': False}


def _cf_rg_zero_ok():
    g = globals()
    return any(nm in g for nm in _CF_RG_ZNAMES)


def _cf_rg_zero_on():
    """v7: lever 0 -- the A9 request-adding pieces off for the rest of this predict (values saved once, restored by _cf_rg_zero_off)."""
    g = globals(); st = _CF_RG_STATE
    if st['zsaved'] is None:
        st['zsaved'] = tuple((nm in g, g.get(nm)) for nm in _CF_RG_ZNAMES)
    for nm, off in zip(_CF_RG_ZNAMES, _CF_RG_ZOFF):
        if nm in g:
            g[nm] = off


def _cf_rg_zero_off():
    st = _CF_RG_STATE; z = st['zsaved']
    if z is not None:
        g = globals()
        for nm, (had, v) in zip(_CF_RG_ZNAMES, z):
            if had:
                g[nm] = v
        st['zsaved'] = None   # v8: the record st['zero'] stays (cleared at predict start / restore / a new pass)


def _cf_rg_now():
    """Live billed residual (s) of the open budget context: flopscope's own meter, read-only, no request.  None if unavailable."""
    try:
        ctx = _cf_rg_budget._active_context
        if ctx is None:
            return None
        v = ctx.residual_wall_time_s
        return None if v is None else float(v)
    except Exception:  # noqa: BLE001
        return None


def _cf_rg_own():
    """v9: wall - dispatch since the outer predict started (BudgetContext's residual definition from the client's own
    accumulator); None if unavailable."""
    sk = _CF_RG_STICKY
    try:
        if sk['n0'] is None or sk['d0'] is None:
            return None
        v = (_cf_rg_pcn() - sk['n0'] - (_cf_rg_tdn() - sk['d0'])) * 1e-9
        return v if v >= 0.0 else 0.0    # v9c: floored at 0
    except Exception:  # noqa: BLE001
        return None


def _cf_rg_units(P, lo, hi, st):
    """Residual units of layers lo..hi-1 with each lever on from the layer recorded in st (None = off)."""
    pq, ps = P
    u = pq[hi] - pq[lo]
    for k in _CF_RG_LEVERS:
        a = st[k]
        if a is not None and a < hi:
            u -= ps[k][hi] - ps[k][max(lo, a)]
    return u


def _cf_rg_step(li):
    global NO_CORR
    st = _CF_RG_STATE
    st['first'] = bool(_CF_DL_FIRST[0] and _CF_DL_FIRST_LEFT[0] == _CF_DL_FIRST_N)   # v3: phase of THIS pass (a restore re-arms it)
    if _CF_RG_STICKY['arm'] and not st['first'] and st['rr'] is None and not _CF_RR_PLAIN[0]:
        _CF_RR_PLAIN[0] = True                       # v9 STICKY: the previous predict of this worker ended slow
        st['rr'] = li
        st['log'].append((int(li), 'rr-sticky', 0.0, 0.0, 0.0, None))
    r = _cf_rg_now()
    if r is not None and not ((r - r) == 0.0 and r >= 0.0):
        r = None                         # v9c: a non-finite / negative meter is no meter
    src = 'ctx'
    dl = _CF_DL_STATE
    if st['prev'] is not None and li <= st['prev'][0]:   # a new pass inside the same predict (safety-net re-predict)
        st['prev'] = None
        if st['fbw2'] is not None and dl['level'] < 1:
            st['fbw2'] = None
        if st['rr'] is not None and not _CF_RR_PLAIN[0]:
            st['rr'] = None
        if st['head'] is not None and not NO_CORR:
            st['head'] = None
        if st['zero'] is not None and st['zsaved'] is None:   # v8: lever 0 was undone with the deadline guard's exit
            st['zero'] = None
    if st['fbw2'] is None and dl['level'] >= 1:     # switched on by the deadline guard at an earlier layer start
        st['fbw2'] = dl['li'] if isinstance(dl.get('li'), int) else max(li - 1, 0)
    if st['rr'] is None and _CF_RR_PLAIN[0]:
        st['rr'] = 0 if st['first'] else li
    P, pre = (_CF_RG_P1, _CF_RG_Q1_PRE) if st['first'] else (_CF_RG_P, _CF_RG_Q_PRE)
    done = pre + _cf_rg_units(P, 0, li, st)
    if done <= 1e-6:
        return
    tail = _CF_RG_TAIL1 if st['first'] else _CF_RG_TAIL
    kw = None
    rate_w = None
    if (_CF_RG_WON and li >= _CF_RG_WLI and dl.get('t0') is not None
            and _CF_RG_CUM[li] > 1e-3):   # v6/v8: wall-clock slowness of this worker, discounted
        kw = (_cf_dl_time.perf_counter() - dl['t0']) / (_CF_RG_CUM[li] * _CF_RG_WNOM) * (1.0 - _CF_RG_WDISC)
        u_tot = pre + P[0][16] + tail
        rate_w = (_CF_RG_RNOM1 if st['first'] else _CF_RG_RNOM) * kw / u_tot
    if r is None:
        r = _cf_rg_own()                 # v9: the client's own accounting stands in for an empty meter
        src = 'own'
    if r is None:
        if rate_w is None:
            return
        r = rate_w * done                # v8: no meter reading -> the wall estimate of the residual so far
        src = 'wall'
    st['src'] = src
    rate = r / done
    if rate_w is not None and rate_w > rate:
        rate = rate_w
    prev = st['prev']
    st['prev'] = (li, r, done)
    if _CF_RG_RECENT > 0.0 and li >= _CF_RG_RECENT_LI and prev is not None and prev[0] == li - 1 and done - prev[2] > 1e-6:
        recent = (r - prev[1]) / (done - prev[2])
        if recent > rate:
            rate += _CF_RG_RECENT * (recent - rate)
    proj = r + rate * (_cf_rg_units(P, li, 16, st) + tail)
    p0 = proj
    m = _CF_RG_M[li]
    t2 = _CF_RG_T2F if st['first'] else _CF_RG_T2
    for k, t in (('rr', _CF_RG_T1 + m), ('zero', _CF_RG_T0 + m), ('fbw2', t2 + m), ('head', _CF_RG_T3 + m)):   # v9: rr first; v8: margin on all
        if proj <= t:
            break
        if st[k] is not None:
            continue
        if k == 'zero' and (st['first'] or not _cf_rg_zero_ok()):   # v9c: nothing to save on the first predict
            continue
        if li + 1 < 16:                  # just in time: if switching on one layer later still meets t, wait
            st[k] = li + 1
            later = r + rate * (_cf_rg_units(P, li, 16, st) + tail)
            st[k] = None
            if later <= t - (_CF_RG_JD if k != 'head' else 0.0):
                break
        if k == 'zero':
            _cf_rg_zero_on()
        elif k == 'rr':
            _CF_RR_PLAIN[0] = True
        elif k == 'fbw2':
            if dl['level'] < 1:
                _cf_dl_enter(1, li, -3.0)
        else:
            if st['nocorr'] is None:
                st['nocorr'] = NO_CORR
            NO_CORR = True
        st[k] = li
        proj = r + rate * (_cf_rg_units(P, li, 16, st) + tail)
        st['log'].append((int(li), k, round(r, 5), round(p0, 5), round(proj, 5), None if kw is None else round(kw, 4), src))


_cf_rg_layer_parent = _be1_layer


def _be1_layer(core, li, *args):
    if (_CF_RG_ON and _CF_DL_ON and _CF_DL_STATE['t0'] is not None and _CF_RG_MIN_LI <= li < _CF_RG_NL
            and len(args) >= 2 and args[0] == 1024 and args[1] == _CF_RG_NL and not _CF_RG_STATE['dead']):
        try:
            _cf_rg_step(li)
        except Exception:  # noqa: BLE001
            _CF_RG_STATE['dead'] = True     # never let the guard break a predict: off for the rest of this one
    return _cf_rg_layer_parent(core, li, *args)


def _cf_rg_undo_head():
    """v3: NO_CORR back to the value the head lever saved (no-op when the lever is off)."""
    global NO_CORR
    st = _CF_RG_STATE
    if st['nocorr'] is not None:
        NO_CORR = st['nocorr']
        st['nocorr'] = None   # v9c: the head record stays (sticky r_eq); cleared at predict start / restore / new pass


_cf_rg_dl_exit_parent = _cf_dl_exit


def _cf_dl_exit():
    """v3: the head lever is undone with the deadline guard's switches (this exit runs in the deadline guard's finally,
    before an exception reaches the safety net), then the deadline guard restores RR / FBW2 / caps as before."""
    try:
        _cf_rg_undo_head()
        _cf_rg_zero_off()
    finally:
        _cf_rg_dl_exit_parent()


_cf_rg_restore_parent = _cf_guard_restore


def _cf_guard_restore(self):
    """v3: RG-owned flags back to their shipped values before the safety net re-runs setup; the retry re-arms on its own."""
    try:
        _cf_rg_undo_head()
        _cf_rg_zero_off()
        st = _CF_RG_STATE
        st['zero'] = st['rr'] = st['fbw2'] = st['head'] = None    # the deadline guard's exit already undid RR / FBW2: the retry re-syncs
        st['prev'] = None
    except Exception:  # noqa: BLE001
        pass
    return _cf_rg_restore_parent(self)


_cf_rg_predict_parent = Estimator.predict


def _cf_rg_predict(self, mlp, budget):
    global NO_CORR
    st = _CF_RG_STATE
    _cf_rg_zero_off()
    st['zero'] = st['rr'] = st['fbw2'] = st['head'] = st['nocorr'] = None
    st['src'] = None
    st['prev'] = None
    st['dead'] = False
    st['log'] = []
    st['first'] = bool(_CF_DL_FIRST[0] and _CF_DL_FIRST_LEFT[0] == _CF_DL_FIRST_N)
    sk = _CF_RG_STICKY
    try:                                             # v9b: the wall-rule origin first, on its own
        sk['w0'] = _cf_dl_time.perf_counter()        # wall rule clock (slowx copies scale it on purpose)
    except Exception:  # noqa: BLE001
        sk['w0'] = None
    try:                                             # v9: own-meter origin (outer predict start)
        sk['n0'] = _cf_rg_pcn()
        sk['d0'] = _cf_rg_tdn()
    except Exception:  # noqa: BLE001
        sk['n0'] = sk['d0'] = None
    try:
        return _cf_rg_predict_parent(self, mlp, budget)
    finally:
        if st['nocorr'] is not None:
            NO_CORR = st['nocorr']
            st['nocorr'] = None
        try:                                         # v9 STICKY: arm / disarm the next steady predict of this worker
            r_end = _cf_rg_now()
            if r_end is not None and not ((r_end - r_end) == 0.0 and r_end >= 0.0):
                r_end = None             # v9c
            if r_end is None:
                r_end = _cf_rg_own()
            P, pre = (_CF_RG_P1, _CF_RG_Q1_PRE) if st['first'] else (_CF_RG_P, _CF_RG_Q_PRE)
            su = dict(st)
            if st['first'] and st['rr'] == 0:
                su['rr'] = None                      # the first predict's RR is by design (RNOM1 includes it)
            u_used = pre + _cf_rg_units(P, 0, 16, su)
            u_full = pre + P[0][16]
            r_eq = None if r_end is None else r_end * u_full / max(u_used, 1e-6)
            rn = _CF_RG_RNOM1 if st['first'] else _CF_RG_RNOM
            wrel = ((_cf_dl_time.perf_counter() - sk['w0']) / _CF_RG_WNOM) if sk['w0'] is not None else 0.0
            sk['arm'] = bool((r_eq is not None and r_eq >= _CF_RG_STICKY_REL * rn) or wrel >= _CF_RG_STICKY_WREL)
            sk['last'] = (None if r_end is None else round(r_end, 5), None if r_eq is None else round(r_eq, 5), round(wrel, 4), sk['arm'])
        except Exception:  # noqa: BLE001
            sk['arm'] = False
        _z = st['zero']
        _cf_rg_zero_off()
        try:
            self._cf_rg_last = dict(meter=st.get('src'), sticky=_CF_RG_STICKY['last'], first=st['first'], zero=_z, rr=st['rr'], fbw2=st['fbw2'], head=st['head'], dead=st['dead'], log=list(st['log']))
        except Exception:  # noqa: BLE001
            pass


Estimator.predict = _cf_rg_predict
# ===================== end Claude-F RG =====================
